function toggleMobileSidebar() {
    const sidebar = document.querySelector('.sidebar');
    const overlay = document.getElementById('sidebarOverlay');
    if (sidebar) sidebar.classList.toggle('show');
    if (overlay) overlay.classList.toggle('show');
}

function closeMobileSidebar() {
    const sidebar = document.querySelector('.sidebar');
    const overlay = document.getElementById('sidebarOverlay');
    if (sidebar) sidebar.classList.remove('show');
    if (overlay) overlay.classList.remove('show');
}

function showPage(pageId, element) {
    // 🚀 1. ด่านตรวจสิทธิ์ขั้นสูงสุด: ตรวจสอบสิทธิ์ก่อนเปิดหน้าเสมอ!
    const currentUserStr = localStorage.getItem('clinicUser');
    if (currentUserStr) {
        try {
            const currentUser = JSON.parse(currentUserStr);
            const permissions = Array.isArray(currentUser.permissions) ? currentUser.permissions : [];
            const isAdmin = currentUser.role === 'admin' || currentUser.role === 'ผู้ดูแลระบบ' || permissions.includes('all');

            if (!isAdmin) {
                // เช็คว่าพนักงานคนนี้มีสิทธิ์ในหน้าที่กำลังจะเปิดหรือไม่
                const hasAccess = permissions.some(p => p.startsWith(pageId));

                if (!hasAccess) {
                    // ถ้าไม่มีสิทธิ์! ให้หาหน้าแรกที่เขามีสิทธิ์แล้วสลับไปหน้านั้นแทน
                    const allMenuKeys = [
                        'dashboard', 'appointments', 'booking', 'registration', 'triage', 'doctor',
                        'payment', 'lab', 'queue', 'prescription', 'pharmacy', 'history',
                        'billing', 'expenses', 'doctor-reports', 'services', 'stock-drugs', 'stock-equip', 'staff', 'referrals', 'daily-reports', 'clinic-settings'
                    ];
                    const firstAllowed = allMenuKeys.find(key => permissions.some(p => p.startsWith(key)));

                    if (firstAllowed) {
                        pageId = firstAllowed;
                        element = document.getElementById(`nav-${firstAllowed}`);
                    } else {
                        // ถ้าไม่มีสิทธิ์เลยสักหน้าเดียว ให้หยุดการทำงานทันที
                        console.warn("Access Denied: ไม่มีสิทธิ์การเข้าถึง");
                        return;
                    }
                }
            }
        } catch (err) {
            console.error("Permission Security Error:", err);
        }
    }

    const targetPage = document.getElementById(pageId);
    if (!targetPage) return;

    // 2. ซ่อนเนื้อหาทุกหน้าก่อน
    document.querySelectorAll('.page-section').forEach(p => {
        p.classList.remove('active');
        // ใช้ cssText บังคับซ่อนเด็ดขาด
        p.style.cssText = 'display: none !important; visibility: hidden !important; opacity: 0 !important;';
    });

    // 3. แสดงเฉพาะหน้าที่ได้รับอนุญาต
    targetPage.classList.add('active');
    if (pageId === 'booking') {
        if (window.innerWidth <= 991.98) {
            targetPage.style.cssText = 'display: block !important; visibility: visible !important; opacity: 1 !important; position: fixed !important; top: 56px !important; left: 0 !important; right: 0 !important; bottom: 0 !important; width: 100vw !important; height: calc(100dvh - 56px) !important; max-height: calc(100dvh - 56px) !important; padding: 0 !important; margin: 0 !important; overflow: hidden !important; z-index: 1020 !important;';
            const frame = document.getElementById('marketingFrame');
            if (frame) {
                frame.style.cssText = 'width: 100% !important; height: 100% !important; min-height: 100% !important; max-height: 100% !important; border: none !important; margin: 0 !important; padding: 0 !important; display: block !important; border-radius: 0 !important;';
            }
        } else {
            targetPage.style.cssText = 'display: block !important; visibility: visible !important; opacity: 1 !important; width: 100% !important; height: 100% !important; padding: 0 !important; margin: 0 !important;';
            const frame = document.getElementById('marketingFrame');
            if (frame) frame.style.cssText = '';
        }
    } else {
        targetPage.style.cssText = 'display: block !important; visibility: visible !important; opacity: 1 !important;';
    }

    // 4. อัปเดตสถานะเมนูด้านซ้ายมือให้เป็น Active
    document.querySelectorAll('#sidebarNav .nav-link, .sidebar a.nav-link').forEach(l => l.classList.remove('active'));
    if (element) {
        element.classList.add('active');
    } else {
        const navEl = document.getElementById('nav-' + pageId);
        if (navEl) navEl.classList.add('active');
    }

    // 5. อัปเดตชื่อหน้าใน Mobile Top Header
    const mobileTitleEl = document.getElementById('mobilePageHeaderTitle');
    if (mobileTitleEl) {
        if (element) {
            const labelText = element.textContent.trim();
            if (labelText) mobileTitleEl.textContent = labelText;
        } else {
            const activeNav = document.querySelector(`#sidebarNav a[onclick*="${pageId}"]`);
            if (activeNav) {
                const labelText = activeNav.textContent.trim();
                if (labelText) mobileTitleEl.textContent = labelText;
            }
        }
    }

    // 5.1 ควบคุมการล็อกหน้าจอสำหรับหน้า Booking บนมือถือ (ป้องกัน Double Scroll)
    if (document.body) {
        document.body.classList.toggle('page-is-booking', pageId === 'booking');
    }
    const contentAreaEl = document.querySelector('.content-area');
    if (contentAreaEl) {
        contentAreaEl.classList.toggle('is-booking-active', pageId === 'booking');
        if (pageId === 'booking') {
            contentAreaEl.scrollTop = 0;
        }
    }

    // 6. ปิดเมนู Sidebar บนสมาร์ทโฟนเมื่อกดเลือกหน้า
    if (typeof closeMobileSidebar === 'function') closeMobileSidebar();

    // 7. โหลดข้อมูลอัตโนมัติเมื่อกดเข้าสู่แต่ละหน้า
    try {
        if (pageId === 'dashboard') {
            try {
                const frame = document.getElementById('dashboardFrame');
                if (frame && frame.contentWindow) {
                    if (typeof frame.contentWindow.updateDashboardStats === 'function') {
                        frame.contentWindow.updateDashboardStats();
                    }
                    if (typeof frame.contentWindow.renderCalendar === 'function') {
                        frame.contentWindow.renderCalendar();
                    }
                }
            } catch (dErr) { }
            if (typeof window.renderCalendar === 'function') window.renderCalendar();
            if (typeof window.updateDashboardStats === 'function') window.updateDashboardStats();
        } else if (pageId === 'booking') {
            try {
                const frame = document.getElementById('marketingFrame');
                if (frame && frame.contentWindow) {
                    if (typeof frame.contentWindow.setDateFilterMode === 'function') {
                        frame.contentWindow.setDateFilterMode('today');
                    }
                    if (typeof frame.contentWindow.loadLivePatientData === 'function') {
                        frame.contentWindow.loadLivePatientData();
                    }
                    frame.contentWindow.postMessage({ type: 'FETCH_PATIENTS' }, '*');
                }
            } catch (fErr) { }
        } else if (pageId === 'stock-drugs') {
            if (typeof loadStockList === 'function') loadStockList();
        } else if (pageId === 'pharmacy') {
            if (typeof loadPharmacyQueue === 'function') loadPharmacyQueue();
            if (typeof loadPharmacyHistory === 'function') loadPharmacyHistory();
        } else if (pageId === 'history') {
            const hStart = document.getElementById('historyStartDate');
            const hEnd = document.getElementById('historyEndDate');
            const todayStr = (typeof getVientianeDateRange === 'function')
                ? getVientianeDateRange('today').startStr
                : new Date().toLocaleDateString('en-CA');
            if (hStart) hStart.value = todayStr;
            if (hEnd) hEnd.value = todayStr;
            if (typeof loadPatientHistory === 'function') loadPatientHistory(false);
        } else if (pageId === 'stock-equip') {
            if (typeof loadSupplyItems === 'function') loadSupplyItems();
            if (typeof loadSupplyRequests === 'function') loadSupplyRequests();
        } else if (pageId === 'staff') {
            if (typeof loadStaffUsers === 'function') loadStaffUsers();
        } else if (pageId === 'referrals') {
            if (typeof loadReferralData === 'function') loadReferralData();
        } else if (pageId === 'daily-reports') {
            if (typeof loadDailyReport === 'function') loadDailyReport();
            if (typeof loadDailyClinicReport === 'function') loadDailyClinicReport();
        } else if (pageId === 'clinic-settings') {
            try {
                const frame = document.getElementById('settingFrame');
                if (frame && frame.contentWindow && typeof frame.contentWindow.loadSettings === 'function') {
                    frame.contentWindow.loadSettings();
                }
            } catch (sErr) { }
        } else if (pageId === 'doctor-reports') {
            try {
                const frame = document.getElementById('doctorReportFrame');
                if (frame) {
                    const targetSrc = frame.getAttribute('data-src') || 'report.html?v=3.7';
                    if (!frame.src || frame.src.endsWith('about:blank') || !frame.getAttribute('data-loaded')) {
                        frame.src = targetSrc;
                        frame.setAttribute('data-loaded', 'true');
                    } else if (frame.contentWindow && typeof frame.contentWindow.loadReportData === 'function') {
                        frame.contentWindow.loadReportData();
                    }
                }
            } catch (rErr) { }
        } else if (pageId === 'appointments') {
            if (typeof loadAppointments === 'function') loadAppointments();
        } else if (pageId === 'services') {
            if (typeof loadServicesData === 'function') loadServicesData();
        } else if (pageId === 'registration') {
            if (typeof loadPatients === 'function') loadPatients();
        } else if (pageId === 'triage') {
            if (typeof loadTriage === 'function') loadTriage();
            if (typeof loadTriageHistory === 'function') loadTriageHistory();
        } else if (pageId === 'doctor') {
            if (typeof loadDoctorQueue === 'function') loadDoctorQueue();
        } else if (pageId === 'prescription') {
            if (typeof loadPrescriptionList === 'function') loadPrescriptionList();
        } else if (pageId === 'queue') {
            if (typeof loadQueueList === 'function') loadQueueList();
        } else if (pageId === 'payment') {
            if (typeof loadPaymentQueue === 'function') loadPaymentQueue();
        } else if (pageId === 'lab') {
            if (typeof loadLabQueue === 'function') loadLabQueue();
        } else if (pageId === 'billing') {
            if (typeof loadBills === 'function') loadBills();
        } else if (pageId === 'expenses') {
            if (typeof loadExpenses === 'function') loadExpenses();
        }

        if (typeof applyClinicLanguage === 'function') {
            applyClinicLanguage();
        }
    } catch (e) {
        console.warn('Error loading section data for ' + pageId, e);
    }
}

