// =====================================
// Centralized Real-time Synchronization Hub (All Tables)
// =====================================
let _realtimeDebounceTimers = {};

function debounceRealtime(key, callback, delay = 250) {
    if (_realtimeDebounceTimers[key]) {
        clearTimeout(_realtimeDebounceTimers[key]);
    }
    _realtimeDebounceTimers[key] = setTimeout(() => {
        try {
            callback();
        } catch (e) {
            console.warn('Realtime callback error for ' + key, e);
        }
    }, delay);
}

function initClinicRealtimeHub() {
    if (typeof _supabase === 'undefined' || !_supabase) return;

    try {
        console.log('⚡ Initializing Clinic Central Real-time Subscriptions across all tables...');

        // 1. Channel สำหรับตาราง VISITS (คัดกรอง, ตรวจแพทย์, แล็บ, จัดคิว, อ่านผล/จัดยา, จ่ายยา, ชำระเงิน, ประวัติ)
        _supabase.channel('realtime_visits')
            .on('postgres_changes', { event: '*', schema: 'public', table: 'visits' }, (payload) => {
                console.log('⚡ [Realtime: Visits Update]', payload.eventType, payload.new || payload.old);
                debounceRealtime('visits', () => {
                    if (typeof loadTriage === 'function') loadTriage();
                    if (typeof loadTriageHistory === 'function') loadTriageHistory();
                    if (typeof loadDoctorQueue === 'function') loadDoctorQueue();
                    if (typeof loadLabQueue === 'function') loadLabQueue();
                    if (typeof loadQueueList === 'function') loadQueueList();
                    if (typeof loadPrescriptionList === 'function') loadPrescriptionList();
                    if (typeof loadPharmacyQueue === 'function') loadPharmacyQueue();
                    if (typeof loadPharmacyHistory === 'function') loadPharmacyHistory();
                    if (typeof loadPaymentQueue === 'function') loadPaymentQueue();
                    if (typeof loadPatientHistory === 'function') loadPatientHistory();
                    if (typeof loadPatients === 'function') loadPatients();
                    if (typeof loadBills === 'function') loadBills();
                    if (typeof loadDailyClinicReport === 'function') loadDailyClinicReport();
                    if (typeof updateDashboardStats === 'function') updateDashboardStats();
                }, 200);
            })
            .subscribe((status) => {
                if (status === 'SUBSCRIBED') console.log('✅ Realtime Active: visits table');
            });

        // 2. Channel สำหรับตาราง APPOINTMENTS (นัดหมายล่วงหน้า & ปฏิทิน Dashboard)
        _supabase.channel('realtime_appointments')
            .on('postgres_changes', { event: '*', schema: 'public', table: 'appointments' }, (payload) => {
                console.log('⚡ [Realtime: Appointments Update]', payload.eventType);
                debounceRealtime('appointments', () => {
                    if (typeof loadAppointments === 'function') loadAppointments();
                    if (typeof window.renderCalendar === 'function') window.renderCalendar();
                    if (typeof updateDashboardStats === 'function') updateDashboardStats();
                }, 200);
            })
            .subscribe((status) => {
                if (status === 'SUBSCRIBED') console.log('✅ Realtime Active: appointments table');
            });

        // 3. Channel สำหรับตาราง PATIENTS (ทะเบียนผู้ป่วย)
        _supabase.channel('realtime_patients')
            .on('postgres_changes', { event: '*', schema: 'public', table: 'patients' }, (payload) => {
                console.log('⚡ [Realtime: Patients Update]', payload.eventType);
                debounceRealtime('patients', () => {
                    if (typeof loadPatients === 'function') loadPatients();
                    if (typeof loadPaymentQueue === 'function') loadPaymentQueue();
                    if (typeof loadLabQueue === 'function') loadLabQueue();
                    if (typeof loadDoctorQueue === 'function') loadDoctorQueue();
                    if (typeof updateDashboardStats === 'function') updateDashboardStats();
                }, 200);
            })
            .subscribe((status) => {
                if (status === 'SUBSCRIBED') console.log('✅ Realtime Active: patients table');
            });

        // 4. Channel สำหรับตาราง MEDICINES (คลังยา & สต็อกยา)
        _supabase.channel('realtime_medicines')
            .on('postgres_changes', { event: '*', schema: 'public', table: 'medicines' }, (payload) => {
                console.log('⚡ [Realtime: Medicines Update]', payload.eventType);
                debounceRealtime('medicines', () => {
                    if (typeof loadStockList === 'function') loadStockList();
                    if (typeof loadMedicines === 'function') loadMedicines();
                    if (typeof populateRxMedDropdown === 'function') populateRxMedDropdown();
                }, 200);
            })
            .subscribe((status) => {
                if (status === 'SUBSCRIBED') console.log('✅ Realtime Active: medicines table');
            });

        // 5. Channel สำหรับตาราง SUPPLIES & SUPPLY_REQUESTS (คลังพัสดุ & เบิกพัสดุ)
        _supabase.channel('realtime_supplies')
            .on('postgres_changes', { event: '*', schema: 'public', table: 'supplies' }, () => {
                debounceRealtime('supplies', () => {
                    if (typeof loadSupplyItems === 'function') loadSupplyItems();
                }, 200);
            })
            .on('postgres_changes', { event: '*', schema: 'public', table: 'supply_requests' }, () => {
                debounceRealtime('supply_requests', () => {
                    if (typeof loadSupplyRequests === 'function') loadSupplyRequests();
                }, 200);
            })
            .subscribe();

        // 6. Channel สำหรับตาราง BILLS & EXPENSES (ระบบบิล & รายจ่ายประจำวัน)
        _supabase.channel('realtime_finance')
            .on('postgres_changes', { event: '*', schema: 'public', table: 'bills' }, (payload) => {
                console.log('⚡ [Realtime: Bills Update]', payload.eventType);
                debounceRealtime('bills', () => {
                    if (typeof loadBills === 'function') loadBills();
                    if (typeof loadDailyClinicReport === 'function') loadDailyClinicReport();
                    if (typeof loadPaymentQueue === 'function') loadPaymentQueue();
                    if (typeof updateDashboardStats === 'function') updateDashboardStats();
                }, 200);
            })
            .on('postgres_changes', { event: '*', schema: 'public', table: 'clinic_bills' }, (payload) => {
                debounceRealtime('bills', () => {
                    if (typeof loadBills === 'function') loadBills();
                    if (typeof loadDailyClinicReport === 'function') loadDailyClinicReport();
                    if (typeof updateDashboardStats === 'function') updateDashboardStats();
                }, 200);
            })
            .on('postgres_changes', { event: '*', schema: 'public', table: 'clinic_expenses' }, (payload) => {
                debounceRealtime('expenses', () => {
                    if (typeof loadExpenses === 'function') loadExpenses();
                    if (typeof loadDailyClinicReport === 'function') loadDailyClinicReport();
                    if (typeof updateDashboardStats === 'function') updateDashboardStats();
                }, 200);
            })
            .subscribe((status) => {
                if (status === 'SUBSCRIBED') console.log('✅ Realtime Active: bills and expenses tables');
            });

        // 7. Channel สำหรับตาราง STAFF_USERS & STAFF (พนักงาน & สิทธิ์ผู้ใช้)
        _supabase.channel('realtime_staff')
            .on('postgres_changes', { event: '*', schema: 'public', table: 'staff_users' }, () => {
                debounceRealtime('staff', () => {
                    if (typeof loadStaffUsers === 'function') loadStaffUsers();
                    if (typeof loadQueueList === 'function') loadQueueList();
                }, 200);
            })
            .subscribe();

        // 8. Channel สำหรับตาราง SERVICES (รายการบริการตรวจ)
        _supabase.channel('realtime_services')
            .on('postgres_changes', { event: '*', schema: 'public', table: 'services' }, () => {
                debounceRealtime('services', () => {
                    if (typeof loadServicesData === 'function') loadServicesData();
                }, 200);
            })
            .subscribe();

        // 9. Channel สำหรับตาราง COMMISSION_LOGS (ประวัติค่าคอมมิชชั่น & ปันผล แบบ Real-time)
        _supabase.channel('realtime_commission_logs')
            .on('postgres_changes', { event: '*', schema: 'public', table: 'commission_logs' }, (payload) => {
                debounceRealtime('commission_logs', () => {
                    if (typeof loadReferralData === 'function') loadReferralData();
                    if (typeof loadDailyClinicReport === 'function') loadDailyClinicReport();
                }, 150);
            })
            .subscribe();

        // 10. Channel สำหรับตาราง COMMISSION_SETTINGS (การตั้งค่าปันผลแบบ Real-time)
        _supabase.channel('realtime_commission_settings')
            .on('postgres_changes', { event: '*', schema: 'public', table: 'commission_settings' }, (payload) => {
                debounceRealtime('commission_settings', () => {
                    if (typeof loadCommissionToggleStates === 'function') loadCommissionToggleStates();
                    if (typeof loadItemCommissionSettings === 'function') loadItemCommissionSettings();
                    if (typeof loadReferralData === 'function') loadReferralData();
                }, 150);
            })
            .subscribe();

        // 11. Channel สำหรับตาราง REFERRERS (ข้อมูลผู้แนะนำ)
        _supabase.channel('realtime_referrers')
            .on('postgres_changes', { event: '*', schema: 'public', table: 'referrals' }, () => {
                debounceRealtime('referrals', () => {
                    if (typeof loadReferralData === 'function') loadReferralData();
                }, 200);
            })
            .on('postgres_changes', { event: '*', schema: 'public', table: 'referrers' }, () => {
                debounceRealtime('referrers', () => {
                    if (typeof loadReferralData === 'function') loadReferralData();
                }, 200);
            })
            .subscribe();

    } catch (err) {
        console.warn('Real-time Hub initialization notice:', err);
    }
}
window.initClinicRealtimeHub = initClinicRealtimeHub;

// Network Status Listeners for seamless auto-reconnect
window.addEventListener('online', () => {
    console.log('🌐 Internet Reconnected: Re-syncing clinic data and real-time channels...');
    if (typeof Swal !== 'undefined') {
        const Toast = Swal.mixin({
            toast: true,
            position: 'top-end',
            showConfirmButton: false,
            timer: 3000,
            timerProgressBar: true
        });
        Toast.fire({
            icon: 'success',
            title: 'เชื่อมต่ออินเทอร์เน็ตแล้ว (Online)'
        });
    }
    try {
        if (typeof initClinicRealtimeHub === 'function') initClinicRealtimeHub();
        if (typeof loadBills === 'function') loadBills();
        if (typeof updateDashboardStats === 'function') updateDashboardStats();
        if (typeof loadDoctorQueue === 'function') loadDoctorQueue();
        if (typeof loadTriage === 'function') loadTriage();
        if (typeof loadPatients === 'function') loadPatients();
    } catch (e) { }
});

window.addEventListener('offline', () => {
    console.warn('⚠️ Internet Disconnected: Clinic is currently operating in offline-safe cache mode.');
    if (typeof Swal !== 'undefined') {
        const Toast = Swal.mixin({
            toast: true,
            position: 'top-end',
            showConfirmButton: false,
            timer: 4000,
            timerProgressBar: true
        });
        Toast.fire({
            icon: 'warning',
            title: 'อินเทอร์เน็ตหลุด (Offline): ไม่สามารถซิงค์ข้อมูลกับคลาวด์ได้ชั่วคราว'
        });
    }
});

function generateId(prefix) {
    return prefix + '-' + Math.floor(100000 + Math.random() * 900000);
}

// 🌟 Helper ดึง Logo ແລະ ຊື່ຄລີນິກຈາກ Clinic Settings
async function getClinicBrandingInfo() {
    let logoUrl = '';
    let clinicName = 'Clinic';
    try {
        if (!window.clinicSettings && typeof _supabase !== 'undefined') {
            const { data: sData } = await _supabase.from('clinic_settings').select('key, value');
            if (sData && sData.length > 0) {
                window.clinicSettings = Object.fromEntries(sData.map(r => [r.key, r.value]));
            }
        }
        const cSettings = window.clinicSettings || {};
        logoUrl = cSettings['clinic_logo_url'] || localStorage.getItem('clinic_logo_url') || '';
        if (cSettings['clinic_name_la']) {
            clinicName = cSettings['clinic_name_la'];
        }
    } catch (e) {
        console.warn('Load clinic settings branding error:', e);
    }
    return { logoUrl, clinicName };
}

// Pre-load clinic settings for slips, invoices and bills
(async function loadGlobalClinicSettings() {
    try {
        if (typeof _supabase !== 'undefined') {
            const { data: sData } = await _supabase.from('clinic_settings').select('key, value');
            if (sData && sData.length > 0) {
                window.clinicSettings = Object.fromEntries(sData.map(r => [r.key, r.value]));
                if (window.clinicSettings['clinic_logo_url']) {
                    localStorage.setItem('clinic_logo_url', window.clinicSettings['clinic_logo_url']);
                }
            }
        }
    } catch (e) {
        console.warn('Preload clinic settings error:', e);
    }
})();

document.addEventListener("DOMContentLoaded", function () {
    // === COLLAPSIBLE SIDEBAR DYNAMIC INITIALIZATION ===
    const sidebar = document.querySelector('.sidebar');
    const contentArea = document.querySelector('.content-area');
    if (sidebar && contentArea) {
        const isCollapsed = localStorage.getItem('sidebar-collapsed') === 'true';
        if (isCollapsed) {
            sidebar.classList.add('collapsed');
            contentArea.classList.add('collapsed');
        }

        const navLinks = sidebar.querySelectorAll('.nav-link');
        navLinks.forEach(link => {
            if (!link.getAttribute('title')) {
                const text = link.textContent.trim();
                if (text) link.setAttribute('title', text);
            }
        });

        const toggleContainer = document.createElement('div');
        toggleContainer.className = 'sidebar-toggle-container';

        const toggleBtn = document.createElement('div');
        toggleBtn.className = 'sidebar-toggle-btn';
        toggleBtn.innerHTML = `<i class="bi bi-${isCollapsed ? 'chevron-right' : 'chevron-left'}" id="sidebarToggleIcon"></i>`;

        toggleBtn.addEventListener('click', function () {
            const collapsed = sidebar.classList.toggle('collapsed');
            contentArea.classList.toggle('collapsed');
            localStorage.setItem('sidebar-collapsed', collapsed ? 'true' : 'false');

            const icon = document.getElementById('sidebarToggleIcon');
            if (icon) {
                icon.className = `bi bi-${collapsed ? 'chevron-right' : 'chevron-left'}`;
            }
        });

        toggleContainer.appendChild(toggleBtn);
        sidebar.insertBefore(toggleContainer, sidebar.firstChild);
    }
    // === END OF COLLAPSIBLE SIDEBAR LOGIC ===

    // Prevent 'Blocked aria-hidden on an element because its descendant retained focus' warning
    document.addEventListener('hide.bs.modal', function (event) {
        if (document.activeElement && event.target && event.target.contains(document.activeElement)) {
            document.activeElement.blur();
        }
    });

    document.addEventListener('click', function (e) {
        if (e.target && (e.target.matches('[data-bs-dismiss="modal"]') || e.target.closest('[data-bs-dismiss="modal"]'))) {
            if (document.activeElement) document.activeElement.blur();
        }
    });

    if (typeof Swal !== 'undefined' && Swal.fire) {
        const _origSwalFire = Swal.fire.bind(Swal);
        window.Swal.fire = function (...args) {
            if (document.activeElement && document.activeElement !== document.body) {
                document.activeElement.blur();
            }
            return _origSwalFire(...args);
        };
    }

    // ⚡ Phase 1: โหลดคิวหลักและ Realtime ทันทีเพื่อให้ UI พร้อมใช้งานเร็วที่สุด
    loadDoctorQueue();
    loadPaymentQueue();
    loadPharmacyQueue();
    loadQueueList();
    loadMedicines();
    loadMlmProducts();
    initMlmRealtimeSubscription();
    initClinicRealtimeHub();

    // ⚡ Phase 2: ทยอยโหลดข้อมูลใน background แบบแบ่งกลุ่ม ไม่ให้แย่ง Network Connections (Browser 6-connection limit)
    setTimeout(() => {
        loadAppointments();
        loadPatients();
        loadTriage();
    }, 200);

    setTimeout(() => {
        loadLabQueue();
        loadPrescriptionList();
        loadPatientHistory();
    }, 600);

    setTimeout(() => {
        loadSupplyItems();
        loadSupplyRequests();
        loadServicesData();
    }, 1000);

    setTimeout(() => {
        loadReferralData();
        loadStaffUsers();
        loadBills();
        loadExpenses();
    }, 1400);

    // Listen for messages from iframes (e.g. marketing.html) to circumvent CORS issues
    window.addEventListener('message', async function (event) {
        if (event.data === 'openAddPatientModal') {
            if (typeof openAddPatientModal === 'function') {
                openAddPatientModal();
            }
        } else if (event.data === 'closeAddPatientModal') {
            const modalEl = document.getElementById('addPatientModal');
            if (modalEl) {
                const inst = bootstrap.Modal.getOrCreateInstance(modalEl);
                if (inst) inst.hide();
            }
        } else if (event.data && event.data.type === 'SHOW_VISIT_DETAIL') {
            if (typeof showHistoryDetails === 'function') {
                showHistoryDetails(event.data.visitId, event.data.hn, event.data.patientName, event.data.orderData);
            }
        } else if (event.data && event.data.type === 'ORDER_CREATED') {
            try {
                const orderData = event.data.order;
                if (orderData) {
                    // 1. บันทึกลงตาราง stk_nutrient_orders ใน Supabase MLM
                    if (typeof saveNutrientOrderToDatabase === 'function') {
                        saveNutrientOrderToDatabase(orderData).catch(err => console.warn('Sync order to stk_nutrient_orders warning:', err));
                    }

                    // 2. บันทึกลงตาราง visits, bills และ patients ใน Clinic Supabase เพื่อให้ปรากฏในประวัติคนไข้ (Patient History) ทันที
                    if (typeof _supabase !== 'undefined' && _supabase && orderData.visit_id) {
                        try {
                            const grandTotal = Number(orderData.grandTotal || orderData.total_amount || 0);
                            const randOrderNum = Math.floor(10000 + Math.random() * 90000);
                            const rawVId = String(orderData.visit_id || orderData.visitId || ('VIS-ORD-' + randOrderNum));
                            const cleanVId = rawVId.startsWith('VIS-ORD-') ? rawVId : ('VIS-ORD-' + rawVId.replace(/^VIS-|^ORD-/, ''));
                            const orderPhone = orderData.customer_phone || orderData.phone || '';
                            const orderDisease = orderData.disease || (orderData.gender && orderData.gender !== 'ຊາຍ' && orderData.gender !== 'ຍິງ' && orderData.gender !== 'ชาย' && orderData.gender !== 'หญิง' ? orderData.gender : '');
                            const orderSymptom = orderDisease || orderData.symptom || ('ສັ່ງຊື້ຢາ/ອາຫານເສີມ [Order]' + (orderData.notes ? ` (${orderData.notes})` : ''));
                            const visitPayload = {
                                visit_id: cleanVId,
                                hn: orderData.hn ? String(orderData.hn) : null,
                                patient_name: orderData.customer_name || orderData.patient_name,
                                doctor_name: orderData.closer_dr || orderData.doctor_advice || 'ແພດປະຈຳຄລີນິກ',
                                symptom: orderSymptom,
                                disease: orderDisease,
                                status: 'ສັ່ງຊື້ສິນຄ້າ',
                                created_at: orderData.created_at || new Date().toISOString(),
                                meds: (orderData.items_json || orderData.items) ? JSON.stringify(orderData.items_json || orderData.items) : null
                            };
                            // 1. บันทึกข้อมูลคนไข้ลง patients ก่อน เพื่อให้ตาราง visits และ bills อ้างอิง HN ได้อย่างสมบูรณ์ ไม่ติด Foreign Key 409
                            if (orderData.hn) {
                                try {
                                    const pUpsert = {
                                        hn: String(orderData.hn),
                                        patient_name: orderData.customer_name || orderData.patient_name,
                                        age: orderData.age || null,
                                        province: orderData.province || '',
                                        district: orderData.district || '',
                                        village: orderData.village || '',
                                        referred_by: orderData.recorded_by || '',
                                        created_at: orderData.created_at || new Date().toISOString()
                                    };
                                    if (orderPhone) pUpsert.phone = orderPhone;
                                    if (orderDisease) pUpsert.past_history = orderDisease;
                                    await _supabase.from('patients').upsert(pUpsert, { onConflict: 'hn' });
                                } catch (pe) { }
                            }

                            // 2. บันทึกข้อมูลคิวตรวจลง visits
                            await _supabase.from('visits').upsert(visitPayload, { onConflict: 'visit_id' });

                            // บันทึกลง LocalStorage ใช้ safeSetLocalStorage เพื่อป้องกัน QuotaExceededError (เฉพาะ visits ไม่สร้าง bills)
                            try {
                                let cachedVisits = JSON.parse(localStorage.getItem('clinic_visits_queue') || '[]');
                                if (!Array.isArray(cachedVisits)) cachedVisits = [];
                                cachedVisits.unshift(visitPayload);
                                window.safeSetLocalStorage('clinic_visits_queue', cachedVisits);
                            } catch (e) { }

                            // รีเฟรชประวัติผู้ป่วยทันทีหากเปิดหน้าประวัติอยู่
                            if (typeof loadPatientHistory === 'function') {
                                setTimeout(loadPatientHistory, 500);
                            }
                        } catch (vErr) {
                            console.warn('Sync order to visits/patients table warning:', vErr);
                        }
                    }
                }
            } catch (orderErr) {
                console.warn('Error handling ORDER_CREATED message:', orderErr);
            }
        } else if (event.data && event.data.type === 'FETCH_PATIENTS') {
            try {
                if (typeof _supabase === 'undefined') return;

                let currentUser = window.currentUser;
                if (!currentUser) {
                    try { currentUser = JSON.parse(localStorage.getItem('clinicUser') || 'null'); } catch (e) { }
                }

                // ดึงรหัสพนักงาน (emp_code) ของคนที่ Login อยู่
                let userEmpCode = currentUser && currentUser.emp_code ? String(currentUser.emp_code).trim() : '';
                if (!userEmpCode && currentUser && Array.isArray(window.allEmployeesData)) {
                    const foundEmp = window.allEmployeesData.find(e => {
                        const eMail = (e.email || '').toLowerCase().trim();
                        const curMail = (currentUser.email || '').toLowerCase().trim();
                        if (curMail && eMail && curMail === eMail) return true;

                        const eName = (e.full_name || e.name || '').toLowerCase().trim();
                        const curName = (currentUser.name || currentUser.full_name || '').toLowerCase().trim();
                        if (curName && eName && (eName.includes(curName) || curName.includes(eName))) return true;

                        return false;
                    });
                    if (foundEmp && foundEmp.emp_code) {
                        userEmpCode = String(foundEmp.emp_code).trim();
                    }
                }

                // โหลดรายชื่อผู้ป่วยทั้งหมดจาก Supabase (เรียงตามล่าสุด)
                const { data: patients, error } = await _supabase
                    .from('patients')
                    .select('*')
                    .order('created_at', { ascending: false });

                // ดึงข้อมูลการเข้าตรวจล่าสุด (visits)
                const { data: recentVisits } = await _supabase
                    .from('visits')
                    .select('visit_id, hn, patient_name, created_at, symptom, status, doctor_name, meds')
                    .order('created_at', { ascending: false })
                    .limit(300);

                // ดึงข้อมูลการสั่งซื้อสารอาหาร/ยา (stk_nutrient_orders)
                const candidateOrders = [];

                // 1. ดึงจาก MLM Supabase
                try {
                    const nutrientClient = (typeof _mlmSupabase !== 'undefined' && _mlmSupabase) || (typeof window._mlmSupabase !== 'undefined' && window._mlmSupabase);
                    if (nutrientClient) {
                        const { data: nData, error: nErr } = await nutrientClient
                            .from('stk_nutrient_orders')
                            .select('*')
                            .order('created_at', { ascending: false })
                            .limit(300);
                        if (!nErr && Array.isArray(nData)) candidateOrders.push(...nData);
                    }
                } catch (e) { }

                // 2. ดึงจาก Clinic Supabase stk_nutrient_orders (Dual-save fallback)
                try {
                    const clinicDb = (typeof _supabase !== 'undefined' && _supabase) || (typeof window._supabase !== 'undefined' && window._supabase);
                    if (clinicDb) {
                        const { data: cData, error: cErr } = await clinicDb
                            .from('stk_nutrient_orders')
                            .select('*')
                            .order('created_at', { ascending: false })
                            .limit(300);
                        if (!cErr && Array.isArray(cData)) candidateOrders.push(...cData);
                    }
                } catch (e) { }

                // 3. ดึงจาก visits table ที่เป็น VIS-ORD-%
                try {
                    const clinicDb = (typeof _supabase !== 'undefined' && _supabase) || (typeof window._supabase !== 'undefined' && window._supabase);
                    if (clinicDb) {
                        const { data: ordVisits, error: ovErr } = await clinicDb
                            .from('visits')
                            .select('visit_id, hn, patient_name, doctor_name, symptom, status, created_at, meds')
                            .ilike('visit_id', 'VIS-ORD-%')
                            .order('created_at', { ascending: false })
                            .limit(300);
                        if (!ovErr && Array.isArray(ordVisits)) candidateOrders.push(...ordVisits);
                    }
                } catch (e) { }

                // 4. ดึงจาก LocalStorage (clinic_orders ແລະ stk_nutrient_orders)
                try {
                    const localOrders = JSON.parse(localStorage.getItem('clinic_orders') || '[]');
                    if (Array.isArray(localOrders)) candidateOrders.push(...localOrders);
                } catch (e) { }
                try {
                    const localStk = JSON.parse(localStorage.getItem('stk_nutrient_orders') || '[]');
                    if (Array.isArray(localStk)) candidateOrders.push(...localStk);
                } catch (e) { }

                // 5. Deduplicate ออเดอร์ตามเลข Order / Visit ID
                const uniqueOrdersMap = new Map();
                candidateOrders.forEach(o => {
                    if (!o) return;
                    const st = String(o.status || '').toLowerCase();
                    if (st.includes('cancel') || st.includes('ຍົກເລີກ') || st.includes('ยกเลิก') || String(o.notes || '').includes('[DELETED]')) {
                        return;
                    }

                    const vid = String(o.visit_id || o.visitId || '').trim().toUpperCase();
                    const oid = String(o.order_id || o.orderId || '').trim().toUpperCase();
                    const symptomStr = String(o.symptom || o.disease || '');

                    // 🔧 [FIX] การแยกแยะ "Order สินค้า/อาหารเสริม" ออกจาก "ใบสั่งยาคลินิก (ORD-CLINIC-)"
                    // ข้อกำหนด:
                    //   - VIS-ORD-XXXXX  → Order สินค้า ✅
                    //   - ORD-XXXXX      → Order สินค้า ✅
                    //   - ORD-CLINIC-X   → ใบสั่งยาตอนตรวจ ❌ ไม่ใช่ Order
                    //   - symptom มีคำ "ສັ່ງຊື້" / "สั่งซื้อ" → Order ✅
                    //   - symptom มีคำ "Order" แบบ exact → Order ✅ (ป้องกันจับ keyword บังเอิญ)
                    const isClinicPrescription = oid.startsWith('ORD-CLINIC-') || vid.includes('CLINIC');
                    if (isClinicPrescription) return; // ใบสั่งยาคลินิก → ข้ามออกไปเลย ไม่นับเป็น Order

                    const isOrderByVid = vid.startsWith('VIS-ORD-');
                    const isOrderByOid = oid.startsWith('ORD-') && !oid.startsWith('ORD-CLINIC-');
                    const isOrderBySymptom = symptomStr.includes('ສັ່ງຊື້') || symptomStr.includes('สั่งซื้อ') ||
                        /\bOrder\b/.test(symptomStr) || symptomStr.startsWith('Order ');

                    const isOrder = isOrderByVid || isOrderByOid || isOrderBySymptom;

                    if (!isOrder) return;

                    let key = '';
                    const num = (vid || oid).replace(/\D/g, '');
                    if (num) {
                        key = 'ORD-' + num.slice(-5);
                    } else {
                        key = vid || oid || String(o.id || Math.random());
                    }

                    if (!uniqueOrdersMap.has(key)) {
                        uniqueOrdersMap.set(key, o);
                    } else {
                        const existing = uniqueOrdersMap.get(key);
                        uniqueOrdersMap.set(key, Object.assign({}, existing, o));
                    }
                });

                const combinedOrders = Array.from(uniqueOrdersMap.values());
                let allPatients = patients ? [...patients] : [];

                // ผูก visit_status และ order ล่าสุดให้กับคนไข้แต่ละคนอย่างแม่นยำ
                allPatients.forEach(p => {
                    const pVisits = (recentVisits || []).filter(v => (p.hn && v.hn === p.hn) || (!p.hn && v.patient_name && p.patient_name && v.patient_name.trim().toLowerCase() === p.patient_name.trim().toLowerCase()));

                    // 🌟 คัดกรองออเดอร์ของคนไข้: ถ้า Order มี HN ต้องตรงกับ HN ของคนไข้เท่านั้น (ป้องกันคนไข้ชื่อเหมือนกันแต่คนละ HN มาแย่งออเดอร์กัน)
                    const pOrders = combinedOrders.filter(o => {
                        if (o.hn && p.hn) {
                            return String(o.hn).trim() === String(p.hn).trim();
                        }
                        if (!o.hn) {
                            const oName = (o.customer_name || o.patient_name || '').trim().toLowerCase();
                            const pName = (p.patient_name || '').trim().toLowerCase();
                            return !!(oName && pName && oName === pName);
                        }
                        return false;
                    });

                    const latestV = pVisits[0];
                    const latestO = pOrders[0];

                    const vTime = latestV ? new Date(latestV.created_at || 0).getTime() : 0;
                    const oTime = latestO ? new Date(latestO.created_at || latestO.date || 0).getTime() : 0;

                    // ตรวจสอบว่า latestO เกิดจากการสั่งจ่ายยาในคลินิก (ORD-CLINIC-) หรือไม่
                    const isClinicRxOrder = latestO && String(latestO.order_id || '').startsWith('ORD-CLINIC-');

                    // ถ้าคนไข้มีประวัติมาตรวจรักษาในคลินิก (latestV ที่ไม่ใช่ออเดอร์)
                    const isRealClinicVisit = latestV && latestV.symptom && !latestV.symptom.startsWith('ສັ່ງຊື້') && !latestV.symptom.startsWith('สั่งซื้อ') && !latestV.symptom.startsWith('Order');

                    if (latestO && !isClinicRxOrder && (oTime >= vTime || !isRealClinicVisit)) {
                        const rawVisitId = latestO.visit_id || latestO.visitId || ('VIS-ORD-' + String(latestO.order_id || latestO.orderId || '').replace(/\D/g, '').slice(-5));
                        p.latest_visit_id = rawVisitId;
                        p.latest_visit_date = new Date(latestO.created_at || latestO.date).toLocaleString('lo-LA');
                        p.latest_visit_raw_date = latestO.created_at || latestO.date;
                        p.latest_symptom = 'ສັ່ງຊື້ຢາ/ອາຫານເສີມ' + (latestO.notes ? ` (${latestO.notes})` : (latestO.symptom ? ` (${latestO.symptom})` : ''));
                        p.visit_status = '08 ຫ້ອງຈ່າຍຢາ';
                        p.doctor_name = latestO.closer_dr || latestO.doctor_advice || 'ແພດປະຈຳຄລີນິກ';
                        p.has_order = true;
                        p.order_data = latestO;
                    } else if (latestV) {
                        // คนไข้มาตรวจรักษาที่คลินิก (มาตรวจ) -> แสดงผลตรวจและอาการจริง เช่น ตาแดง
                        p.latest_visit_id = latestV.visit_id;
                        p.latest_visit_date = new Date(latestV.created_at).toLocaleString('lo-LA');
                        p.latest_visit_raw_date = latestV.created_at;
                        p.latest_symptom = latestV.symptom || '-';
                        p.visit_status = latestV.status || '-';
                        p.doctor_name = latestV.doctor_name || (latestO ? (latestO.closer_dr || latestO.doctor_advice) : '-');
                        p.has_order = false;
                        if (latestO) {
                            p.order_data = latestO;
                        }
                    }
                });

                // 🌟 โครงสร้างข้อมูล Order แท้จริงสำหรับแท็บ "Order" (1 Order = 1 แถว)
                const allOrdersList = combinedOrders.map(o => {
                    const vid = o.visit_id || o.visitId || '';
                    const oid = o.order_id || o.orderId || '';
                    const num = (vid || oid).replace(/\D/g, '');
                    const rawVisitId = vid.startsWith('VIS-ORD-') ? vid : ('VIS-ORD-' + (num ? num.slice(-5) : '00000'));
                    const ordDate = o.created_at || o.date || new Date().toISOString();

                    // จับคู่หาคนไข้เพื่อดึง HN หรือข้อมูลอ้างอิง
                    let matchedPt = null;
                    if (o.hn) {
                        matchedPt = allPatients.find(p => p.hn && (p.hn === o.hn || String(p.hn).trim() === String(o.hn).trim()));
                    }
                    if (!matchedPt) {
                        const oName = (o.customer_name || o.patient_name || '').trim().toLowerCase();
                        if (oName) {
                            matchedPt = allPatients.find(p => p.patient_name && p.patient_name.trim().toLowerCase() === oName);
                        }
                    }

                    const ordHn = o.hn || (matchedPt ? matchedPt.hn : '-');
                    const ordName = o.customer_name || o.patient_name || (matchedPt ? matchedPt.patient_name : '-');
                    const ordPhone = o.customer_phone || o.phone || (matchedPt ? (matchedPt.phone || matchedPt.tel) : '-');
                    const symptomText = o.notes ? ` (${o.notes})` : (o.symptom ? ` (${o.symptom})` : '');

                    let orderSubtotal = Number(o.subtotal || 0);
                    let orderGrandTotal = Number(o.grandTotal || o.total_amount || o.payable_amount || 0);
                    const orderDisc = Number(o.discount || 0);

                    let ordItems = o.items_json || o.items || o.meds;
                    if (typeof ordItems === 'string') {
                        try { ordItems = JSON.parse(ordItems); } catch (e) { ordItems = []; }
                    }
                    if ((!orderGrandTotal || orderGrandTotal === 0) && Array.isArray(ordItems) && ordItems.length > 0) {
                        let calcSub = 0;
                        ordItems.forEach(it => {
                            if (!it) return;
                            const q = parseFloat(it.qty || it.quantity || 1) || 1;
                            const t = parseFloat(String(it.total || it.total_price || '').replace(/,/g, ''));
                            if (!isNaN(t) && t > 0) calcSub += t;
                            else {
                                const p = parseFloat(String(it.price || it.unit_price || it.sale_price || 0).replace(/,/g, '')) || 0;
                                calcSub += (q * p);
                            }
                        });
                        orderSubtotal = calcSub;
                        orderGrandTotal = Math.max(0, calcSub - orderDisc);
                    }

                    return {
                        ...o,
                        id: o.id || rawVisitId,
                        hn: ordHn,
                        patient_name: ordName,
                        phone: ordPhone,
                        created_at: ordDate,
                        latest_visit_id: rawVisitId,
                        latest_visit_date: new Date(ordDate).toLocaleString('lo-LA'),
                        latest_visit_raw_date: ordDate,
                        latest_symptom: 'ສັ່ງຊື້ຢາ/อาหารເສີມ' + symptomText,
                        visit_status: '08 ຫ້ອງຈ່າຍຢາ',
                        status: '08 ຫ້ອງຈ່າຍຢາ',
                        doctor_name: o.closer_dr || o.doctor_advice || (matchedPt ? matchedPt.doctor_name : 'ແພດປະຈຳຄລີນິກ') || 'ແພດປະຈຳຄລີນິກ',
                        has_order: true,
                        grandTotal: orderGrandTotal,
                        subtotal: orderSubtotal,
                        items: ordItems,
                        order_data: {
                            ...o,
                            grandTotal: orderGrandTotal,
                            subtotal: orderSubtotal,
                            items: ordItems
                        },
                        referred_by: o.referred_by || o.closer_dr || (matchedPt ? matchedPt.referred_by : ''),
                        created_by: o.created_by || (matchedPt ? matchedPt.created_by : '')
                    };
                }).sort((a, b) => new Date(b.created_at || 0).getTime() - new Date(a.created_at || 0).getTime());

                // ตรวจสอบสิทธิ์ว่าเป็น Admin หรือไม่
                const permissions = currentUser && Array.isArray(currentUser.permissions) ? currentUser.permissions : [];
                const userRole = (currentUser && currentUser.role ? String(currentUser.role) : '').trim().toLowerCase();
                const userEmp = userEmpCode.toLowerCase();
                const userName = (currentUser && (currentUser.name || currentUser.full_name) ? String(currentUser.name || currentUser.full_name) : '').trim().toLowerCase();

                const isAdmin = userRole === 'admin' ||
                    userRole === 'administrator' ||
                    userRole === 'ผู้ดูแลระบบ' ||
                    userRole === 'ຜູ້ດູແລລະບົບ' ||
                    userRole === 'superadmin' ||
                    permissions.includes('all') ||
                    userEmp === 'admin01' ||
                    userName.includes('admin');

                // 🌟 ฟังก์ชันตรวจสอบว่าคนไข้คนนี้เป็นของ User คนที่ Login หรือไม่
                // โดยยึดจาก 1. User Login และ 2. ผู้แนะนำ (referred_by) เช่น ถ้าเลือก 92091957 - SIENG MR ก็จะโผล่ที่หน้าของนาย Sieng เท่านั้น
                const isPatientReferredByUser = function (p) {
                    if (!currentUser && !userEmpCode) return false;

                    const refStr = (p.referred_by || '').trim().toLowerCase();
                    const createdStr = (p.created_by || '').trim().toLowerCase();

                    // 1. ตรวจสอบรหัสพนักงาน (emp_code) เช่น '92091957', 'U001', 'ADMIN01'
                    if (userEmpCode) {
                        const cleanEmp = userEmpCode.toLowerCase().trim();
                        if (refStr && (refStr === cleanEmp || refStr.includes(cleanEmp))) return true;
                        if (createdStr && (createdStr === cleanEmp || createdStr.includes(cleanEmp))) return true;
                    }

                    // 2. ตรวจสอบชื่อพนักงาน (name / full_name) เช่น 'sieng mr'
                    const names = [currentUser.name, currentUser.full_name, currentUser.fullname].filter(Boolean);
                    for (const n of names) {
                        const cleanN = String(n).trim().toLowerCase();
                        if (!cleanN) continue;
                        if (refStr && (refStr === cleanN || refStr.includes(cleanN))) return true;
                        if (createdStr && (createdStr === cleanN || createdStr.includes(cleanN))) return true;
                    }

                    // 3. ตรวจสอบอีเมล (email)
                    if (currentUser.email) {
                        const cleanEmail = String(currentUser.email).trim().toLowerCase();
                        const prefix = cleanEmail.split('@')[0].trim();
                        if (refStr && (refStr === cleanEmail || refStr.includes(cleanEmail))) return true;
                        if (createdStr && (createdStr === cleanEmail || createdStr.includes(cleanEmail))) return true;
                        if (prefix && prefix.length >= 3) {
                            if (refStr && refStr.includes(prefix)) return true;
                            if (createdStr && createdStr.includes(prefix)) return true;
                        }
                    }

                    // 4. ตรวจสอบจาก clinic_patient_referrers ที่เก็บไว้ใน localStorage
                    try {
                        const refMap = JSON.parse(localStorage.getItem('clinic_patient_referrers') || '{}');
                        if (p.hn && refMap[p.hn]) {
                            const mr = String(refMap[p.hn]).trim().toLowerCase();
                            if (userEmpCode && mr.includes(userEmpCode.toLowerCase().trim())) return true;
                            for (const n of names) {
                                const cleanN = String(n).trim().toLowerCase();
                                if (cleanN && mr.includes(cleanN)) return true;
                            }
                        }
                    } catch (e) { }

                    return false;
                };

                const myPatients = allPatients.filter(p => isPatientReferredByUser(p));
                const myOrdersList = allOrdersList.filter(o => isPatientReferredByUser(o));

                if (event.source) {
                    event.source.postMessage({
                        type: 'PATIENTS_DATA',
                        patients: isAdmin ? allPatients : myPatients,
                        allPatients: isAdmin ? allPatients : myPatients,
                        myPatients: myPatients,
                        orders: isAdmin ? allOrdersList : myOrdersList,
                        allOrders: isAdmin ? allOrdersList : myOrdersList,
                        myOrders: myOrdersList,
                        isAdmin: isAdmin,
                        currentUserCode: userEmpCode,
                        currentUserName: currentUser ? (currentUser.name || currentUser.full_name || currentUser.email) : '',
                        targetHn: event.data.targetHn || null
                    }, '*');
                }
            } catch (err) {
                console.error('Error fetching patients for iframe:', err);
            }
        }
    });
});

function calculateAge() {
    const dobEl = document.querySelector('input[name="DOB"]');
    const dobInput = dobEl ? dobEl.value : null;
    if (dobInput) {
        const dob = new Date(dobInput);
        const today = new Date();
        let age = today.getFullYear() - dob.getFullYear();
        const m = today.getMonth() - dob.getMonth();
        if (m < 0 || (m === 0 && today.getDate() < dob.getDate())) { age--; }
        const ageEl = document.querySelector('input[name="Age"]');
        if (ageEl) ageEl.value = age >= 0 ? age : 0;
    }
}

function calculateBMI() {
    let w = parseFloat(document.getElementById('triageWeight').value);
    let h = parseFloat(document.getElementById('triageHeight').value) / 100;
    if (w > 0 && h > 0) { document.getElementById('triageBMI').value = (w / (h * h)).toFixed(2); }
}

// =====================================
// โหลดคิวและข้อมูลต่างๆ
// =====================================
let allAppointments = [];
window.appointmentReferrersMap = JSON.parse(localStorage.getItem('clinic_appointment_referrers') || '{}');
window.patientReferrersMap = JSON.parse(localStorage.getItem('clinic_patient_referrers') || '{}');

async function loadAppointments() {
    const tbody = document.querySelector('#appointmentsTable tbody');
    if (!tbody) return;

    // ตั้งค่าเริ่มต้นของตัวเลือกวันที่นัดหมายเป็นวันปัจจุบัน (Today) หากยังไม่ได้เลือก
    const dateInput = document.getElementById('appointmentDateFilter');
    if (dateInput && !dateInput.value) {
        const todayStr = formatVientianeDate(getVientianeNow()); // ใช้เวลา UTC+7 ลาว/ไทย แก้ปัญหาวันผิดช่วงเช้ามืด
        dateInput.value = todayStr;
    }

    const { data, error } = await _supabase
        .from('appointments')
        .select('*')
        .order('created_at', { ascending: true });

    if (error) {
        tbody.innerHTML = `<tr><td colspan="9" class="text-center text-danger py-3">เกิดข้อผิดพลาด: ${error.message}</td></tr>`;
        return;
    }

    allAppointments = data || [];

    // ดึงข้อมูล referred_by จาก persistent localStorage map
    window.appointmentReferrersMap = JSON.parse(localStorage.getItem('clinic_appointment_referrers') || '{}');
    allAppointments.forEach(d => {
        if (!d.referred_by && window.appointmentReferrersMap[d.appointment_id]) {
            d.referred_by = window.appointmentReferrersMap[d.appointment_id];
        }
    });

    filterAppointments();
}

function toggleApptReferrerField() {
    const isAssisted = document.getElementById('apptTypeAssisted')?.checked;
    const container = document.getElementById('apptReferredByContainer');
    const select = document.getElementById('apptReferredBySelect');

    const labelDirect = document.getElementById('labelApptDirect');
    const labelAssisted = document.getElementById('labelApptAssisted');

    if (labelDirect && labelAssisted) {
        if (isAssisted) {
            labelAssisted.className = "flex-fill text-center py-2.5 px-3 rounded-3 cursor-pointer transition-all fw-bold d-flex align-items-center justify-content-center gap-2 mb-0 bg-primary text-white shadow-sm";
            labelDirect.className = "flex-fill text-center py-2.5 px-3 rounded-3 cursor-pointer transition-all fw-bold d-flex align-items-center justify-content-center gap-2 mb-0 bg-transparent text-secondary";
        } else {
            labelDirect.className = "flex-fill text-center py-2.5 px-3 rounded-3 cursor-pointer transition-all fw-bold d-flex align-items-center justify-content-center gap-2 mb-0 bg-primary text-white shadow-sm";
            labelAssisted.className = "flex-fill text-center py-2.5 px-3 rounded-3 cursor-pointer transition-all fw-bold d-flex align-items-center justify-content-center gap-2 mb-0 bg-transparent text-secondary";
        }
    }

    if (!container) return;

    if (isAssisted) {
        container.style.display = 'block';
    } else {
        container.style.display = 'none';
        if (select) select.value = '';
    }
}

function renderAppointmentsTable(list, selectedDate = '') {
    const tbody = document.querySelector('#appointmentsTable tbody');
    if (!tbody) return;

    tbody.innerHTML = '';
    if (!list || list.length === 0) {
        if (selectedDate) {
            const todayStr = formatVientianeDate(getVientianeNow()); // ใช้เวลา UTC+7 ลาว/ไทย แก้ปัญหาวันผิดช่วงเช้ามืด
            const isToday = (selectedDate === todayStr);
            const dateLabel = isToday ? 'วันนี้' : selectedDate;
            tbody.innerHTML = `<tr><td colspan="9" class="text-center text-muted py-4"><i class="bi bi-calendar-x text-warning me-2 fs-5"></i>ไม่มีรายการนัดหมายในประจำวัน (${dateLabel}) <button type="button" class="btn btn-sm btn-link text-primary text-decoration-none fw-semibold p-0 ms-2" onclick="clearAppointmentDateFilter()">ดูทั้งหมด</button></td></tr>`;
        } else {
            tbody.innerHTML = '<tr><td colspan="9" class="text-center text-muted py-3">ไม่มีข้อมูลนัดหมาย</td></tr>';
        }
        return;
    }

    list.forEach(row => {
        let isWaiting = (row.status === 'รอ' || row.status === 'รอยืนยัน' || row.status === 'รอดำเนินการ');
        let rawStatus = row.status || 'เสร็จสิ้น';
        let displayStatus = rawStatus;
        if (rawStatus === 'สำเร็จ' || rawStatus === 'เสร็จสิ้น') {
            displayStatus = typeof t === 'function' ? t('status_completed', 'เสร็จสิ้น') : 'เสร็จสิ้น';
        } else if (rawStatus === 'รอ' || rawStatus === 'รอยืนยัน' || rawStatus === 'รอดำเนินการ') {
            displayStatus = typeof t === 'function' ? t('status_pending', 'รอดำเนินการ') : 'รอดำเนินการ';
        } else if (rawStatus === 'ยกเลิก') {
            displayStatus = typeof t === 'function' ? t('status_cancelled', 'ยกเลิก') : 'ยกเลิก';
        }
        let statusBadge = isWaiting ? `<span class="badge-soft-warning">${displayStatus}</span>` : `<span class="badge-soft-success">${displayStatus}</span>`;

        let actionBtn = '';
        const regBtnText = typeof t === 'function' ? t('sidebar_registration', 'ลงทะเบียน') : 'ลงทะเบียน';
        const doneBtnText = typeof t === 'function' ? t('action_done', 'ทำรายการแล้ว') : 'ทำรายการแล้ว';
        if (isWaiting) {
            actionBtn = `
                <div class="d-flex gap-1 justify-content-center">
                    <button type="button" class="btn btn-sm btn-outline-primary" onclick="openRegisterFromAppointment('${row.appointment_id}', '${row.guest_name}', '${row.guest_phone}')">${regBtnText}</button>
                    <button type="button" class="btn btn-sm btn-outline-secondary" onclick="editAppointment('${row.appointment_id}')" title="แก้ไข"><i class="bi bi-pencil-square"></i></button>
                    <button type="button" class="btn btn-sm btn-outline-danger" onclick="deleteAppointment('${row.appointment_id}')" title="ลบ"><i class="bi bi-trash"></i></button>
                </div>
            `;
        } else {
            actionBtn = `
                <div class="d-flex gap-1 justify-content-center">
                    <button type="button" class="btn btn-sm btn-light text-muted" disabled>${doneBtnText}</button>
                    <button type="button" class="btn btn-sm btn-outline-danger" onclick="deleteAppointment('${row.appointment_id}')" title="ลบ"><i class="bi bi-trash"></i></button>
                </div>
            `;
        }

        let referrerIdVal = row.referred_by;
        let displayReason = row.reason || '-';
        let referrerHtml = '';

        if (referrerIdVal) {
            const refObj = (window.referrersData || []).find(r => r.id === referrerIdVal || r.code === referrerIdVal);
            const displayRefName = refObj ? `${refObj.name} (${refObj.code || refObj.id})` : referrerIdVal;
            referrerHtml = `<span class="badge bg-primary-subtle text-primary border border-primary-subtle px-2 py-1" style="font-weight: 500;"><i class="ph ph-hand-coins me-1"></i>${displayRefName}</span>`;
        } else if (row.assistant_code) {
            referrerHtml = `<span class="badge bg-light text-dark border px-2 py-1" style="font-weight: 500;"><i class="bi bi-person-badge text-primary me-1"></i>${row.assistant_code}</span>`;
        } else {
            referrerHtml = `<span class="text-muted small">- (นัดเอง)</span>`;
        }

        tbody.innerHTML += `<tr>
            <td class="ps-4 fw-bold text-primary">${row.appointment_id}</td>
            <td>${row.appointment_date}</td>
            <td>${row.appointment_time}</td>
            <td class="fw-bold">${row.guest_name}</td>
            <td>${row.guest_phone}</td>
            <td>${referrerHtml}</td>
            <td>${displayReason || '-'}</td>
            <td>${statusBadge}</td>
            <td class="text-center">${actionBtn}</td>
        </tr>`;
    });
}

function openAddAppointmentModal() {
    const form = document.getElementById('appointmentForm');
    if (form) form.reset();
    if (document.getElementById('appointmentEditId')) document.getElementById('appointmentEditId').value = '';
    if (document.getElementById('displayApptId')) document.getElementById('displayApptId').value = generateId('APT');

    const title = document.getElementById('addAppointmentModalTitle');
    if (title) title.innerHTML = '<i class="bi bi-calendar-plus text-primary me-2"></i>เพิ่มการนัดหมาย';

    populateReferrerDropdowns();
    toggleApptReferrerField();
    bootstrap.Modal.getOrCreateInstance(document.getElementById('addAppointmentModal')).show();
}

function editAppointment(id) {
    const appt = (allAppointments || []).find(a => a.appointment_id === id);
    if (!appt) return;

    populateReferrerDropdowns();

    const form = document.getElementById('appointmentForm');
    if (document.getElementById('appointmentEditId')) document.getElementById('appointmentEditId').value = appt.appointment_id;
    if (document.getElementById('displayApptId')) document.getElementById('displayApptId').value = appt.appointment_id;
    if (form.guestName) form.guestName.value = appt.guest_name || '';
    if (form.guestPhone) form.guestPhone.value = appt.guest_phone || '';
    if (form.appointmentDate) form.appointmentDate.value = appt.appointment_date || '';
    if (form.appointmentTime) form.appointmentTime.value = appt.appointment_time || '';
    if (form.reason) form.reason.value = appt.reason || '';

    const apptTypeAssisted = document.getElementById('apptTypeAssisted');
    const apptTypeDirect = document.getElementById('apptTypeDirect');
    const refSelect = document.getElementById('apptReferredBySelect');

    if (appt.referred_by || appt.appointment_type === 'assisted') {
        if (apptTypeAssisted) apptTypeAssisted.checked = true;
    } else {
        if (apptTypeDirect) apptTypeDirect.checked = true;
    }

    if (refSelect) refSelect.value = appt.referred_by || '';
    toggleApptReferrerField();

    const title = document.getElementById('addAppointmentModalTitle');
    if (title) title.innerHTML = '<i class="bi bi-pencil-square text-primary me-2"></i>แก้ไขข้อมูลการนัดหมาย';

    bootstrap.Modal.getOrCreateInstance(document.getElementById('addAppointmentModal')).show();
}

async function deleteAppointment(id) {
    const appt = (allAppointments || []).find(a => a.appointment_id === id);
    const displayName = appt ? `${appt.guest_name || 'ไม่ระบุชื่อ'} (${appt.appointment_id})` : id;

    const res = await Swal.fire({
        title: 'ยืนยันการลบนัดหมาย?',
        text: `ต้องการลบรายการนัดหมายของคุณ ${displayName} ออกจากระบบใช่หรือไม่?`,
        icon: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#ef4444',
        confirmButtonText: 'ลบข้อมูล',
        cancelButtonText: 'ยกเลิก'
    });

    if (res.isConfirmed) {
        Swal.fire({ title: 'กำลังลบ...', allowOutsideClick: false, didOpen: () => Swal.showLoading() });

        try {
            await _supabase.from('appointments').delete().eq('appointment_id', id);
        } catch (e) {
            console.log('Supabase appointment delete fallback');
        }

        allAppointments = allAppointments.filter(a => a.appointment_id !== id);
        if (window.appointmentReferrersMap) {
            delete window.appointmentReferrersMap[id];
            localStorage.setItem('clinic_appointment_referrers', JSON.stringify(window.appointmentReferrersMap));
        }

        loadAppointments();
        Swal.fire('ลบข้อมูลแล้ว', 'ลบรายการนัดหมายเรียบร้อยแล้ว', 'success');
    }
}

function filterAppointments() {
    const q = (document.getElementById('searchAppointmentInput')?.value || '').toLowerCase().trim();
    const dateVal = document.getElementById('appointmentDateFilter')?.value || '';

    let filtered = [...(allAppointments || [])];

    if (dateVal) {
        filtered = filtered.filter(row => row.appointment_date === dateVal);
    }

    if (q) {
        filtered = filtered.filter(row =>
            (row.appointment_id && row.appointment_id.toLowerCase().includes(q)) ||
            (row.guest_name && row.guest_name.toLowerCase().includes(q)) ||
            (row.guest_phone && row.guest_phone.toLowerCase().includes(q)) ||
            (row.assistant_code && row.assistant_code.toLowerCase().includes(q)) ||
            (row.reason && row.reason.toLowerCase().includes(q)) ||
            (row.status && row.status.toLowerCase().includes(q))
        );
    }

    renderAppointmentsTable(filtered, dateVal);
}

function setAppointmentTodayFilter() {
    const todayStr = new Date().toISOString().split('T')[0];
    const dateInput = document.getElementById('appointmentDateFilter');
    if (dateInput) {
        dateInput.value = todayStr;
    }
    filterAppointments();
}

function clearAppointmentDateFilter() {
    const dateInput = document.getElementById('appointmentDateFilter');
    if (dateInput) {
        dateInput.value = '';
    }
    filterAppointments();
}

window.setAppointmentTodayFilter = setAppointmentTodayFilter;
window.clearAppointmentDateFilter = clearAppointmentDateFilter;

async function loadPatients() {
    const tbody = document.querySelector('#patientsTable tbody');

    const { data, error } = await _supabase
        .from('patients')
        .select('*')
        .order('created_at', { ascending: false }); // เรียงใหม่→เก่า เพื่อให้คนไข้ใหม่สุดไม่หายเมื่อข้อมูลเกิน 1,000 รายการ

    if (error) {
        if (tbody) tbody.innerHTML = `<tr><td colspan="9" class="text-center text-danger py-3">เกิดข้อผิดพลาด: ${error.message}</td></tr>`;
        return;
    }
    if (!data || data.length === 0) {
        if (tbody) tbody.innerHTML = '<tr><td colspan="9" class="text-center text-muted py-3">ไม่มีข้อมูลผู้ป่วย</td></tr>';
        return;
    }

    // ดึงข้อมูลการเข้าตรวจ (visits) ทั้งหมดเพื่อประมวลผลสถานะการคัดกรองและการชำระเงิน
    let latestVisitMap = {};
    try {
        const { data: visitsData } = await _supabase
            .from('visits')
            .select('*')
            .order('created_at', { ascending: false });

        if (visitsData) {
            visitsData.forEach(v => {
                if (v.hn && !latestVisitMap[v.hn]) {
                    latestVisitMap[v.hn] = v;
                }
            });
        }
    } catch (e) { }

    window.patientReferrersMap = JSON.parse(localStorage.getItem('clinic_patient_referrers') || '{}');
    if (data) {
        data.forEach(d => {
            if (!d.referred_by && window.patientReferrersMap[d.hn]) {
                d.referred_by = window.patientReferrersMap[d.hn];
            }
        });
    }

    window.allPatients = data;
    window.latestVisitMap = latestVisitMap;

    // อัปเดตยอดบน Dashboard ทันทีที่ข้อมูลผู้ป่วยพร้อม
    if (typeof window.updateDashboardNoShowCount === 'function') {
        window.updateDashboardNoShowCount();
    }
    const dw = (typeof window.getDashboardFrameWindow === 'function') ? window.getDashboardFrameWindow() : null;
    const dbPanelVisitsEl = (dw && dw.document) ? dw.document.getElementById('db-panel-visits-count') : document.getElementById('db-panel-visits-count');
    if (dbPanelVisitsEl && Array.isArray(window.allPatients)) {
        let sDateStr = '';
        let eDateStr = '';
        if (window.dbStartDate && window.dbEndDate) {
            const minD = window.dbStartDate < window.dbEndDate ? window.dbStartDate : window.dbEndDate;
            const maxD = window.dbStartDate > window.dbEndDate ? window.dbStartDate : window.dbEndDate;
            const tzMin = minD.getTimezoneOffset() * 60000;
            sDateStr = (new Date(minD - tzMin)).toISOString().split('T')[0];
            const tzMax = maxD.getTimezoneOffset() * 60000;
            eDateStr = (new Date(maxD - tzMax)).toISOString().split('T')[0];
        } else {
            sDateStr = new Date().toISOString().split('T')[0];
            eDateStr = sDateStr;
        }
        const syncedCount = window.allPatients.filter(row => {
            if (!row.next_appointment_date) return false;
            try {
                const pDate = new Date(row.next_appointment_date);
                if (isNaN(pDate.getTime())) return false;
                const rDate = pDate.toISOString().split('T')[0];
                return (!sDateStr || rDate >= sDateStr) && (!eDateStr || rDate <= eDateStr);
            } catch (e) { return false; }
        }).length;
        dbPanelVisitsEl.textContent = syncedCount.toLocaleString();
    }

    if (tbody) {
        tbody.innerHTML = '';
        // ตั้งค่าเริ่มต้นวันที่กรองทะเบียนผู้ป่วยเป็นวันปัจจุบัน (Today) หากยังไม่ได้เลือก
        const startInput = document.getElementById('patientFilterStartDate');
        const endInput = document.getElementById('patientFilterEndDate');
        if (startInput && endInput && !startInput.value && !endInput.value) {
            const todayStr = formatVientianeDate(getVientianeNow()); // ใช้เวลา UTC+7 ลาว/ไทย แก้ปัญหาวันผิดช่วงเช้ามืด
            startInput.value = todayStr;
            endInput.value = todayStr;
        }

        filterPatients();
    }
}

// =====================================
// ระบบทะเบียนผู้ป่วย (Patient Registration) - รองรับ Pagination
// =====================================

window.patientFilteredData = []; // เก็บข้อมูลผู้ป่วยที่ถูกค้นหา/กรองแล้ว
window.patientCurrentPage = 1;   // เก็บหน้าปัจจุบัน
window.patientTriageFilter = 'all'; // เก็บสถานะตัวกรองคัดกรอง: 'all' | 'pending' | 'sent'
const PATIENTS_PER_PAGE = 10;    // แสดง 10 รายการต่อหน้า

// 1. ฟังก์ชันกรองข้อมูลผู้ป่วย
function filterPatients() {
    if (!window.allPatients) return;

    let filtered = window.allPatients;

    // Filter by Date (กรองตามวันที่นัดมาตรวจ)
    const startDateStr = document.getElementById('patientFilterStartDate')?.value;
    const endDateStr = document.getElementById('patientFilterEndDate')?.value;

    if (startDateStr || endDateStr) {
        filtered = filtered.filter(row => {
            // 🌟 เปลี่ยนเป้าหมายไปตรวจที่ next_appointment_date แทน created_at
            // ถ้าผู้ป่วยคนไหนไม่ได้ระบุวันที่นัดมาตรวจไว้ เมื่อมีการใช้ตัวกรองวันที่ ระบบจะซ่อนผู้ป่วยคนนั้น (return false)
            if (!row.next_appointment_date) return false;

            // แปลงรูปแบบวันที่ให้อยู่ในฟอร์แมตมาตรฐาน YYYY-MM-DD เพื่อใช้เปรียบเทียบ (พร้อม Safe Check กัน RangeError)
            try {
                const parsedDate = new Date(row.next_appointment_date);
                if (isNaN(parsedDate.getTime())) return false;
                const rowDate = parsedDate.toISOString().split('T')[0];

                let pass = true;
                if (startDateStr && rowDate < startDateStr) pass = false;
                if (endDateStr && rowDate > endDateStr) pass = false;
                return pass;
            } catch (dErr) {
                return false;
            }
        });
    }

    // Filter by Search Input
    const q = (document.getElementById('patientSearchInput')?.value || '').toLowerCase().trim();
    const cleanQ = q.replace(/[-\s]/g, '');
    if (q) {
        filtered = filtered.filter(row => {
            const phone = (row.phone || row.tel || '').toLowerCase();
            const cleanPhone = phone.replace(/[-\s]/g, '');
            return (row.hn && row.hn.toLowerCase().includes(q)) ||
                (row.patient_name && row.patient_name.toLowerCase().includes(q)) ||
                (phone && phone.includes(q)) ||
                (cleanPhone && cleanPhone.includes(cleanQ)) ||
                (row.province && row.province.toLowerCase().includes(q)) ||
                (row.village && row.village.toLowerCase().includes(q)) ||
                (row.allergies && row.allergies.toLowerCase().includes(q)) ||
                (row.referred_by && row.referred_by.toLowerCase().includes(q));
        });
    }

    // Filter by Triage Status
    const triageFilter = window.patientTriageFilter || 'all';
    if (triageFilter !== 'all') {
        // ใช้เวลา Local Time (UTC+7) เพื่อป้องกันปัญหาวันที่เหลื่อมช่วงหลังเที่ยงคืน - 07:00 น.
        const _now = new Date();
        const todayStr = `${_now.getFullYear()}-${String(_now.getMonth() + 1).padStart(2, '0')}-${String(_now.getDate()).padStart(2, '0')}`;
        const latestVisitMap = window.latestVisitMap || {};
        filtered = filtered.filter(row => {
            const latestVisit = latestVisitMap[row.hn];
            const vStatus = latestVisit ? latestVisit.status : null;
            let visitDateStr = '';
            if (latestVisit && latestVisit.created_at) {
                try {
                    const _vDate = new Date(latestVisit.created_at);
                    if (!isNaN(_vDate.getTime())) {
                        visitDateStr = `${_vDate.getFullYear()}-${String(_vDate.getMonth() + 1).padStart(2, '0')}-${String(_vDate.getDate()).padStart(2, '0')}`;
                    }
                } catch (e) { }
            }
            const isFromPreviousDay = Boolean(visitDateStr && visitDateStr < todayStr);
            const isOngoingTreatment = !isFromPreviousDay && latestVisit && (
                vStatus === 'รอคัดกรอง' || vStatus === 'รอตรวจ' || vStatus === 'รอผลแล็บ' ||
                vStatus === 'รอผลตรวจ Lab' || vStatus === 'รอจัดคิว' || vStatus === 'รออ่านผล' ||
                vStatus === 'กำลังคุยกับแพทย์' || vStatus === 'กำลังตรวจ' || vStatus === 'กำลังตรวจอยู่' ||
                vStatus === 'รอชำระเงิน' || vStatus === 'รอจัดยา' || vStatus === 'รอจ่ายยา'
            );
            if (triageFilter === 'pending') return !isOngoingTreatment;
            if (triageFilter === 'sent') return isOngoingTreatment;
            return true;
        });
    }

    // 🌟 นำข้อมูลที่กรองแล้วมาเก็บไว้ และรีเซ็ตหน้ากลับไปที่ 1 เสมอ
    window.patientFilteredData = filtered;
    window.patientCurrentPage = 1;
    renderPatientsTable();
}

// 2. ฟังก์ชันวาดตารางและปุ่มแบ่งหน้า (Pagination)
function renderPatientsTable(page = window.patientCurrentPage) {
    window.patientCurrentPage = page;
    const tbody = document.querySelector('#patientsTable tbody');
    const paginationContainer = document.getElementById('patientPagination');
    if (!tbody) return;

    tbody.innerHTML = '';

    const startDateStr = document.getElementById('patientFilterStartDate')?.value;
    const endDateStr = document.getElementById('patientFilterEndDate')?.value;

    // กรณีไม่มีข้อมูล
    if (!window.patientFilteredData || window.patientFilteredData.length === 0) {
        if (startDateStr || endDateStr) {
            tbody.innerHTML = `<tr><td colspan="10" class="text-center text-muted py-4"><i class="bi bi-calendar-x text-warning me-2 fs-5"></i>ไม่พบข้อมูลผู้ป่วยลงทะเบียนในช่วงวันที่เลือก <button type="button" class="btn btn-sm btn-link text-primary text-decoration-none fw-semibold p-0 ms-2" onclick="clearPatientDateFilter()">ดูทั้งหมด</button></td></tr>`;
        } else {
            const noDataText = typeof t === 'function' ? t('reg_no_data', 'ไม่พบข้อมูลผู้ป่วย') : 'ไม่พบข้อมูลผู้ป่วย';
            tbody.innerHTML = `<tr><td colspan="10" class="text-center text-muted py-5"><i class="bi bi-search fs-3 d-block mb-2 text-secondary"></i>${noDataText}</td></tr>`;
        }
        if (paginationContainer) paginationContainer.innerHTML = '';
        return;
    }

    // คำนวณจำนวนหน้า
    const totalItems = window.patientFilteredData.length;
    const totalPages = Math.ceil(totalItems / PATIENTS_PER_PAGE);

    if (window.patientCurrentPage > totalPages) window.patientCurrentPage = totalPages;
    if (window.patientCurrentPage < 1) window.patientCurrentPage = 1;

    // ตัดข้อมูล (Slice) มาเฉพาะ 10 รายการ
    const startIndex = (window.patientCurrentPage - 1) * PATIENTS_PER_PAGE;
    const endIndex = startIndex + PATIENTS_PER_PAGE;
    const currentData = window.patientFilteredData.slice(startIndex, endIndex);

    // วาดข้อมูลลงในตาราง
    currentData.forEach((row, idx) => {
        let no = startIndex + idx + 1; // คำนวณลำดับรวมกับหน้าที่กำลังเปิด
        let allergy = (row.allergies || '').trim();

        let allergyBadge = (allergy && allergy !== '-' && allergy !== 'ไม่มี')
            ? `<span class="badge-soft-danger">${allergy}</span>`
            : `<span class="badge-soft-success">${typeof t === 'function' ? t('none', 'ไม่มี') : 'ไม่มี'}</span>`;

        let refId = row.referred_by;
        let refHtml = '<span class="text-muted small">-</span>';
        if (refId) {
            const refObj = (window.referrersData || []).find(r => r.id === refId || r.code === refId);
            const staffObj = (window.allStaffUsers || window.defaultTeamStaffUsers || []).find(s => s.emp_code === refId || s.id === refId || s.full_name === refId);

            let displayRefName = refId;
            if (refObj) {
                displayRefName = `${refObj.name} (${refObj.code || refObj.id})`;
            } else if (staffObj) {
                displayRefName = `${staffObj.full_name} (${staffObj.emp_code || 'STAFF'})`;
            }
            refHtml = `<span class="badge bg-primary-subtle text-primary border border-primary-subtle px-2 py-1" style="font-weight: 500;"><i class="ph ph-hand-coins me-1"></i>${displayRefName}</span>`;
        }

        const latestVisit = window.latestVisitMap ? window.latestVisitMap[row.hn] : null;

        // 🌟 1. ກວດສອບສະຖານະການກວດຂອງ Visit ຫຼ້າສຸດ (Active vs Finished/New Visit)
        const todayStr = new Date().toISOString().split('T')[0];
        let visitDateStr = '';
        if (latestVisit && latestVisit.created_at) {
            visitDateStr = new Date(latestVisit.created_at).toISOString().split('T')[0];
        }
        const isFromPreviousDay = Boolean(visitDateStr && visitDateStr < todayStr);
        const vStatus = latestVisit ? latestVisit.status : null;

        // ຖືວ່າ "ກຳລັງປິ່ນປົວຢູ່" (ຍັງບໍ່ໃຫ້ສົ່ງຄັດກອງຊ້ຳ) ສະເພາະກໍລະນີທີ່ຍັງບໍ່ທັນສຳເລັດ ແລະ ເປັນຂອງມື້ນີ້ເທົ່ານັ້ນ
        const isOngoingTreatment = !isFromPreviousDay && latestVisit && (
            vStatus === 'รอคัดกรอง' || vStatus === 'รอตรวจ' || vStatus === 'รอผลแล็บ' ||
            vStatus === 'รอผลตรวจ Lab' || vStatus === 'รอจัดคิว' || vStatus === 'รออ่านผล' ||
            vStatus === 'กำลังคุยกับแพทย์' || vStatus === 'กำลังตรวจ' || vStatus === 'กำลังตรวจอยู่' ||
            vStatus === 'รอชำระเงิน' || vStatus === 'รอจัดยา' || vStatus === 'รอจ่ายยา'
        );

        const isFinished = !isOngoingTreatment && latestVisit && (vStatus === 'เสร็จสิ้น' || vStatus === 'ยกเลิก' || isFromPreviousDay);

        // ສະຖານະການຄັດກອງ
        let triageBadge = '';
        if (isOngoingTreatment) {
            const sentText = typeof t === 'function' ? t('reg_sent_triage', 'ส่งคัดกรองแล้ว') : 'ส่งคัดกรองแล้ว';
            triageBadge = `<span class="badge bg-info-subtle text-info border border-info-subtle px-2 py-1 text-nowrap"><i class="bi bi-check-circle-fill me-1"></i>${sentText}</span>`;
        } else if (isFinished) {
            triageBadge = `<span class="badge bg-success-subtle text-success border border-success-subtle px-2 py-1 text-nowrap"><i class="bi bi-check-all me-1"></i>ກວດສຳເລັດແລ້ວ</span>`;
        } else {
            const waitText = typeof t === 'function' ? t('reg_waiting_triage', 'รอส่งคัดกรอง') : 'รอส่งคัดกรอง';
            triageBadge = `<span class="badge bg-secondary-subtle text-secondary border px-2 py-1 text-nowrap"><i class="bi bi-clock me-1"></i>${waitText}</span>`;
        }

        // ສະຖານະການຊຳລະເງິນ
        let paymentBadge = '';
        if (vStatus === 'เสร็จสิ้น' || (isFromPreviousDay && vStatus !== 'รอชำระเงิน')) {
            const paidText = typeof t === 'function' ? t('payment_status_paid', 'ชำระเงินเสร็จสิ้น') : 'ชำระเงินเสร็จสิ้น';
            paymentBadge = `<span class="badge bg-success-subtle text-success border border-success-subtle px-2 py-1 text-nowrap"><i class="bi bi-check-all me-1"></i>${paidText}</span>`;
        } else if (vStatus === 'รอชำระเงิน') {
            const pendingPayText = typeof t === 'function' ? t('payment_status_pending', 'รอชำระเงิน') : 'รอชำระเงิน';
            paymentBadge = `<span class="badge bg-warning-subtle text-warning-emphasis border border-warning-subtle px-2 py-1 text-nowrap"><i class="bi bi-hourglass-split me-1"></i>${pendingPayText}</span>`;
        } else if (isOngoingTreatment) {
            const treatingText = typeof t === 'function' ? t('reg_status_in_treatment', 'กำลังรักษา') : 'กำลังรักษา';
            paymentBadge = `<span class="badge bg-danger-subtle text-danger border border-danger-subtle px-2 py-1 text-nowrap"><i class="bi bi-activity me-1"></i>${treatingText}</span>`;
        } else if (vStatus) {
            paymentBadge = `<span class="badge bg-secondary-subtle text-secondary border px-2 py-1 text-nowrap"><i class="bi bi-clock me-1"></i>${vStatus}</span>`;
        } else {
            const unpaidText = typeof t === 'function' ? t('payment_status_unpaid', 'ยังไม่ชำระเงิน') : 'ยังไม่ชำระเงิน';
            paymentBadge = `<span class="badge bg-light text-muted border px-2 py-1 text-nowrap"><i class="bi bi-dash-circle me-1"></i>${unpaidText}</span>`;
        }

        const statusBadges = `
            <div class="d-flex flex-column align-items-center justify-content-center gap-1">
                ${paymentBadge}
                ${triageBadge}
            </div>
        `;

        const sentBtnLabel = typeof t === 'function' ? t('reg_sent', 'ส่งแล้ว') : 'ส่งแล้ว';
        const sendTriageLabel = typeof t === 'function' ? t('reg_btn_send_triage', 'ส่งเข้าคัดกรอง') : 'ส่งเข้าคัดกรอง';

        // 🌟 2. ປຸ່ມສົ່ງເຂົ້າຄັດກອງ / ເປີດຮອບກວດໃໝ່:
        // - ຖ້າກຳລັງປິ່ນປົວຢູ່ໃນມື້ນີ້ -> ລັອກປຸ່ມ (disabled)
        // - ຖ້າກວດສຳເລັດແລ້ວ ຫຼື ມາຄົນລະມື້ -> ສະແດງປຸ່ມ "ເປີດຮອບໃໝ່" (ສ້າງ VISIT ໃໝ່)
        // - ຖ້າຄົນໄຂ້ໃໝ່ຍັງບໍ່ເຄີຍມີ Visit -> ສະແດງປຸ່ມ "ສົ່ງເຂົ້າຄັດກອງ"
        let sendBtn = '';
        if (isOngoingTreatment) {
            sendBtn = `<button type="button" class="btn btn-sm btn-secondary text-nowrap" disabled title="${sentBtnLabel}">${sentBtnLabel}</button>`;
        } else if (isFinished) {
            sendBtn = `<button type="button" class="btn btn-sm btn-outline-primary text-nowrap fw-semibold" onclick="sendToTriage('${row.hn}', '${row.patient_name}')" title="ເປີດຮອບກວດໃໝ່ (ສ້າງ VISIT ໃໝ່)"><i class="bi bi-plus-circle me-1"></i>ເປີດຮອບໃໝ່</button>`;
        } else {
            sendBtn = `<button type="button" class="btn btn-sm btn-primary text-nowrap" onclick="sendToTriage('${row.hn}', '${row.patient_name}')">${sendTriageLabel}</button>`;
        }

        let actionBtns = `
            <div class="d-flex gap-1 justify-content-center align-items-center text-nowrap">
                ${sendBtn}
                <button type="button" class="btn btn-sm btn-outline-secondary" onclick="editPatient('${row.hn}')" title="แก้ไขประวัติผู้ป่วย"><i class="bi bi-pencil-square"></i></button>
                <button type="button" class="btn btn-sm btn-outline-danger" onclick="deletePatient('${row.hn}')" title="ลบประวัติผู้ป่วย"><i class="bi bi-trash"></i></button>
            </div>
        `;

        tbody.innerHTML += `<tr>
            <td class="ps-4 text-center align-middle">${no}</td>
            <td class="fw-bold text-nowrap align-middle">${row.hn}</td>
            <td class="fw-bold text-nowrap align-middle">${row.patient_name}</td>
            <td class="text-nowrap align-middle">${row.age || '-'}</td>
            <td class="text-nowrap align-middle">${row.phone || '-'}</td>
            <td class="text-nowrap align-middle">${row.province || row.village || '-'}</td>
            <td class="text-center text-nowrap align-middle">${allergyBadge}</td>
            <td class="text-center text-nowrap align-middle">${refHtml}</td>
            <td class="text-center text-nowrap align-middle">${statusBadges}</td>
            <td class="text-center text-nowrap align-middle">${actionBtns}</td>
        </tr>`;
    });

    // 🌟 วาดปุ่ม Pagination พร้อมข้อความบอกจำนวนรวมที่มุมขวา
    if (paginationContainer) {
        paginationContainer.className = "mt-3 mb-2";
        let paginationHtml = `<div class="d-flex justify-content-between align-items-center w-100 px-3 flex-wrap gap-2">`;

        // 1. ช่องซ้าย (เว้นไว้เพื่อดัน Pagination ให้อยู่ตรงกลางสมมาตรกับช่องขวา)
        paginationHtml += `<div class="d-none d-md-block" style="min-width: 180px;"></div>`;

        // 2. ช่องกลาง (ตัวปุ่มแบ่งหน้า)
        paginationHtml += `<div class="d-flex justify-content-center align-items-center gap-1 flex-grow-1">`;
        if (totalPages > 1) {
            paginationHtml += `<button class="btn btn-sm btn-light border text-muted px-2.5 py-1" onclick="renderPatientsTable(${window.patientCurrentPage - 1})" ${window.patientCurrentPage === 1 ? 'disabled' : ''}><i class="bi bi-chevron-left"></i></button>`;

            for (let i = 1; i <= totalPages; i++) {
                if (i === 1 || i === totalPages || (i >= window.patientCurrentPage - 2 && i <= window.patientCurrentPage + 2)) {
                    const activeClass = i === window.patientCurrentPage ? 'btn-primary fw-bold' : 'btn-light border text-dark';
                    paginationHtml += `<button class="btn btn-sm ${activeClass} px-3 py-1" onclick="renderPatientsTable(${i})">${i}</button>`;
                } else if (i === window.patientCurrentPage - 3 || i === window.patientCurrentPage + 3) {
                    paginationHtml += `<span class="px-2 text-muted">...</span>`;
                }
            }

            paginationHtml += `<button class="btn btn-sm btn-light border text-muted px-2.5 py-1" onclick="renderPatientsTable(${window.patientCurrentPage + 1})" ${window.patientCurrentPage === totalPages ? 'disabled' : ''}><i class="bi bi-chevron-right"></i></button>`;
        }
        paginationHtml += `</div>`;

        // 3. ช่องขวา (จำนวนรายการ)
        const startItem = totalItems === 0 ? 0 : startIndex + 1;
        const endItem = Math.min(startIndex + PATIENTS_PER_PAGE, totalItems);
        paginationHtml += `
            <div class="text-end text-muted small fw-semibold" style="min-width: 180px;">
                แสดง ${startItem}-${endItem} จาก <span class="text-primary fw-bold">${totalItems}</span> รายการ
            </div>
        `;

        paginationHtml += `</div>`;
        paginationContainer.innerHTML = paginationHtml;
    }
}

function setPatientTodayFilter() {
    const todayStr = formatVientianeDate(getVientianeNow()); // ใช้เวลา UTC+7 ลาว/ไทย แก้ปัญหาวันผิดช่วงเช้ามืด
    const startInput = document.getElementById('patientFilterStartDate');
    const endInput = document.getElementById('patientFilterEndDate');
    if (startInput) startInput.value = todayStr;
    if (endInput) endInput.value = todayStr;
    filterPatients();
}

function clearPatientDateFilter() {
    const startInput = document.getElementById('patientFilterStartDate');
    const endInput = document.getElementById('patientFilterEndDate');
    if (startInput) startInput.value = '';
    if (endInput) endInput.value = '';
    filterPatients();
}

window.setPatientTodayFilter = setPatientTodayFilter;
window.clearPatientDateFilter = clearPatientDateFilter;

// =====================================
// Triage Status Filter (ຍັງບໍ່ໄດ້ຄັດກອງ / ສົ່ງຄັດກອງແລ້ວ)
// =====================================
function setTriageFilter(mode) {
    window.patientTriageFilter = mode; // 'all' | 'pending' | 'sent'

    // Use unified tab-active class: deactivate ALL tabs in the group first, then activate the target
    const allTabBtns = document.querySelectorAll('#triageFilterBtnGroup .btn');
    allTabBtns.forEach(function (btn) {
        btn.setAttribute('data-tab-active', 'false');
    });

    // Activate the correct button by its data-tab-mode attribute
    const targetBtn = document.querySelector('#triageFilterBtnGroup [data-tab-mode="' + mode + '"]');
    if (targetBtn) {
        targetBtn.setAttribute('data-tab-active', 'true');
    }

    filterPatients();
}
window.setTriageFilter = setTriageFilter;

// Activate "Today" tab (standalone — deactivates all triage filter tabs too)
function setPatientTodayTab() {
    const allTabBtns = document.querySelectorAll('#triageFilterBtnGroup .btn');
    allTabBtns.forEach(function (btn) {
        btn.setAttribute('data-tab-active', 'false');
    });
    const todayBtn = document.getElementById('btnFilterToday');
    if (todayBtn) todayBtn.setAttribute('data-tab-active', 'true');
    setPatientTodayFilter();
}
window.setPatientTodayTab = setPatientTodayTab;

