// หมายเหตุ: ฟังก์ชัน exportBillsExcel (ฉบับสมบูรณ์พร้อมตัวกรองวันที่และฟิลด์ครบถ้วน) ถูกประกาศไว้ที่ส่วนจัดการรายงานบิลด้านล่าง (บรรทัด ~18570)


// Export PDF จะถูกประกาศพร้อมกับ printBillsReport ด้านล่าง

// =====================================
// การบันทึกและส่งข้อมูล
// =====================================
async function submitAppointment() {
    const form = document.getElementById('appointmentForm');
    const editId = document.getElementById('appointmentEditId')?.value;
    const apptId = editId || form.displayApptId.value || generateId('APT');

    const apptTypeVal = document.getElementById('apptTypeAssisted')?.checked ? 'assisted' : 'direct';
    const selectedRefBy = (document.getElementById('apptReferredBySelect')?.value || null);

    const payload = {
        appointment_id: apptId,
        appointment_type: apptTypeVal,
        guest_name: form.guestName.value,
        guest_phone: form.guestPhone.value,
        appointment_date: form.appointmentDate.value,
        appointment_time: form.appointmentTime.value,
        reason: form.reason.value,
        status: form.status.value || 'รอ',
        referred_by: selectedRefBy
    };

    // อัปเดตข้อมูลลง LocalStorage ไว้เป็นแคชสำรอง
    try {
        if (selectedRefBy) {
            window.appointmentReferrersMap = JSON.parse(localStorage.getItem('clinic_appointment_referrers') || '{}');
            window.appointmentReferrersMap[apptId] = selectedRefBy;
            if (typeof window.safeSetLocalStorage === 'function') {
                window.safeSetLocalStorage('clinic_appointment_referrers', window.appointmentReferrersMap);
            } else {
                localStorage.setItem('clinic_appointment_referrers', JSON.stringify(window.appointmentReferrersMap));
            }
        } else if (window.appointmentReferrersMap && window.appointmentReferrersMap[apptId]) {
            delete window.appointmentReferrersMap[apptId];
            if (typeof window.safeSetLocalStorage === 'function') {
                window.safeSetLocalStorage('clinic_appointment_referrers', window.appointmentReferrersMap);
            } else {
                localStorage.setItem('clinic_appointment_referrers', JSON.stringify(window.appointmentReferrersMap));
            }
        }
    } catch (ex) {
        console.warn('clinic_appointment_referrers LocalStorage error:', ex);
    }

    Swal.fire({ title: 'กำลังบันทึก...', allowOutsideClick: false, didOpen: () => Swal.showLoading() });

    let error = null;

    // 🚀 ส่งข้อมูลตรงเข้า Database โดยไม่ตัด referred_by ทิ้งแล้ว
    if (editId) {
        const res = await _supabase.from('appointments').update(payload).eq('appointment_id', editId);
        error = res.error;
    } else {
        const res = await _supabase.from('appointments').insert([payload]);
        error = res.error;
    }

    if (error) {
        Swal.fire('ข้อผิดพลาด', error.message, 'error');
    } else {
        Swal.fire('สำเร็จ', editId ? 'แก้ไขรายการนัดหมายเรียบร้อยแล้ว' : 'บันทึกนัดหมายเรียบร้อยแล้ว', 'success');
        bootstrap.Modal.getOrCreateInstance(document.getElementById('addAppointmentModal')).hide();
        form.reset();
        if (document.getElementById('appointmentEditId')) document.getElementById('appointmentEditId').value = '';
        toggleApptReferrerField();
        loadAppointments();
    }
}

async function submitPatient() {
    const form = document.getElementById('patientForm');
    const editHn = document.getElementById('patientEditHn')?.value;
    const hn = editHn || ('HN-' + Math.floor(100000 + Math.random() * 900000));
    const linkApptId = document.getElementById('linkAppointmentId')?.value;
    const refByVal = (document.getElementById('patientReferredBySelect')?.value || null);

    try {
        if (refByVal) {
            window.patientReferrersMap = JSON.parse(localStorage.getItem('clinic_patient_referrers') || '{}');
            window.patientReferrersMap[hn] = refByVal;
            if (typeof window.safeSetLocalStorage === 'function') {
                window.safeSetLocalStorage('clinic_patient_referrers', window.patientReferrersMap);
            } else {
                localStorage.setItem('clinic_patient_referrers', JSON.stringify(window.patientReferrersMap));
            }
        } else if (window.patientReferrersMap && window.patientReferrersMap[hn]) {
            delete window.patientReferrersMap[hn];
            if (typeof window.safeSetLocalStorage === 'function') {
                window.safeSetLocalStorage('clinic_patient_referrers', window.patientReferrersMap);
            } else {
                localStorage.setItem('clinic_patient_referrers', JSON.stringify(window.patientReferrersMap));
            }
        }
    } catch (ex) {
        console.warn('clinic_patient_referrers LocalStorage error:', ex);
    }

    const patientData = {
        hn: hn,
        patient_name: form.FullName.value,
        dob: (form.DOB ? form.DOB.value : null) || null,
        age: parseInt(form.Age.value) || null,
        village: form.Village.value || null,
        district: (document.getElementById('patientDistrictSelect')?.value || form.District?.value || null),
        province: (document.getElementById('patientProvinceSelect')?.value || form.Province?.value || null),
        job: form.Job.value || null,
        phone: form.Tel.value,
        // 🌟 แก้ไข: ดึงค่าจากฟอร์มและส่งไปที่คอลัมน์ใหม่
        next_appointment_date: (form.NextAppointmentDate ? form.NextAppointmentDate.value : null) || null,
        past_history: form.PastHistory.value || null,
        allergies: form.Allergies.value || null,
        referred_by: refByVal,
        created_by: window.currentUser ? (window.currentUser.fullname || window.currentUser.name || window.currentUser.email) : null
    };

    Swal.fire({ title: 'กำลังบันทึก...', allowOutsideClick: false, didOpen: () => Swal.showLoading() });

    let patientErr = null;

    // 🚀 ส่งข้อมูลตรงเข้า Database โดยไม่ตัด referred_by ทิ้งแล้ว
    if (editHn) {
        const res = await _supabase.from('patients').update(patientData).eq('hn', editHn);
        patientErr = res.error;
    } else {
        const res = await _supabase.from('patients').insert([patientData]);
        patientErr = res.error;
    }

    if (patientErr) {
        Swal.fire('ข้อผิดพลาด', patientErr.message, 'error');
        return;
    }

    if (window.allPatients) {
        if (editHn) {
            const idx = window.allPatients.findIndex(x => x.hn === editHn);
            if (idx >= 0) window.allPatients[idx] = patientData;
        } else {
            window.allPatients.unshift(patientData);
        }
    }

    if (linkApptId) {
        await _supabase
            .from('appointments')
            .update({ status: 'เสร็จสิ้น' })
            .eq('appointment_id', linkApptId);
        loadAppointments();
    }

    bootstrap.Modal.getOrCreateInstance(document.getElementById('addPatientModal')).hide();
    form.reset();
    if (document.getElementById('patientEditHn')) document.getElementById('patientEditHn').value = '';

    // สั่งเปลี่ยนหน้าจอ (Redirect) ไปที่หน้า "ทะเบียนผู้ป่วย" (ID: registration) ทันที
    if (typeof showPage === 'function') {
        showPage('registration', document.getElementById('nav-registration'));
    }

    // โหลดข้อมูลใหม่เพื่อให้ตารางอัปเดต
    loadPatients();

    // แสดงข้อความแจ้งเตือนสำเร็จ
    Swal.fire('สำเร็จ', editHn ? 'แก้ไขประวัติผู้ป่วยเรียบร้อยแล้ว' : 'ลงทะเบียนผู้ป่วยและประวัติใหม่เรียบร้อยแล้ว', 'success').then(() => {
        if (typeof showPage === 'function') {
            showPage('registration', document.getElementById('nav-registration'));
        }
    });
}

function openAddPatientModal() {
    const form = document.getElementById('patientForm');
    if (form) form.reset();
    if (document.getElementById('patientEditHn')) document.getElementById('patientEditHn').value = '';
    if (document.getElementById('linkAppointmentId')) document.getElementById('linkAppointmentId').value = '';

    populateProvinceDropdown();
    onPatientProvinceChange();
    populateReferrerDropdowns();

    const patRefSelect = document.getElementById('patientReferredBySelect');
    const lockHint = document.getElementById('patientRefLockHint');
    if (patRefSelect) {
        patRefSelect.value = '';
        patRefSelect.removeAttribute('readonly');
        patRefSelect.style.pointerEvents = 'auto';
        patRefSelect.classList.remove('bg-light');

        // 🌟 Auto-select ผู้แนะนำตามผู้ใช้งานที่กำลัง Login อยู่
        let cur = window.currentUser;
        if (!cur) {
            try { cur = JSON.parse(localStorage.getItem('clinicUser') || 'null'); } catch (e) { }
        }
        if (cur) {
            let matchedRef = '';
            const allEmp = window.allEmployeesData || [];
            const empCode = (cur.emp_code || '').trim().toLowerCase();
            const curName = (cur.name || cur.full_name || '').trim().toLowerCase();

            const found = allEmp.find(e => {
                const c = (e.emp_code || '').toLowerCase().trim();
                const n = (e.full_name || '').toLowerCase().trim();
                if (empCode && c && c === empCode) return true;
                if (curName && n && (n.includes(curName) || curName.includes(n))) return true;
                return false;
            });

            if (found) {
                matchedRef = `${found.emp_code} - ${found.full_name}`;
            } else if (cur.emp_code && (cur.name || cur.full_name)) {
                matchedRef = `${cur.emp_code} - ${cur.name || cur.full_name}`;
            }

            if (matchedRef) {
                patRefSelect.value = matchedRef;
            }
        }
    }
    if (lockHint) lockHint.style.display = 'none';

    const modalTitle = document.querySelector('#addPatientModal .modal-title');
    if (modalTitle) modalTitle.textContent = 'ເພີ່ມປະຫວັດຜູ້ປ່ວຍໃໝ່';

    const patModalEl = document.getElementById('addPatientModal');
    if (patModalEl && !patModalEl.dataset.frameBound) {
        patModalEl.dataset.frameBound = 'true';
        patModalEl.addEventListener('click', function (e) {
            if (e.target === this) {
                bootstrap.Modal.getOrCreateInstance(this).hide();
            }
        });
        patModalEl.addEventListener('shown.bs.modal', function () {
            document.querySelectorAll('.modal-backdrop').forEach(el => el.remove());
            try {
                const frame = document.getElementById('marketingFrame');
                if (frame && frame.contentWindow) {
                    frame.contentWindow.postMessage('addPatientModalOpened', '*');
                }
            } catch (e) { }
        });
        patModalEl.addEventListener('hidden.bs.modal', function () {
            document.querySelectorAll('.modal-backdrop').forEach(el => el.remove());
            document.body.classList.remove('modal-open');
            document.body.style.removeProperty('overflow');
            document.body.style.removeProperty('padding-right');
            try {
                const frame = document.getElementById('marketingFrame');
                if (frame && frame.contentWindow) {
                    frame.contentWindow.postMessage('addPatientModalClosed', '*');
                }
            } catch (e) { }
        });
    }

    if (patModalEl) {
        bootstrap.Modal.getOrCreateInstance(patModalEl).show();
        document.querySelectorAll('.modal-backdrop').forEach(el => el.remove());
    }
}

function openRegisterFromAppointment(appId, name, phone) {
    const form = document.getElementById('patientForm');
    if (form) form.reset();
    if (form.FullName) form.FullName.value = name;
    if (form.Tel) form.Tel.value = phone;
    if (document.getElementById('patientEditHn')) document.getElementById('patientEditHn').value = '';
    document.getElementById('linkAppointmentId').value = appId;

    populateProvinceDropdown();
    onPatientProvinceChange();
    populateReferrerDropdowns();

    const patRefSelect = document.getElementById('patientReferredBySelect');
    const lockHint = document.getElementById('patientRefLockHint');

    // ดึงข้อมูลนัดหมายเพื่อตรวจดูว่ามีการระบุผู้แนะนำไว้หรือไม่
    const appt = (allAppointments || []).find(a => a.appointment_id === appId);
    if (appt && appt.referred_by && patRefSelect) {
        // หากมีผู้แนะนำจากการนัดหมายล่วงหน้า -> เติมข้อมูลอัตโนมัติและล็อกไม่ให้แก้ไข
        patRefSelect.value = appt.referred_by;
        patRefSelect.setAttribute('readonly', 'readonly');
        patRefSelect.style.pointerEvents = 'none';
        patRefSelect.classList.add('bg-light');
        if (lockHint) lockHint.style.display = 'inline-block';
    } else if (patRefSelect) {
        // หากไม่มีผู้แนะนำจากการนัดหมาย -> สามารถกรอก/พิมพ์ค้นหาได้ตามปกติ
        patRefSelect.value = '';
        patRefSelect.removeAttribute('readonly');
        patRefSelect.style.pointerEvents = 'auto';
        patRefSelect.classList.remove('bg-light');
        if (lockHint) lockHint.style.display = 'none';
    }

    const modalTitle = document.querySelector('#addPatientModal .modal-title');
    if (modalTitle) modalTitle.textContent = `ເພີ່ມປະຫວັດຜູ້ປ່ວຍໃໝ່ (ຈາກລາຍການນັດໝາຍ: ${appId})`;

    bootstrap.Modal.getOrCreateInstance(document.getElementById('addPatientModal')).show();
}

function editPatient(hn) {
    const patient = (window.allPatients || []).find(p => p.hn === hn);
    if (!patient) return;

    const form = document.getElementById('patientForm');
    if (!form) return;
    form.reset();

    if (document.getElementById('patientEditHn')) {
        document.getElementById('patientEditHn').value = patient.hn;
    }

    if (form.FullName) form.FullName.value = patient.patient_name || '';
    if (form.DOB) form.DOB.value = patient.dob || '';
    if (form.Age) form.Age.value = patient.age || '';
    if (form.Tel) form.Tel.value = patient.phone || '';
    // 🌟 แก้ไข: นำค่าจากฐานข้อมูลกลับมาใส่ในฟอร์มวันที่นัดมาตรวจ
    if (form.NextAppointmentDate) form.NextAppointmentDate.value = patient.next_appointment_date || '';
    if (form.Job) form.Job.value = patient.job || '';
    if (form.Village) form.Village.value = patient.village || '';
    if (form.PastHistory) form.PastHistory.value = patient.past_history || '';
    if (form.Allergies) form.Allergies.value = patient.allergies || '';

    populateProvinceDropdown();
    if (document.getElementById('patientProvinceSelect') && patient.province) {
        document.getElementById('patientProvinceSelect').value = patient.province;
        onPatientProvinceChange();
        if (document.getElementById('patientDistrictSelect') && patient.district) {
            document.getElementById('patientDistrictSelect').value = patient.district;
        }
    }

    populateReferrerDropdowns();
    const patRefSelect = document.getElementById('patientReferredBySelect');
    const lockHint = document.getElementById('patientRefLockHint');
    if (patRefSelect) {
        patRefSelect.value = patient.referred_by || '';
        if (patient.referred_by_from_appt) {
            patRefSelect.setAttribute('readonly', 'readonly');
            patRefSelect.style.pointerEvents = 'none';
            patRefSelect.classList.add('bg-light');
            if (lockHint) lockHint.style.display = 'inline-block';
        } else {
            patRefSelect.removeAttribute('readonly');
            patRefSelect.style.pointerEvents = 'auto';
            patRefSelect.classList.remove('bg-light');
            if (lockHint) lockHint.style.display = 'none';
        }
    }

    const modalTitle = document.querySelector('#addPatientModal .modal-title');
    if (modalTitle) modalTitle.textContent = `ແກ້ໄຂປະຫວັດຜູ້ປ່ວຍ (${patient.hn})`;

    bootstrap.Modal.getOrCreateInstance(document.getElementById('addPatientModal')).show();
}

async function deletePatient(hn) {
    const result = await Swal.fire({
        title: 'ยืนยันการลบประวัติผู้ป่วย?',
        text: `คุณต้องการลบผู้ป่วย HN: ${hn} ใช่หรือไม่?`,
        icon: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#d33',
        cancelButtonColor: '#3085d6',
        confirmButtonText: 'ใช่, ลบเลย',
        cancelButtonText: 'ยกเลิก'
    });

    if (result.isConfirmed) {
        Swal.fire({ title: 'กำลังลบ...', allowOutsideClick: false, didOpen: () => Swal.showLoading() });
        const { error } = await _supabase.from('patients').delete().eq('hn', hn);

        if (error) {
            Swal.fire('เกิดข้อผิดพลาด', error.message, 'error');
        } else {
            Swal.fire('สำเร็จ', 'ลบประวัติผู้ป่วยเรียบร้อยแล้ว', 'success');
            loadPatients();
        }
    }
}

async function sendToTriage(hn, name) {
    const visitId = generateId('VIS');
    const visitData = {
        visit_id: visitId,
        hn: hn,
        patient_name: name,
        status: 'รอคัดกรอง'
    };

    Swal.fire({ title: 'กำลังส่งข้อมูล...', allowOutsideClick: false, didOpen: () => Swal.showLoading() });

    const { error } = await _supabase
        .from('visits')
        .insert([visitData]);

    if (error) {
        Swal.fire('ข้อผิดพลาด', error.message, 'error');
    } else {
        Swal.fire('สำเร็จ', 'เพิ่มเข้าคิวคัดกรองแล้ว', 'success');
        showPage('triage', document.querySelector('a[onclick*="triage"]'));
        loadTriage();
        if (typeof loadPatients === 'function') loadPatients();
    }
}

async function openTriageModal(visitId) {
    const form = document.getElementById('triageForm');
    if (form) form.reset();
    const vInput = document.getElementById('triageVisitId');
    if (vInput) vInput.value = visitId;

    // ดึงข้อมูลเดิมของ visit นี้มาแสดงเผื่อมีการบันทึกค้างไว้
    if (typeof _supabase !== 'undefined' && visitId) {
        try {
            const { data } = await _supabase.from('visits').select('*').eq('visit_id', visitId).maybeSingle();
            if (data && form) {
                if (data.temp && form.temp) form.temp.value = data.temp;
                if (data.bp && form.bp) form.bp.value = data.bp;
                if (data.pulse && form.pulse) form.pulse.value = data.pulse;
                if (data.weight && form.weight) form.weight.value = data.weight;
                if (data.height && form.height) form.height.value = data.height;
                if (data.bmi && form.bmi) form.bmi.value = data.bmi;
                if (data.spo2 && form.spo2) form.spo2.value = data.spo2;
                if (data.symptom && form.symptom) form.symptom.value = data.symptom;
            }
        } catch (e) {
            console.warn('Could not prefetch visit triage info:', e);
        }
    }

    bootstrap.Modal.getOrCreateInstance(document.getElementById('triageModal')).show();
}

async function submitTriage() {
    if (typeof navigator !== 'undefined' && navigator.onLine === false) {
        Swal.fire({
            icon: 'warning',
            title: 'สัญญาณอินเทอร์เน็ตขาดหาย (Offline)',
            text: 'อุปกรณ์ขาดการเชื่อมต่ออินเทอร์เน็ต กรุณาตรวจสอบ Wi-Fi หรือการเชื่อมต่อเครือข่ายก่อนส่งข้อมูลเข้าห้องตรวจ'
        });
        return;
    }

    const form = document.getElementById('triageForm');
    const visitId = document.getElementById('triageVisitId')?.value || form?.visitId?.value;

    if (!visitId) {
        Swal.fire('ข้อผิดพลาด', 'ไม่พบรหัสการตรวจ (Visit ID) กรุณาลองใหม่อีกครั้ง', 'error');
        return;
    }

    const triageData = {
        temp: form.temp?.value ? parseFloat(form.temp.value) : null,
        bp: form.bp?.value?.trim() || null,
        pulse: form.pulse?.value ? parseInt(form.pulse.value) : null,
        weight: form.weight?.value ? parseFloat(form.weight.value) : null,
        height: form.height?.value ? parseFloat(form.height.value) : null,
        bmi: form.bmi?.value ? parseFloat(form.bmi.value) : null,
        spo2: form.spo2?.value ? parseInt(form.spo2.value) : null,
        symptom: form.symptom?.value?.trim() || null,
        status: 'รอตรวจ'
    };

    Swal.fire({ title: 'กำลังส่งข้อมูล...', allowOutsideClick: false, didOpen: () => Swal.showLoading() });

    const { error } = await _supabase
        .from('visits')
        .update(triageData)
        .eq('visit_id', visitId);

    if (error) {
        Swal.fire('ข้อผิดพลาด', error.message, 'error');
    } else {
        bootstrap.Modal.getOrCreateInstance(document.getElementById('triageModal')).hide();
        if (typeof loadTriage === 'function') loadTriage();
        if (typeof loadTriageHistory === 'function') loadTriageHistory();
        if (typeof loadDoctorQueue === 'function') loadDoctorQueue();
        if (typeof loadPatients === 'function') loadPatients();

        Swal.fire({
            icon: 'success',
            title: 'ส่งเข้าห้องตรวจแล้ว',
            html: `รหัสตรวจ: <strong>${visitId}</strong> ได้ถูกส่งไปยังห้องตรวจแพทย์เรียบร้อยแล้ว`,
            showCancelButton: true,
            confirmButtonText: '<i class="bi bi-person-check me-1"></i>ไปที่ห้องตรวจแพทย์',
            cancelButtonText: 'อยู่ที่หน้านี้ต่อ',
            confirmButtonColor: '#0d6efd'
        }).then((result) => {
            if (result.isConfirmed) {
                showPage('doctor', document.querySelector('a[onclick*="doctor"]'));
            }
        });
    }
}

window.selectedLabCategory = 'เลือดวิทยา (HEMATOLOGY)';
window.checkedLabState = {};

function getServiceCategory(s) {
    if (!s) return 'อื่นๆ (Other)';

    if (s.category && typeof s.category === 'string' && s.category.trim()) {
        const cat = s.category.trim();
        if (cat.includes('เลือดวิทยา') || cat.includes('HEMATOLOGY')) return 'เลือดวิทยา (HEMATOLOGY)';
        if (cat.includes('ชีวเคมี') || cat.includes('Biochemistry')) return 'ชีวเคมี (Biochemistry)';
        if (cat.includes('ภูมิคุ้มกัน') || cat.includes('Immunology')) return 'ภูมิคุ้มกันวิทยา (Immunology)';
        if (cat.includes('ปัสสาวะ') || cat.includes('อุจจาระ') || cat.includes('Urinalysis') || cat.includes('Stool')) return 'ปัสสาวะและอุจจาระ (Urinalysis, Stool Examination, and Other)';
        if (cat.includes('อื่นๆ') || cat.includes('Other')) return 'อื่นๆ (Other)';
        return cat;
    }

    const name = (s.name || s.id || '').toLowerCase().trim();

    // 1. เลือดวิทยา (HEMATOLOGY)
    if (
        name.includes('cbc') || name.includes('blood count') || name.includes('hemoglobin') ||
        name.includes('hematocrit') || name.includes('hct') || name.includes('wbc') ||
        name.includes('rbc') || name.includes('platelet') || name.includes('thalassemia') ||
        name.includes('esr') || name.includes('coagulation') || name.includes('forgesterone') ||
        name.includes('เม็ดเลือด') || name.includes('เกล็ดเลือด')
    ) {
        return 'เลือดวิทยา (HEMATOLOGY)';
    }

    // 2. ชีวเคมี (Biochemistry)
    if (
        name.includes('electrolyte') || name.includes('fbs') || name.includes('glucose') ||
        name.includes('hba1c') || name.includes('bun') || name.includes('creatinine') ||
        name.includes('gfr') || name.includes('uric') || name.includes('sgot') ||
        name.includes('sgpt') || name.includes('alp') || name.includes('ast') ||
        name.includes('alt') || name.includes('lipid') || name.includes('cholesterol') ||
        name.includes('triglyceride') || name.includes('hdl') || name.includes('ldl') ||
        name.includes('ferritin') || name.includes('dosage hormone') || name.includes('troponin') ||
        name.includes('t3') || name.includes('t4') || name.includes('tsh') || name.includes('ตับ') || name.includes('ไต')
    ) {
        return 'ชีวเคมี (Biochemistry)';
    }

    // 3. ภูมิคุ้มกันวิทยา (Immunology)
    if (
        name.includes('hpv') || name.includes('hiv') || name.includes('hbsag') ||
        name.includes('hbsab') || name.includes('hcv') || name.includes('vdrl') ||
        name.includes('syphilis') || name.includes('syphillis') || name.includes('dengue') || name.includes('allergy') ||
        name.includes('ca 153') || name.includes('ca 15-3') || name.includes('ca 125') ||
        name.includes('ca 199') || name.includes('ca 19-9') || name.includes('cea') ||
        name.includes('psa') || name.includes('afp') || name.includes('cyfra') ||
        name.includes('crp') || name.includes('aslo') || name.includes('rheumatoid') ||
        name.includes('h.pylori') || name.includes('h-pylori') || name.includes('pylori') || name.includes('sle') ||
        name.includes('viral load') || name.includes('ภูมิคุ้มกัน') || name.includes('มะเร็ง')
    ) {
        return 'ภูมิคุ้มกันวิทยา (Immunology)';
    }

    // 4. ปัสสาวะและอุจจาระ (Urinalysis, Stool Examination, and Other)
    if (
        name.includes('urinalysis') || name.includes('stool') || name.includes('urine') ||
        name.includes('ua') || name.includes('fecal') || name.includes('parasite') ||
        name.includes('ปัสสาวะ') || name.includes('อุจจาระ')
    ) {
        return 'ปัสสาวะและอุจจาระ (Urinalysis, Stool Examination, and Other)';
    }

    // 5. อื่นๆ (Other)
    if (
        name.includes('echo') || name.includes('abdominal') || name.includes('sperm') ||
        name.includes('spermogramme') || name.includes('pap') || name.includes('cytology') ||
        name.includes('ultrasound')
    ) {
        return 'อื่นๆ (Other)';
    }

    return 'อื่นๆ (Other)';
}

function isCategoryMatch(itemCategory, targetCategory) {
    if (!targetCategory || targetCategory === 'ALL' || targetCategory === 'ทั้งหมด (All)') return true;
    const cat = (itemCategory || '').toLowerCase().trim();
    const target = targetCategory.toLowerCase().trim();

    if (cat === target) return true;

    if (target.includes('เลือดวิทยา') || target.includes('hematology')) {
        return cat.includes('เลือดวิทยา') || cat.includes('hematology');
    }
    if (target.includes('ชีวเคมี') || target.includes('biochemistry')) {
        return cat.includes('ชีวเคมี') || cat.includes('biochemistry');
    }
    if (target.includes('ภูมิคุ้มกัน') || target.includes('immunology')) {
        return cat.includes('ภูมิคุ้มกัน') || cat.includes('immunology');
    }
    if (target.includes('ปัสสาวะ') || target.includes('urinalysis') || target.includes('stool') || target.includes('อุจจาระ')) {
        return cat.includes('ปัสสาวะ') || cat.includes('urinalysis') || cat.includes('stool') || cat.includes('อุจจาระ');
    }
    if (target.includes('อื่นๆ') || target.includes('other')) {
        return cat.includes('อื่นๆ') || cat.includes('other');
    }

    return false;
}

// =====================================
// ระบบห้อง Lab - รองรับ Pagination 15 รายการ/หน้า และตัวกรองค้นหา/วันที่
// =====================================
window.labQueueData = []; // เก็บข้อมูลทั้งหมด
window.labFilteredData = []; // เก็บข้อมูลที่ผ่านการกรอง
window.labCurrentPage = 1; // หน้าปัจจุบัน
const LAB_PER_PAGE = 15; // จำนวน 15 รายการต่อหน้า

// 1. ดึงข้อมูลจากฐานข้อมูลมาเก็บไว้
async function loadLabQueue() {
    const tbody = document.querySelector('#labTable tbody');
    if (!tbody) return;

    // 🌟 ตั้งค่าเริ่มต้นตัวกรองวันที่ของห้อง Lab ให้เป็นวันปัจจุบัน (Today - Asia/Vientiane) หากยังไม่ได้เลือกช่วงวันที่
    let startInput = document.getElementById('labStartDate');
    let endInput = document.getElementById('labEndDate');
    if ((!startInput?.value || !endInput?.value) && !window._labFilterExplicitAll) {
        const todayRange = getVientianeDateRange('today');
        if (startInput && !startInput.value) startInput.value = todayRange.startStr;
        if (endInput && !endInput.value) endInput.value = todayRange.endStr;
    }

    const startDate = startInput?.value;
    const endDate = endInput?.value;

    tbody.innerHTML = '<tr><td colspan="8" class="text-center text-muted py-5"><div class="spinner-border spinner-border-sm text-primary me-2"></div>กำลังโหลดข้อมูล...</td></tr>';

    let labQuery = _supabase
        .from('visits')
        .select('visit_id, hn, patient_name, doctor_name, status, lab_tests, lab_note, pdf_url, created_at')
        .in('status', ['รอผลแล็บ', 'รอผลตรวจ Lab', 'รอผลแล็บเพิ่มเติม', 'ผลออกบางส่วน']);

    if (startDate) {
        labQuery = labQuery.gte('created_at', startDate + "T00:00:00");
    }
    if (endDate) {
        labQuery = labQuery.lte('created_at', endDate + "T23:59:59");
    }

    const { data, error } = await labQuery.order('created_at', { ascending: true }).limit(100);

    if (error) {
        tbody.innerHTML = `<tr><td colspan="8" class="text-center text-danger py-3">เกิดข้อผิดพลาด: ${error.message}</td></tr>`;
        return;
    }

    let processedData = data || [];

    // 🌟 ดึงเคสที่เป็น "รอผลแล็บเพิ่มเติม" (Partial Lab) เข้ามาแสดงในห้อง Lab ด้วย
    window._clinicPartialLabsMap = {};
    try {
        window._clinicPartialLabsMap = JSON.parse(localStorage.getItem('clinic_partial_labs') || '{}');
    } catch (e) { }

    try {
        const existingIds = new Set(processedData.map(r => r.visit_id));

        // 1. ดึงจาก Supabase ที่มีคำว่า รอผลแล็บเพิ่มเติม ใน lab_note
        const { data: partialDbData } = await _supabase
            .from('visits')
            .select('visit_id, hn, patient_name, doctor_name, status, lab_tests, lab_note, pdf_url, created_at')
            .like('lab_note', '%รอผลแล็บเพิ่มเติม%')
            .neq('status', 'ຍົກເລີກ')
            .limit(50);

        if (partialDbData && partialDbData.length > 0) {
            partialDbData.forEach(pRow => {
                if (pRow.status === 'รอจัดคิว') {
                    pRow.status = 'รอผลแล็บเพิ่มเติม';
                    _supabase.from('visits').update({ status: 'รอผลแล็บเพิ่มเติม' }).eq('visit_id', pRow.visit_id).then(() => { });
                }
                if (!existingIds.has(pRow.visit_id)) {
                    existingIds.add(pRow.visit_id);
                    processedData.push(pRow);
                }
            });
        }

        // 2. ตรวจสอบเคสที่มีใน LocalStorage clinic_partial_labs
        const localPartialIds = Object.keys(window._clinicPartialLabsMap || {}).filter(vid => !existingIds.has(vid));
        if (localPartialIds.length > 0) {
            const { data: localDbVisits } = await _supabase
                .from('visits')
                .select('visit_id, hn, patient_name, doctor_name, status, lab_tests, lab_note, pdf_url, created_at')
                .in('visit_id', localPartialIds)
                .neq('status', 'ຍົກເລີກ');

            if (localDbVisits && localDbVisits.length > 0) {
                localDbVisits.forEach(lpRow => {
                    if (lpRow.status === 'รอจัดคิว') {
                        lpRow.status = 'รอผลแล็บเพิ่มเติม';
                        _supabase.from('visits').update({ status: 'รอผลแล็บเพิ่มเติม' }).eq('visit_id', lpRow.visit_id).then(() => { });
                    }
                    if (!existingIds.has(lpRow.visit_id)) {
                        existingIds.add(lpRow.visit_id);
                        processedData.push(lpRow);
                    }
                });
            }
        }
    } catch (errPartial) {
        console.warn('loadLabQueue partial check warning:', errPartial);
    }

    // เติม HN สำหรับเคสที่ยังไม่มี HN (ค้นหาเฉพาะรายชื่อที่ต้องการ ไม่โหลดทั้งระบบ)
    const exactNameMap = {};
    const normNameMap = {};
    const missingNames = processedData.filter(r => !r.hn || r.hn === '-' || r.hn === 'null').map(r => r.patient_name).filter(Boolean);
    if (missingNames.length > 0) {
        try {
            const { data: pList } = await _supabase.from('patients').select('hn, patient_name').in('patient_name', missingNames);
            if (pList && pList.length > 0) {
                pList.forEach(p => {
                    const pName = (p.patient_name || '').trim();
                    const pHn = (p.hn && p.hn !== 'null' && p.hn !== 'undefined' && p.hn !== '-') ? p.hn.trim() : '';
                    if (pHn && pName) {
                        exactNameMap[pName.toLowerCase()] = pHn;
                        const normP = typeof normalizeClinicPatientName === 'function' ? normalizeClinicPatientName(pName) : pName.toLowerCase();
                        if (normP) normNameMap[normP] = pHn;
                    }
                });
            }
        } catch (e) {
            console.warn('loadLabQueue missing HN lookup notice:', e);
        }
    }

    processedData.forEach(row => {
        let rowHn = (row.hn && row.hn !== 'null' && row.hn !== 'undefined' && row.hn !== '-') ? row.hn.trim() : '';
        if (!rowHn) {
            const rawName = (row.patient_name || '').trim();
            const lowerName = rawName.toLowerCase();
            const normName = typeof normalizeClinicPatientName === 'function' ? normalizeClinicPatientName(rawName) : lowerName;

            let matchedHn = exactNameMap[lowerName] || normNameMap[normName];

            if (!matchedHn && normName && normName.length >= 2) {
                for (const p of allPatientsList) {
                    const pName = (p.patient_name || p.name || '').trim();
                    const pHn = (p.hn && p.hn !== 'null' && p.hn !== 'undefined' && p.hn !== '-') ? p.hn.trim() : '';
                    const pNorm = typeof normalizeClinicPatientName === 'function' ? normalizeClinicPatientName(pName) : pName.toLowerCase();
                    if (pHn && pNorm && (pNorm.includes(normName) || normName.includes(pNorm))) {
                        matchedHn = pHn;
                        break;
                    }
                }
            }

            if (matchedHn) {
                row.hn = matchedHn;
                _supabase.from('visits').update({ hn: matchedHn }).eq('visit_id', row.visit_id).then(() => { });
            }
        }
    });

    window.labQueueData = processedData;
    filterLabTable(); // กรองข้อมูลและแสดงผล
}

// 2. ฟังก์ชันจัดวันที่ให้ปุ่มกด วันนี้, เดือนนี้, ปีนี้, ทั้งหมด
window.setLabDateFilter = function (mode) {
    const startInput = document.getElementById('labStartDate');
    const endInput = document.getElementById('labEndDate');

    if (mode === 'all') {
        window._labFilterExplicitAll = true;
        if (startInput) startInput.value = '';
        if (endInput) endInput.value = '';
        if (typeof loadLabQueue === 'function') loadLabQueue();
        return;
    }
    window._labFilterExplicitAll = false;

    if (mode === 'year') {
        const vNow = getVientianeNow();
        if (startInput) startInput.value = `${vNow.getFullYear()}-01-01`;
        if (endInput) endInput.value = `${vNow.getFullYear()}-12-31`;
        if (typeof loadLabQueue === 'function') loadLabQueue();
        return;
    }

    let filterType = mode;
    if (mode === 'month') filterType = 'thisMonth';
    applyQuickDateFilter(filterType, 'labStartDate', 'labEndDate', () => {
        if (typeof loadLabQueue === 'function') loadLabQueue();
    });
};

// 3. ฟังก์ชันกรองข้อมูลตามวันที่และข้อความที่ค้นหา
window.filterLabTable = function () {
    if (!window.labQueueData) return;

    let filtered = window.labQueueData;

    // กรองด้วยวันที่
    const startDateStr = document.getElementById('labStartDate')?.value;
    const endDateStr = document.getElementById('labEndDate')?.value;

    if (startDateStr || endDateStr) {
        window._labFilterExplicitAll = false;
        filtered = filtered.filter(row => {
            // 🌟 เคสที่เป็น Partial Lab (รอผลเพิ่มเติม) ให้แสดงเสมอ แม้ว่าวันที่ส่งตรวจจะเป็นวันก่อนหน้า (เช่น 3 วันที่แล้ว)
            const isPartial = row.status === 'รอผลแล็บเพิ่มเติม' ||
                row.status === 'ผลออกบางส่วน' ||
                (row.lab_note && row.lab_note.includes('รอผลแล็บเพิ่มเติม')) ||
                (window._clinicPartialLabsMap && window._clinicPartialLabsMap[row.visit_id]);
            if (isPartial) return true;

            if (!row.created_at) return true;
            const d = new Date(row.created_at);
            const rowYear = d.getFullYear();
            const rowMonth = String(d.getMonth() + 1).padStart(2, '0');
            const rowDay = String(d.getDate()).padStart(2, '0');
            const rowDate = `${rowYear}-${rowMonth}-${rowDay}`;

            let pass = true;
            if (startDateStr && rowDate < startDateStr) pass = false;
            if (endDateStr && rowDate > endDateStr) pass = false;
            return pass;
        });
    }

    // กรองด้วยช่องค้นหา (ชื่อ, HN, VIS)
    const q = (document.getElementById('searchLabInput')?.value || '').toLowerCase().trim();
    if (q) {
        filtered = filtered.filter(row =>
            (row.visit_id && row.visit_id.toLowerCase().includes(q)) ||
            (row.hn && row.hn.toLowerCase().includes(q)) ||
            (row.patient_name && row.patient_name.toLowerCase().includes(q))
        );
    }

    window.labFilteredData = filtered;
    window.labCurrentPage = 1; // รีเซ็ตกลับไปหน้า 1 เสมอเมื่อมีการค้นหา
    renderLabTable();
};

// 4. ฟังก์ชันตัดข้อมูลทีละ 15 รายการและสร้างปุ่มแบ่งหน้า
window.renderLabTable = function (page = window.labCurrentPage) {
    window.labCurrentPage = page;
    const tbody = document.querySelector('#labTable tbody');
    const paginationContainer = document.getElementById('labPagination');
    if (!tbody) return;

    tbody.innerHTML = '';

    const dataSource = window.labFilteredData || window.labQueueData || [];

    // กรณีไม่มีข้อมูล
    if (!dataSource || dataSource.length === 0) {
        const emptyText = typeof t === 'function' ? t('lab_empty', 'ไม่มีรายการรอตรวจ Lab') : 'ไม่มีรายการรอตรวจ Lab';
        tbody.innerHTML = `<tr><td colspan="8" class="text-center text-muted py-5">${emptyText}</td></tr>`;
        if (paginationContainer) paginationContainer.innerHTML = '';
        return;
    }

    // คำนวณจำนวนหน้า
    const totalItems = dataSource.length;
    const totalPages = Math.ceil(totalItems / LAB_PER_PAGE);

    if (window.labCurrentPage > totalPages) window.labCurrentPage = totalPages;
    if (window.labCurrentPage < 1) window.labCurrentPage = 1;

    // หาจุดเริ่มต้นและจุดสิ้นสุด
    const startIndex = (window.labCurrentPage - 1) * LAB_PER_PAGE;
    const endIndex = startIndex + LAB_PER_PAGE;

    // ตัดข้อมูล (Slice) มา 15 รายการ
    const currentData = dataSource.slice(startIndex, endIndex);

    const itemsLabel = typeof t === 'function' ? t('lab_btn_items', 'รายการส่งแล็บ') : 'รายการส่งแล็บ';
    const pendingLabel = typeof t === 'function' ? t('lab_status_pending', 'รอผลแล็บ') : 'รอผลแล็บ';
    const uploadLabel = typeof t === 'function' ? t('lab_btn_upload', 'อัปโหลดผล') : 'อัปโหลดผล';

    let cachedVascularMap = {};
    try { cachedVascularMap = JSON.parse(localStorage.getItem('clinic_vascular_results') || '{}'); } catch (e) { }

    currentData.forEach((row, idx) => {
        let no = startIndex + idx + 1; // ลำดับที่แบบต่อเนื่อง
        const hnDisplay = row.hn || '-';
        const testCount = row.lab_tests ? row.lab_tests.split(',').filter(Boolean).length : 0;
        const safeName = (row.patient_name || '').replace(/'/g, "\\'");

        window.labRowCache = window.labRowCache || {};
        window.labRowCache[row.visit_id] = {
            visitId: row.visit_id,
            hn: row.hn,
            patientName: row.patient_name || '',
            labTests: row.lab_tests || '',
            labNote: row.lab_note || ''
        };

        const hasAddOn = (row.lab_note && (row.lab_note.includes('ສັ່ງກວດເພີ່ມ') || row.lab_note.includes('ตรวจเพิ่ม')));
        const addOnBadgeHtml = hasAddOn
            ? `<span class="badge bg-warning text-dark border border-warning px-2 py-0.5 rounded-pill fw-bold ms-1" style="font-size: 0.72rem;"><i class="bi bi-plus-circle-fill me-1"></i>ສັ່ງກວດເພີ່ມ</span>`
            : '';
        let labDetailsHtml = `<button class="btn btn-sm btn-light border" onclick="viewLabDetailsByVisitId('${row.visit_id}')"><i class="ph ph-flask text-primary me-1"></i> ${itemsLabel} (${testCount} รายการ)</button>`;

        const filesList = getLabFilesForVisit(row.visit_id, row.pdf_url);
        const cachedVasc = cachedVascularMap[row.visit_id];
        const hasVascNote = (row.lab_note && row.lab_note.includes('[ผลตรวจหลอดเลือด]'));
        const vascText = hasVascNote ? row.lab_note : (cachedVasc ? cachedVasc.resultText : '');

        let allResultButtons = [];

        filesList.forEach((fileItem) => {
            const catName = fileItem.category || 'ผลแล็บ';
            let btnIcon = 'bi-file-earmark-pdf';
            let btnClass = 'btn-outline-danger';

            if (catName === 'เอโก') { btnIcon = 'bi-activity'; btnClass = 'btn-outline-primary'; }
            else if (catName === 'เอ็กซเรย์') { btnIcon = 'bi-file-earmark-medical'; btnClass = 'btn-outline-info'; }
            else if (catName === 'ตรวจเลือด') { btnIcon = 'bi-droplet-fill'; btnClass = 'btn-outline-danger'; }
            else if (catName === 'ตรวจหลอดเลือด') { btnIcon = 'bi-heart-pulse-fill'; btnClass = 'btn-outline-warning'; }
            else { btnIcon = 'bi-file-earmark-text'; btnClass = 'btn-outline-secondary'; }

            const safeCat = catName.replace(/'/g, "\\'");
            allResultButtons.push(`
                <button class="btn btn-sm ${btnClass} me-1 mb-1" onclick="viewRealLabFile('', '${row.visit_id}', '${safeName}', '${safeCat}')">
                    <i class="bi ${btnIcon} me-1"></i> ${catName}
                </button>
            `);
        });

        if (vascText) {
            allResultButtons.push(`
                <button type="button" class="btn btn-sm btn-outline-danger me-1 mb-1 fw-semibold" title="ເບິ່ງ / ພິມລາຍງານ PDF" onclick="openVascularReportPopup('${row.visit_id}')">
                    <i class="bi bi-file-earmark-pdf me-1"></i> ຜົນວິນິດໄສ (PDF)
                </button>
            `);
        }

        let allResultDisplay = allResultButtons.length > 0 ? allResultButtons.join(' ') : `<span class="text-muted">-</span>`;

        // 🌟 ตรวจสอบว่าเป็นเคสที่รอผลแล็บเพิ่มเติม (Partial Lab) หรือไม่
        const isPartialLab = row.status === 'รอผลแล็บเพิ่มเติม' ||
            row.status === 'ผลออกบางส่วน' ||
            (row.lab_note && row.lab_note.includes('รอผลแล็บเพิ่มเติม')) ||
            (window._clinicPartialLabsMap && window._clinicPartialLabsMap[row.visit_id]);

        let statusBadgeHtml = `<span class="badge-soft-warning">${pendingLabel}</span>`;
        if (isPartialLab) {
            let partialNoteText = 'ລໍຖ້າຜົນເພີ່ມເຕີມ';
            if (row.lab_note && row.lab_note.includes('รอผลแล็บเพิ่มเติม')) {
                const m = row.lab_note.match(/\[รอผลแล็บเพิ่มเติม(?::\s*([^\]]*))?\]/);
                if (m && m[1]) partialNoteText = m[1].trim();
            } else if (window._clinicPartialLabsMap && window._clinicPartialLabsMap[row.visit_id]) {
                partialNoteText = window._clinicPartialLabsMap[row.visit_id].pendingNote || partialNoteText;
            }
            statusBadgeHtml = `<span class="badge" style="background-color: #f59e0b; color: #fff; font-size: 11.5px; padding: 5px 9px; border-radius: 6px; font-weight: 600;" title="${partialNoteText}"><i class="bi bi-hourglass-split me-1"></i>${partialNoteText}</span>`;
        }

        let queueBtnHtml = isPartialLab
            ? `<button class="btn btn-sm btn-warning text-dark fw-bold ms-1 shadow-sm" onclick="sendToReportQueue('${row.visit_id}')"><i class="bi bi-check2-all me-1"></i>ສົ່ງອ່ານຜົນຄົບຖ້ວນ</button>`
            : `<button class="btn btn-sm btn-outline-primary ms-1" onclick="sendToReportQueue('${row.visit_id}')">ຈັດຄິວອ່ານຜົນກວດ</button>`;

        tbody.innerHTML += `
            <tr>
                <td class="ps-4 text-center fw-semibold text-secondary">${no}</td>
                <td class="fw-bold text-primary">${row.visit_id}</td>
                <td>${hnDisplay}</td>
                <td class="fw-bold">${row.patient_name}${addOnBadgeHtml}</td>
                <td>${labDetailsHtml}</td>
                <td class="text-center">${allResultDisplay}</td>
                <td>${statusBadgeHtml}</td>
                <td class="text-center text-nowrap">
                    <button class="btn btn-sm btn-primary px-3" onclick="openLabUploadModal('${row.visit_id}')"><i class="bi bi-upload"></i> ${uploadLabel}</button>
                    ${queueBtnHtml}
                </td>
            </tr>
        `;
    });

    // วาดกล่องตัวเลขแบ่งหน้าและข้อความนับจำนวน
    if (paginationContainer) {
        let paginationHtml = `<div class="d-flex justify-content-between align-items-center w-100 px-3 flex-wrap gap-2">`;
        paginationHtml += `<div class="d-none d-md-block" style="min-width: 180px;"></div>`;
        paginationHtml += `<div class="d-flex justify-content-center align-items-center gap-1 flex-grow-1">`;

        if (totalPages > 1) {
            paginationHtml += `<button class="btn btn-sm btn-light border text-muted px-2.5 py-1" onclick="renderLabTable(${window.labCurrentPage - 1})" ${window.labCurrentPage === 1 ? 'disabled' : ''}><i class="bi bi-chevron-left"></i></button>`;

            for (let i = 1; i <= totalPages; i++) {
                if (i === 1 || i === totalPages || (i >= window.labCurrentPage - 2 && i <= window.labCurrentPage + 2)) {
                    const activeClass = i === window.labCurrentPage ? 'btn-primary fw-bold' : 'btn-light border text-dark';
                    paginationHtml += `<button class="btn btn-sm ${activeClass} px-3 py-1" onclick="renderLabTable(${i})">${i}</button>`;
                } else if (i === window.labCurrentPage - 3 || i === window.labCurrentPage + 3) {
                    paginationHtml += `<span class="px-2 text-muted">...</span>`;
                }
            }

            paginationHtml += `<button class="btn btn-sm btn-light border text-muted px-2.5 py-1" onclick="renderLabTable(${window.labCurrentPage + 1})" ${window.labCurrentPage === totalPages ? 'disabled' : ''}><i class="bi bi-chevron-right"></i></button>`;
        }
        paginationHtml += `</div>`;

        const startItem = totalItems === 0 ? 0 : startIndex + 1;
        const endItem = Math.min(startIndex + LAB_PER_PAGE, totalItems);
        paginationHtml += `
            <div class="text-end text-muted small fw-semibold" style="min-width: 180px;">
                แสดง ${startItem}-${endItem} จาก <span class="text-primary fw-bold">${totalItems}</span> รายการ
            </div>
        </div>`;

        paginationContainer.innerHTML = paginationHtml;
    }
};

function handleLabCheckboxChange(inputEl, serviceName, price) {
    window.checkedLabState = window.checkedLabState || {};
    if (inputEl.checked) {
        window.checkedLabState[serviceName] = {
            name: serviceName,
            price: parseFloat(price) || 0
        };
    } else {
        delete window.checkedLabState[serviceName];
    }
    updateLabTotals();
}

function switchLabCategory(categoryName, btnEl) {
    window.selectedLabCategory = categoryName;
    if (btnEl) {
        document.querySelectorAll('#labCategoryTabs .lab-cat-tab').forEach(b => {
            b.classList.remove('active', 'fw-semibold');
            b.classList.add('text-secondary');
            b.style.color = '';
            b.style.borderBottom = 'none';
        });
        btnEl.classList.remove('text-secondary');
        btnEl.classList.add('active', 'fw-semibold');
        btnEl.style.color = '#0284c7';
        btnEl.style.borderBottom = '2px solid #0284c7';
        btnEl.style.paddingBottom = '6px';
    }
    renderServicesLabContainer();
}

function updateLabTotals() {
    window.checkedLabState = window.checkedLabState || {};
    const stateItems = Object.values(window.checkedLabState);

    // Count custom lab checkboxes in #customLabContainer if not in window.checkedLabState
    const customBoxes = document.querySelectorAll('#customLabContainer input[name="lab"]:checked');
    let customCount = 0;
    let customPriceTotal = 0;
    customBoxes.forEach(cb => {
        if (!window.checkedLabState[cb.value]) {
            customCount++;
            if (cb.dataset.price) {
                customPriceTotal += parseFloat(cb.dataset.price) || 0;
            }
        }
    });

    const totalItems = stateItems.length + customCount;
    let totalPrice = customPriceTotal;
    stateItems.forEach(item => {
        totalPrice += (parseFloat(item.price) || 0);
    });

    const countEl = document.getElementById('labTotalItemsCount');
    const priceEl = document.getElementById('labTotalPriceDisplay');
    if (countEl) countEl.textContent = totalItems;
    if (priceEl) priceEl.textContent = totalPrice.toLocaleString() + ' LAK';
}

function renderServicesLabContainer() {
    const customContainer = document.getElementById('servicesLabContainer');
    if (!customContainer) return;

    const services = window.allServicesData || window.servicesData || [];
    const currentCat = window.selectedLabCategory || 'เลือดวิทยา (HEMATOLOGY)';

    const filteredServices = (currentCat === 'ALL' || currentCat === 'ทั้งหมด (All)')
        ? services
        : services.filter(s => {
            const itemCat = s.category || getServiceCategory(s);
            return isCategoryMatch(itemCat, currentCat);
        });

    if (filteredServices.length === 0) {
        customContainer.innerHTML = `
            <div class="col-12">
                <div class="text-center text-muted py-4">
                    <i class="bi bi-folder-x fs-3 d-block mb-2 text-secondary opacity-50"></i>
                    ยังไม่มีรายการในหมวดหมู่ "${currentCat}"<br>
                    <small class="text-muted">สามารถตั้งค่าเพิ่มรายการได้ที่เมนู "จัดการรายการตรวจ"</small>
                </div>
            </div>`;
    } else {
        customContainer.innerHTML = filteredServices.map(s => {
            const cur = s.currency === 'THB' ? 'บาท' : (s.currency || 'LAK');
            const isPackage = s.sub_items && Array.isArray(s.sub_items) && s.sub_items.length > 0;
            const isChecked = (window.checkedLabState && window.checkedLabState[s.name]) ? 'checked' : '';

            const badgeTypeHtml = isPackage
                ? `<span class="badge bg-primary-subtle text-primary border border-primary-subtle px-1.5 py-0.5 rounded-pill me-1" style="font-size: 0.68rem;"><i class="bi bi-box-seam me-1"></i>แพ็กเกจ</span>`
                : `<span class="badge bg-secondary-subtle text-secondary border px-1.5 py-0.5 rounded-pill me-1" style="font-size: 0.68rem;"><i class="bi bi-card-checklist me-1"></i>รายการเดี่ยว</span>`;

            const escapedName = (s.name || '').replace(/'/g, "\\'");

            if (!isPackage) {
                return `
                    <div class="col-md-3 col-sm-6 mb-2">
                        <label class="d-flex align-items-center cursor-pointer w-100 p-1.5 rounded-2 hover-bg-light" style="cursor: pointer;">
                            <div class="form-check me-2 mb-0">
                                <input type="checkbox" class="form-check-input lab-item-checkbox shadow-none" name="lab" value="${s.name}" data-price="${s.price || 0}" ${isChecked} onchange="handleLabCheckboxChange(this, '${escapedName}', ${s.price || 0})" style="transform: scale(1.15); cursor: pointer;">
                            </div>
                            <div class="text-truncate" style="font-size: 0.85rem;">
                                ${badgeTypeHtml}
                                <span class="fw-semibold text-dark me-1">${s.name}</span>
                                <span class="fw-bold" style="color: #0284c7;">${Number(s.price).toLocaleString()} ${cur}</span>
                            </div>
                        </label>
                    </div>
                `;
            }

            let subItemsHtml = '';
            if (s.sub_items && s.sub_items.length > 0) {
                subItemsHtml = `
                    <div class="mt-1 ps-4">
                        <div class="text-muted extra-small mb-1 opacity-75" style="font-size: 0.72rem;">
                            รายการย่อย (${s.sub_items.length} รายการ):
                        </div>
                        <div class="d-flex flex-wrap gap-1">
                            ${s.sub_items.map(item => `<span class="badge bg-light text-secondary border-0 px-1.5 py-0.5 fw-normal" style="font-size: 0.72rem; color: #475569;"><i class="bi bi-check2 text-success me-1"></i>${item.name}</span>`).join('')}
                        </div>
                    </div>
                `;
            }

            return `
                <div class="col-md-4 col-sm-6 mb-3">
                    <div class="card h-100 border-0 p-2.5 shadow-sm" style="background: #f8fafc; border-radius: 12px; border: 1px solid #e2e8f0 !important;">
                        <label class="d-flex align-items-start cursor-pointer mb-0 w-100" style="cursor: pointer;">
                            <div class="form-check me-2 mt-1 mb-0">
                                <input type="checkbox" class="form-check-input lab-item-checkbox shadow-none" name="lab" value="${s.name}" data-price="${s.price || 0}" ${isChecked} onchange="handleLabCheckboxChange(this, '${escapedName}', ${s.price || 0})" style="transform: scale(1.15); cursor: pointer;">
                            </div>
                            <div class="w-100">
                                <div class="d-flex align-items-center mb-1 flex-wrap">
                                    ${badgeTypeHtml}
                                    <span class="fw-bold text-dark" style="font-size: 0.9rem;">${s.name}</span>
                                </div>
                                ${subItemsHtml}
                                <div class="mt-2 ps-4 fw-bold" style="color: #0284c7; font-size: 0.9rem;">
                                    ${Number(s.price).toLocaleString()} ${cur}
                                </div>
                            </div>
                        </label>
                    </div>
                </div>
            `;
        }).join('');
    }
    updateLabTotals();
}

async function openLabOrder(visitId, patientName, hn) {
    const form = document.getElementById('labOrderForm');
    if (form) form.reset();
    const labNoteInput = document.getElementById('labOrderNoteInput');
    if (labNoteInput) labNoteInput.value = '';

    const vId = document.getElementById('labVisitId');
    if (vId) vId.value = visitId;
    const hInput = document.getElementById('labHN');
    if (hInput) hInput.value = hn;
    const vDisp = document.getElementById('labVisitIdDisplay');
    if (vDisp) vDisp.innerText = visitId;
    const pDisp = document.getElementById('labPatientName');
    if (pDisp) pDisp.innerText = patientName;
    const hDisp = document.getElementById('labHNDisplay');
    if (hDisp) hDisp.innerText = hn;

    // --- ส่วนที่เพิ่มใหม่: ดึงข้อมูล อายุ, ที่อยู่ และ สัญญาณชีพ ---
    let age = '-';
    let address = '-';
    let vitals = 'ความดัน: -, นน.: - กก., อุณหภูมิ: -°C';

    // 1. ค้นหาข้อมูลผู้ป่วยเพื่อดึง อายุ และ ที่อยู่ (บ้าน, เมือง, แขวง)
    if (window.allPatients) {
        const pat = window.allPatients.find(p => p.hn === hn);
        if (pat) {
            age = pat.age ? pat.age + ' ປີ' : '-';
            let addrParts = [];
            if (pat.village && pat.village !== '-') addrParts.push('ບ.' + pat.village);
            if (pat.district && pat.district !== '-') addrParts.push('ມ.' + pat.district);
            if (pat.province && pat.province !== '-') addrParts.push('ຂ.' + pat.province);
            if (addrParts.length > 0) address = addrParts.join(', ');
        }
    }

    // 2. ค้นหาข้อมูล Visit ปัจจุบันเพื่อดึง สัญญาณชีพ
    let visitInfo = null;
    if (window.doctorQueueData) {
        visitInfo = window.doctorQueueData.find(v => v.visit_id === visitId);
    }
    // ดึงข้อมูลสำรองจากฐานข้อมูลหากไม่เจอในคิว
    if (!visitInfo && typeof _supabase !== 'undefined') {
        try {
            const { data } = await _supabase.from('visits').select('*').eq('visit_id', visitId).maybeSingle();
            visitInfo = data;
        } catch (e) { console.warn("Fetch visit info error:", e); }
    }

    // จัดรูปแบบข้อมูลสัญญาณชีพ
    if (visitInfo) {
        const bp = visitInfo.bp || '-';
        const weight = visitInfo.weight || '-';
        const temp = visitInfo.temp || '-';
        vitals = `ความดัน: ${bp}, นน.: ${weight} กก., อุณหภูมิ: ${temp}°C`;
    }

    // แสดงผลข้อมูลลงใน HTML
    const ageDisp = document.getElementById('labPatientAge');
    if (ageDisp) ageDisp.innerText = age;
    const addrDisp = document.getElementById('labPatientAddress');
    if (addrDisp) addrDisp.innerText = address;
    const vitalsDisp = document.getElementById('labPatientVitals');
    if (vitalsDisp) vitalsDisp.innerText = vitals;
    // --------------------------------------------------------

    const customContainer = document.getElementById('customLabContainer');
    if (customContainer) customContainer.innerHTML = '';

    window.checkedLabState = {};

    // 🌟 ดึงรายการตรวจเดิมของ Visit นี้ (เฉพาะกรณีที่เป็นของวันนี้เท่านั้น เพื่อไม่ให้บล็อกรายการของวันก่อนหน้า)
    let existingLabs = [];
    if (visitInfo && visitInfo.lab_tests) {
        const todayStr = new Date().toISOString().split('T')[0];
        let visitDateStr = '';
        if (visitInfo.created_at) {
            visitDateStr = new Date(visitInfo.created_at).toISOString().split('T')[0];
        }
        if (!visitDateStr || visitDateStr === todayStr) {
            existingLabs = visitInfo.lab_tests.split(',').map(s => s.trim()).filter(Boolean);
        }
    }
    window.currentVisitExistingLabs = existingLabs;

    // แสดงแถบรายการตรวจเดิมที่เคยสั่งไปแล้ว
    const existingLabsBanner = document.getElementById('existingLabsBanner');
    if (existingLabsBanner) {
        if (existingLabs.length > 0) {
            existingLabsBanner.innerHTML = `
                <div class="alert alert-info py-2 px-3 mb-3 d-flex align-items-center gap-2" style="font-size: 0.85rem; border-radius: 10px; border-left: 4px solid #0284c7;">
                    <i class="bi bi-info-circle-fill text-primary fs-5"></i>
                    <div>
                        <strong class="text-dark">ລາຍການທີ່ເຄີຍສັ່ງກ່ອນໜ້າ (${existingLabs.length} ລາຍການ):</strong>
                        <div class="text-primary fw-semibold mt-0.5">${existingLabs.join(', ')}</div>
                        <small class="text-muted">ກະລຸນາເລືອກສະເພາະລາຍການທີ່ຕ້ອງການ <strong>"ສັ່ງເພີ່ມ"</strong> (ລະບົບຈະຮວມລາຍການໃຫ້ອັດຕະໂນມັດ ໂດຍບໍ່ລຶບລາຍການເກົ່າ ແລະ ແຍກບິນໃຫ້ຢ່າງຖືກຕ້ອງ)</small>
                    </div>
                </div>
            `;
            existingLabsBanner.style.display = 'block';
        } else {
            existingLabsBanner.innerHTML = '';
            existingLabsBanner.style.display = 'none';
        }
    }

    // ดึงข้อมูลบริการ/แล็บ 38 รายการจาก Supabase DB เพื่อให้ข้อมูลครบถ้วนเสมอ
    if (typeof loadServicesData === 'function') {
        await loadServicesData();
    }

    const firstTab = document.querySelector('#labCategoryTabs .lab-cat-tab');
    if (firstTab) {
        switchLabCategory('เลือดวิทยา (HEMATOLOGY)', firstTab);
    } else {
        renderServicesLabContainer();
    }

    const modalEl = document.getElementById('labOrderModal');
    if (modalEl) {
        bootstrap.Modal.getOrCreateInstance(modalEl).show();
    }
}

function openDoctorLabModal(visitId, hn, patientName) {
    openLabOrder(visitId, patientName, hn);
}

// 🌟 ฟังก์ชันเปิดหน้าต่างเลือกคนไข้ที่รอผลแล็บวันนี้ เพื่อสั่งตรวจเพิ่ม
window.openDoctorAddLabModal = async function () {
    Swal.fire({
        title: 'ກຳລັງໂຫລດຂໍ້ມູນຄົນໄຂ້...',
        allowOutsideClick: false,
        didOpen: () => Swal.showLoading()
    });

    try {
        const todayStr = (typeof getVientianeDateRange === 'function')
            ? getVientianeDateRange('today').startStr
            : new Date().toISOString().split('T')[0];

        const { data, error } = await _supabase
            .from('visits')
            .select('visit_id, hn, patient_name, doctor_name, symptom, status, lab_tests, lab_note, created_at')
            .in('status', ['รอผลแล็บ', 'รอผลตรวจ Lab', 'รอผลแล็บเพิ่มเติม'])
            .gte('created_at', todayStr + 'T00:00:00')
            .order('created_at', { ascending: false });

        if (error) throw error;

        const labPatients = data || [];
        if (labPatients.length === 0) {
            Swal.fire({
                icon: 'info',
                title: 'ບໍ່ພົບຄົນໄຂ້',
                text: 'ບໍ່ມີຄົນໄຂ້ທີ່ກຳລັງລໍຖ້າຜົນແລັບໃນມື້ນີ້',
                confirmButtonText: 'ຕົກລົງ'
            });
            return;
        }

        let rowsHtml = labPatients.map((p, idx) => {
            const testList = (p.lab_tests || '').split(',').map(s => s.trim()).filter(Boolean);
            const safeName = (p.patient_name || '').replace(/'/g, "\\'");
            return `
                <tr class="border-bottom">
                    <td class="text-center py-2.5 text-muted fw-bold">${idx + 1}</td>
                    <td class="py-2.5">
                        <strong class="text-primary">${p.visit_id}</strong>
                        <span class="badge bg-light text-secondary border ms-1">HN: ${p.hn || '-'}</span>
                    </td>
                    <td class="py-2.5">
                        <div class="fw-bold text-dark">${p.patient_name}</div>
                        <small class="text-muted">ລາຍການກວດເດີມ: <span class="text-info fw-semibold">${testList.join(', ') || '-'}</span></small>
                    </td>
                    <td class="text-end pe-3 py-2.5">
                        <button class="btn btn-sm btn-warning text-dark fw-bold rounded-pill shadow-sm px-3"
                            onclick="Swal.close(); openLabOrder('${p.visit_id}', '${safeName}', '${p.hn || ''}')">
                            <i class="bi bi-plus-circle-fill me-1"></i>ເລືອກສັ່ງກວດເພີ່ມ
                        </button>
                    </td>
                </tr>
            `;
        }).join('');

        const modalHtml = `
            <div class="text-start">
                <div class="mb-3">
                    <input type="text" id="swalSearchLabPatient" class="form-control"
                        placeholder="🔍 ຄົ້ນຫາ ຊື່, HN, Visit ID..." 
                        onkeyup="const val = this.value.toLowerCase(); document.querySelectorAll('#swalLabPatientsTable tbody tr').forEach(tr => tr.style.display = tr.innerText.toLowerCase().includes(val) ? '' : 'none')">
                </div>
                <div class="table-responsive border rounded-3" style="max-height: 380px; overflow-y: auto;">
                    <table class="table table-hover align-middle mb-0" id="swalLabPatientsTable">
                        <thead class="bg-light sticky-top">
                            <tr class="text-secondary small fw-bold">
                                <th class="text-center" width="50">#</th>
                                <th width="160">Visit / HN</th>
                                <th>ຊື່-ນາມສະກຸນ / ລາຍການກວດເດີມ</th>
                                <th class="text-end pe-3" width="160">ຈັດການ</th>
                            </tr>
                        </thead>
                        <tbody>
                            ${rowsHtml}
                        </tbody>
                    </table>
                </div>
            </div>
        `;

        Swal.fire({
            title: '<h5 class="fw-bold text-dark mb-0"><i class="bi bi-flask text-warning me-2"></i>ເລືອກຄົນໄຂ້ທີ່ລໍຖ້າຜົນແລັບ (ສັ່ງກວດເພີ່ມ)</h5>',
            html: modalHtml,
            width: '720px',
            showConfirmButton: false,
            showCloseButton: true
        });

    } catch (err) {
        Swal.fire('Error', err.message || 'ບໍ່ສາມາດໂຫລດຂໍ້ມູນໄດ້', 'error');
    }
};

async function submitLabOrder() {
    const form = document.getElementById('labOrderForm');
    const visitId = form.visitId.value;

    window.checkedLabState = window.checkedLabState || {};
    const selectedLabs = Object.keys(window.checkedLabState);

    // ดึงรายการแล็บเพิ่มเติมจากช่อง Custom หากมี
    form.querySelectorAll('#customLabContainer input[name="lab"]:checked').forEach((cb) => {
        if (!selectedLabs.includes(cb.value)) {
            selectedLabs.push(cb.value);
        }
    });

    if (selectedLabs.length === 0) {
        Swal.fire('แจ้งเตือน', 'กรุณาเลือกรายการ Lab อย่างน้อย 1 รายการ', 'warning');
        return;
    }

    // 🌟 ดึงข้อความจากช่องหมายเหตุที่เราเพิ่งเพิ่มเข้ามา
    const labNoteInput = document.getElementById('labOrderNoteInput');
    const labNoteVal = labNoteInput ? labNoteInput.value.trim() : '';

    Swal.fire({ title: 'กำลังบันทึกส่งแล็บ...', allowOutsideClick: false, didOpen: () => Swal.showLoading() });

    // 🌟 ຮວມລາຍການກວດເກົ່າ + ລາຍການກວດໃໝ່ ບໍ່ໃຫ້ລາຍການເກົ່າຖືກຂຽນທັບ
    const existingLabs = window.currentVisitExistingLabs || [];
    const mergedLabs = [...new Set([...existingLabs, ...selectedLabs])];
    const newlyAddedLabs = selectedLabs.filter(x => !existingLabs.includes(x));

    let finalLabNote = labNoteVal;
    if (existingLabs.length > 0 && newlyAddedLabs.length > 0) {
        finalLabNote = (finalLabNote || '').replace(/\[(?:ສັ່ງກວດເພີ່ມ|ตรวจเพิ่ม)(?::\s*[^\]]*)?\]/g, '').trim();
        finalLabNote = `[ສັ່ງກວດເພີ່ມ: ${newlyAddedLabs.join(', ')}] ${finalLabNote}`.trim();
    }

    // ข้อมูลที่จะอัปเดตลงฐานข้อมูล Supabase
    const updateData = {
        lab_tests: mergedLabs.join(', '),
        lab_note: finalLabNote, // บันทึกข้อความหมายเหตุและแท็กสั่งตรวจเพิ่มลงฐานข้อมูล
        status: 'รอชำระเงิน'
    };

    const { error } = await _supabase
        .from('visits')
        .update(updateData)
        .eq('visit_id', visitId);

    if (error) {
        Swal.fire('ข้อผิดพลาด', error.message, 'error');
    } else {
        bootstrap.Modal.getOrCreateInstance(document.getElementById('labOrderModal')).hide();
        loadDoctorQueue();
        loadPaymentQueue();
        Swal.fire('สำเร็จ', 'ส่งเข้าห้องการเงินสำเร็จ', 'success');
    }
}

function addCustomLabCheckbox() {
    const input = document.getElementById('customLabInput');
    const container = document.getElementById('customLabContainer');
    if (!input || !container) return;

    const val = input.value.trim();
    if (!val) return;

    const col = document.createElement('div');
    col.className = 'col-md-6 mb-2';
    col.innerHTML = `
        <label class="w-100 h-100 cursor-pointer" style="cursor: pointer;">
            <div class="card h-100 border-0 shadow-sm transition-all custom-lab-card" style="border-radius: 12px; background: #fff8f1; border: 1px dashed #fdba74 !important;">
                <div class="card-body p-3 d-flex align-items-center">
                    <div class="form-check me-3 mb-0">
                        <input type="checkbox" class="form-check-input shadow-none" name="lab" value="${val}" checked onchange="updateLabTotals()" style="transform: scale(1.3); cursor: pointer;">
                    </div>
                    <div class="w-100">
                        <span class="fw-bold text-dark d-block" style="font-size: 1rem;">${val}</span>
                        <small class="text-warning-emphasis">รายการเพิ่มพิเศษ</small>
                    </div>
                </div>
            </div>
        </label>
    `;

    container.appendChild(col);
    input.value = '';
    updateLabTotals();
}

async function confirmPayment(visitId) {
    try {
        const { data: vData } = await _supabase.from('visits').select('*').eq('visit_id', visitId).maybeSingle();
        if (vData) {
            showPaymentDetails(vData.visit_id, vData.hn, vData.patient_name, vData.lab_tests, vData.discount || vData.lab_discount || 0);
            return;
        }
    } catch (e) {
        console.warn('confirmPayment fetch visit error:', e);
    }
    showPaymentDetails(visitId);
}

window.paymentQueueData = [];
window.paymentFilteredData = [];

// ฟังก์ชันปรับแต่งชื่อผู้ป่วยเพื่อใช้เทียบเคียง (Normalizer สำหรับภาษาลาว/ไทย)
function normalizeClinicPatientName(name) {
    if (!name || typeof name !== 'string') return '';
    return name
        .trim()
        .toLowerCase()
        .replace(/^(ນາງ|ນ\.|ນ|ທ້າວ|ທ\.|ທ|นาย|นาง|นางสาว|น\.ส\.|ด\.ช\.|ด\.ญ\.|คุณ|ท่าน)\s*/i, '')
        .replace(/[\s\-_.\u00a0]+/g, '')
        .replace(/ໍ้า/g, '້ຳ')
        .replace(/ຳ/g, 'ำ');
}
window.normalizeClinicPatientName = normalizeClinicPatientName;

async function resolvePatientHn(patientName, visitId, phone, autoGenerateIfNotFound = true) {
    if (!patientName || patientName === '-' || patientName === 'ผู้ป่วย') return '';

    const rawName = (patientName || '').trim();
    const lowerName = rawName.toLowerCase();
    const normName = normalizeClinicPatientName(rawName);

    // 1. ตรวจสอบใน window.allPatients ก่อน
    let allPatientsList = window.allPatients || [];
    if (allPatientsList.length === 0) {
        try {
            // อัปเดตให้ดึงข้อมูลทั้งหมด (*) ป้องกันการเซฟทับข้อมูลแบบไม่ครบ
            const { data: pList } = await _supabase.from('patients').select('*');
            if (pList && pList.length > 0) {
                allPatientsList = pList;
                window.allPatients = pList;
            }
        } catch (e) { }
    }

    // Direct Exact
    for (const p of allPatientsList) {
        const pName = (p.patient_name || p.name || '').trim();
        const pHn = (p.hn && p.hn !== 'null' && p.hn !== 'undefined' && p.hn !== '-') ? p.hn.trim() : '';
        if (pHn && pName.toLowerCase() === lowerName) {
            return pHn;
        }
    }

    // Normalized
    for (const p of allPatientsList) {
        const pName = (p.patient_name || p.name || '').trim();
        const pHn = (p.hn && p.hn !== 'null' && p.hn !== 'undefined' && p.hn !== '-') ? p.hn.trim() : '';
        if (pHn && normalizeClinicPatientName(pName) === normName) {
            return pHn;
        }
    }

    // Substring
    if (normName.length >= 2) {
        for (const p of allPatientsList) {
            const pName = (p.patient_name || p.name || '').trim();
            const pHn = (p.hn && p.hn !== 'null' && p.hn !== 'undefined' && p.hn !== '-') ? p.hn.trim() : '';
            const pNorm = normalizeClinicPatientName(pName);
            if (pHn && pNorm && (pNorm.includes(normName) || normName.includes(pNorm))) {
                return pHn;
            }
        }
    }

    // Phone match
    if (phone) {
        const cleanPhone = String(phone).replace(/\D/g, '');
        if (cleanPhone.length >= 6) {
            for (const p of allPatientsList) {
                const pPhone = String(p.phone || p.emergency_tel || '').replace(/\D/g, '');
                const pHn = (p.hn && p.hn !== 'null' && p.hn !== 'undefined' && p.hn !== '-') ? p.hn.trim() : '';
                if (pHn && pPhone && (pPhone === cleanPhone || pPhone.includes(cleanPhone) || cleanPhone.includes(pPhone))) {
                    return pHn;
                }
            }
        }
    }

    // 2. ตรวจสอบจากตาราง visits และ bills ที่มี HN อยู่แล้ว
    try {
        const { data: vData } = await _supabase.from('visits').select('hn').eq('patient_name', rawName).not('hn', 'is', null).limit(1).maybeSingle();
        if (vData && vData.hn && vData.hn !== '-' && vData.hn !== 'null') return vData.hn.trim();
    } catch (e) { }

    try {
        const { data: bData } = await _supabase.from('bills').select('hn').eq('patient_name', rawName).not('hn', 'is', null).limit(1).maybeSingle();
        if (bData && bData.hn && bData.hn !== '-' && bData.hn !== 'null') return bData.hn.trim();
    } catch (e) { }

    // 3. หากยังไม่พบ HN (เคสตรวจที่ไม่ได้ลงทะเบียนล่วงหน้า) ให้สร้างรหัสแสดงผลจำลอง
    if (autoGenerateIfNotFound && rawName && rawName !== '-' && rawName !== 'ผู้ป่วย') {
        const autoHn = 'HN-' + Math.floor(100000 + Math.random() * 900000);
        return autoHn;
    }

    return '';
}
window.resolvePatientHn = resolvePatientHn;

// 1. โหลดข้อมูลก้อนหลักจากฐานข้อมูลห้องการเงิน / จ่ายค่ารักษา
async function loadPaymentQueue() {
    const tbody = document.querySelector('#paymentTable tbody');
    if (!tbody) return;

    // 🌟 ตั้งค่าเริ่มต้นช่วงวันที่ในหน้าจ่ายค่ารักษาให้เป็นวันปัจจุบันก่อน (Default to Today)
    const startInput = document.getElementById('paymentStartDate');
    const endInput = document.getElementById('paymentEndDate');
    if (startInput && endInput && !startInput.value && !endInput.value && !window._paymentDateInitialized) {
        const todayStr = new Date().toISOString().split('T')[0];
        startInput.value = todayStr;
        endInput.value = todayStr;
        window._paymentDateInitialized = true;
    }

    tbody.innerHTML = '<tr><td colspan="6" class="text-center text-muted py-5"><div class="spinner-border spinner-border-sm text-primary me-2"></div>กำลังโหลดข้อมูล...</td></tr>';

    // ดึงคนที่มาก่อน (คิวเก่า) ขึ้นก่อน
    const { data, error } = await _supabase
        .from('visits')
        .select('*')
        .eq('status', 'รอชำระเงิน')
        .order('created_at', { ascending: true });

    if (error) {
        tbody.innerHTML = `<tr><td colspan="6" class="text-center text-danger py-3">เกิดข้อผิดพลาด: ${error.message}</td></tr>`;
        return;
    }

    let processedData = data || [];

    // ดึงข้อมูลทะเบียนผู้ป่วยทั้งหมดมาเตรียมไว้สำหรับการจับคู่ HN
    let allPatientsList = window.allPatients || [];
    try {
        // อัปเดตให้ดึงข้อมูลทั้งหมด (*) ป้องกันการเซฟทับข้อมูลแบบไม่ครบ
        const { data: pList } = await _supabase.from('patients').select('*');
        if (pList && pList.length > 0) {
            allPatientsList = pList;
            window.allPatients = pList;
        }
    } catch (e) {
        console.warn('loadPaymentQueue fetch patients notice:', e);
    }

    // ดึงประวัติ visits อื่นๆ ที่มี HN อยู่แล้ว
    let visitHnMap = {};
    let visitNameHnMap = {};
    try {
        const { data: vList } = await _supabase.from('visits').select('visit_id, hn, patient_name').not('hn', 'is', null);
        if (vList) {
            vList.forEach(v => {
                const cleanHn = (v.hn && v.hn !== 'null' && v.hn !== 'undefined' && v.hn !== '-') ? v.hn.trim() : '';
                if (cleanHn) {
                    if (v.visit_id) visitHnMap[v.visit_id] = cleanHn;
                    if (v.patient_name) {
                        visitNameHnMap[v.patient_name.trim().toLowerCase()] = cleanHn;
                        const pNorm = normalizeClinicPatientName(v.patient_name);
                        if (pNorm) visitNameHnMap[pNorm] = cleanHn;
                    }
                }
            });
        }
    } catch (e) { }

    // สร้าง Map จากรายชื่อผู้ป่วย
    const exactNameMap = {};
    const normNameMap = {};
    const phoneMap = {};

    allPatientsList.forEach(p => {
        const pName = (p.patient_name || p.name || '').trim();
        const pHn = (p.hn && p.hn !== 'null' && p.hn !== 'undefined' && p.hn !== '-') ? p.hn.trim() : '';
        if (pHn) {
            if (pName) {
                exactNameMap[pName.toLowerCase()] = pHn;
                const normP = normalizeClinicPatientName(pName);
                if (normP) normNameMap[normP] = pHn;
            }
            if (p.phone) phoneMap[String(p.phone).replace(/\D/g, '')] = pHn;
            if (p.emergency_tel) phoneMap[String(p.emergency_tel).replace(/\D/g, '')] = pHn;
        }
    });

    processedData.forEach(row => {
        let rowHn = (row.hn && row.hn !== 'null' && row.hn !== 'undefined' && row.hn !== '-') ? row.hn.trim() : '';

        if (!rowHn) {
            const rawName = (row.patient_name || '').trim();
            const lowerName = rawName.toLowerCase();
            const normName = normalizeClinicPatientName(rawName);

            let matchedHn = visitHnMap[row.visit_id] ||
                exactNameMap[lowerName] ||
                normNameMap[normName] ||
                visitNameHnMap[lowerName] ||
                visitNameHnMap[normName];

            // ลอง Partial/Substring search ถ้ายังไม่เจอ
            if (!matchedHn && normName && normName.length >= 2) {
                for (const p of allPatientsList) {
                    const pName = (p.patient_name || p.name || '').trim();
                    const pHn = (p.hn && p.hn !== 'null' && p.hn !== 'undefined' && p.hn !== '-') ? p.hn.trim() : '';
                    const pNorm = normalizeClinicPatientName(pName);
                    if (pHn && pNorm && (pNorm.includes(normName) || normName.includes(pNorm))) {
                        matchedHn = pHn;
                        break;
                    }
                }
            }

            if (matchedHn) {
                row.hn = matchedHn;
            }
        }
    });

    window.paymentQueueData = processedData;
    filterPaymentTable(); // เรียกใช้ตัวกรองเพื่อวาดตาราง
}

// 2. ฟังก์ชันจัดวันที่ให้ปุ่มกด วันนี้, เดือนนี้, ปีนี้
window.setPaymentDateFilter = function (mode) {
    const startInput = document.getElementById('paymentStartDate');
    const endInput = document.getElementById('paymentEndDate');
    const now = new Date();

    if (mode === 'today') {
        const todayStr = now.toISOString().split('T')[0];
        if (startInput) startInput.value = todayStr;
        if (endInput) endInput.value = todayStr;
    } else if (mode === 'month') {
        const firstDay = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0];
        const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().split('T')[0];
        if (startInput) startInput.value = firstDay;
        if (endInput) endInput.value = lastDay;
    } else if (mode === 'year') {
        const firstDay = new Date(now.getFullYear(), 0, 1).toISOString().split('T')[0];
        const lastDay = new Date(now.getFullYear(), 11, 31).toISOString().split('T')[0];
        if (startInput) startInput.value = firstDay;
        if (endInput) endInput.value = lastDay;
    } else if (mode === 'all') {
        if (startInput) startInput.value = '';
        if (endInput) endInput.value = '';
    }
    filterPaymentTable();
};

// 3. ฟังก์ชันกรองข้อมูลตามวันที่และข้อความที่ค้นหา
window.filterPaymentTable = function () {
    if (!window.paymentQueueData) return;

    let filtered = window.paymentQueueData;

    const startDateStr = document.getElementById('paymentStartDate')?.value;
    const endDateStr = document.getElementById('paymentEndDate')?.value;

    if (startDateStr || endDateStr) {
        filtered = filtered.filter(row => {
            if (!row.created_at) return true;
            const rowDate = new Date(row.created_at).toISOString().split('T')[0];
            let pass = true;
            if (startDateStr && rowDate < startDateStr) pass = false;
            if (endDateStr && rowDate > endDateStr) pass = false;
            return pass;
        });
    }

    const q = (document.getElementById('searchPaymentInput')?.value || '').toLowerCase().trim();
    if (q) {
        filtered = filtered.filter(row =>
            (row.visit_id && row.visit_id.toLowerCase().includes(q)) ||
            (row.hn && row.hn.toLowerCase().includes(q)) ||
            (row.patient_name && row.patient_name.toLowerCase().includes(q))
        );
    }

    window.paymentFilteredData = filtered;
    renderPaymentTable();
};

// 4. ฟังก์ชันวาดตารางแสดงผล
window.renderPaymentTable = function () {
    const tbody = document.querySelector('#paymentTable tbody');
    if (!tbody) return;

    tbody.innerHTML = '';

    if (!window.paymentFilteredData || window.paymentFilteredData.length === 0) {
        const emptyText = typeof t === 'function' ? t('payment_empty', 'ไม่มีรายการรอชำระเงิน') : 'ไม่มีรายการรอชำระเงิน';
        tbody.innerHTML = `<tr><td colspan="6" class="text-center text-muted py-5">${emptyText}</td></tr>`;
        return;
    }

    const detailsLabel = typeof t === 'function' ? t('payment_btn_details', 'ดูรายละเอียด') : 'ดูรายละเอียด';
    const pendingLabel = typeof t === 'function' ? t('payment_status_pending', 'รอชำระเงิน') : 'รอชำระเงิน';

    window.paymentFilteredData.forEach((row, idx) => {
        const hnDisplay = row.hn || '-';
        const testCount = row.lab_tests ? row.lab_tests.split(',').filter(Boolean).length : 0;
        const safeTests = (row.lab_tests || '').replace(/'/g, "\\'");
        const safeName = (row.patient_name || '').replace(/'/g, "\\'");

        let labDetailsHtml = `<button class="btn btn-sm btn-outline-primary rounded-pill px-3 py-1 fw-semibold" onclick="showPaymentDetails('${row.visit_id}', '${hnDisplay}', '${safeName}', '${safeTests}', ${row.discount || row.lab_discount || 0})"><i class="bi bi-credit-card me-1"></i> ${detailsLabel} (${testCount} รายการ)</button>`;

        tbody.innerHTML += `<tr>
            <td class="ps-4 text-center fw-semibold text-secondary">${idx + 1}</td>
            <td class="fw-bold text-primary">${row.visit_id}</td>
            <td class="fw-semibold text-secondary">${hnDisplay}</td>
            <td class="fw-bold">${row.patient_name || '-'}</td>
            <td>${labDetailsHtml}</td>
            <td><span class="badge-soft-warning">${pendingLabel}</span></td>
        </tr>`;
    });
};

// ===============================================
// ระบบจัดเก็บไฟล์แล็บด้วย IndexedDB (ป้องกัน QuotaExceededError)
// ===============================================
const LabDB = {
    dbName: 'ClinicLabFilesDB',
    storeName: 'lab_files_store',
    db: null,

    async getDB() {
        if (this.db) return this.db;
        return new Promise((resolve) => {
            try {
                const request = indexedDB.open(this.dbName, 1);
                request.onupgradeneeded = (e) => {
                    const db = e.target.result;
                    if (!db.objectStoreNames.contains(this.storeName)) {
                        db.createObjectStore(this.storeName, { keyPath: 'id' });
                    }
                };
                request.onsuccess = (e) => {
                    this.db = e.target.result;
                    resolve(this.db);
                };
                request.onerror = (e) => {
                    console.warn('IndexedDB open error:', e.target.error);
                    resolve(null);
                };
            } catch (err) {
                console.warn('IndexedDB exception:', err);
                resolve(null);
            }
        });
    },

    async saveFile(fileItem) {
        try {
            const db = await this.getDB();
            if (!db) return false;
            return new Promise((resolve) => {
                const tx = db.transaction(this.storeName, 'readwrite');
                const store = tx.objectStore(this.storeName);
                store.put(fileItem);
                tx.oncomplete = () => resolve(true);
                tx.onerror = () => resolve(false);
            });
        } catch (e) {
            console.warn('LabDB saveFile error:', e);
            return false;
        }
    },

    async getFile(id) {
        try {
            const db = await this.getDB();
            if (!db) return null;
            return new Promise((resolve) => {
                const tx = db.transaction(this.storeName, 'readonly');
                const store = tx.objectStore(this.storeName);
                const req = store.get(id);
                req.onsuccess = () => resolve(req.result || null);
                req.onerror = () => resolve(null);
            });
        } catch (e) {
            return null;
        }
    },

    async getFilesByVisit(visitId) {
        try {
            const db = await this.getDB();
            if (!db) return [];
            return new Promise((resolve) => {
                const tx = db.transaction(this.storeName, 'readonly');
                const store = tx.objectStore(this.storeName);
                const req = store.getAll();
                req.onsuccess = () => {
                    const all = req.result || [];
                    const matched = all.filter(f => f && String(f.visitId) === String(visitId));
                    resolve(matched);
                };
                req.onerror = () => resolve([]);
            });
        } catch (e) {
            return [];
        }
    }
};

// Helper สำหรับดึงไฟล์แล็บทั้งหมดของ Visit (สะสมหลายไฟล์ได้ และไม่เกิน Quota)
function isValidLabFileUrl(u) {
    if (!u || typeof u !== 'string') return false;
    const s = u.trim();
    if (s === '' || s === '#' || s === 'undefined' || s === 'null' || s.includes('sample.pdf')) return false;
    return s.startsWith('http://') || s.startsWith('https://') || s.startsWith('data:') || s.startsWith('blob:');
}

function getLabFilesForVisit(visitId, rowPdfUrl) {
    let files = [];

    // 1. ดึงจาก DB pdf_url โดยตรง (ถ้าเป็น JSON Array)
    if (rowPdfUrl && typeof rowPdfUrl === 'string' && rowPdfUrl.trim() !== '') {
        const raw = rowPdfUrl.trim();
        if (raw.startsWith('[')) {
            try {
                const parsed = JSON.parse(raw);
                if (Array.isArray(parsed)) {
                    parsed.forEach(p => {
                        if (p && (p.id || isValidLabFileUrl(p.url || p.publicUrl))) {
                            const u = p.url || p.publicUrl || '';
                            const cat = p.category || 'ผลแล็บ';
                            if (!files.some(f => (p.id && f.id === p.id) || (f.fileName === p.fileName && f.category === cat) || (u && (f.url === u || f.publicUrl === u)))) {
                                files.push({
                                    id: p.id || 'FILE-DB-' + Date.now(),
                                    url: u,
                                    publicUrl: u,
                                    fileName: p.fileName || 'ไฟล์ผลแล็บ',
                                    fileType: p.fileType || 'application/pdf',
                                    category: cat,
                                    updatedAt: p.updatedAt || new Date().toISOString()
                                });
                            }
                        }
                    });
                }
            } catch (e) {
                console.warn('JSON parse rowPdfUrl error:', e);
            }
        } else if (isValidLabFileUrl(raw)) {
            files.push({
                id: 'FILE-DB-' + Date.now(),
                url: raw,
                publicUrl: raw,
                fileName: 'ไฟล์ผลแล็บ',
                category: 'ผลแล็บ',
                updatedAt: new Date().toISOString()
            });
        }
    }

    // 2. ดึงจาก Metadata ใน LocalStorage
    try {
        const metaMap = JSON.parse(localStorage.getItem('clinic_lab_files_meta') || '{}');
        const metaList = metaMap[visitId];
        if (Array.isArray(metaList)) {
            metaList.forEach(m => {
                if (m && (m.id || isValidLabFileUrl(m.url || m.publicUrl))) {
                    const cat = m.category || 'ผลแล็บ';
                    if (!files.some(f => (m.id && f.id === m.id) || (f.fileName === m.fileName && f.category === cat))) {
                        files.push(m);
                    }
                }
            });
        }
    } catch (e) { }

    // 3. ดึงจาก Legacy Storage ใน LocalStorage (เผื่อไฟล์เก่าที่เคยเซฟไว้)
    try {
        const cachedMap = JSON.parse(localStorage.getItem('clinic_real_lab_files') || '{}');
        const raw = cachedMap[visitId];
        let legacyList = [];
        if (Array.isArray(raw)) {
            legacyList = raw;
        } else if (raw && typeof raw === 'object' && (raw.id || isValidLabFileUrl(raw.url || raw.publicUrl))) {
            legacyList = [raw];
        }
        legacyList.forEach(legacyItem => {
            if (legacyItem && (legacyItem.id || isValidLabFileUrl(legacyItem.url || legacyItem.publicUrl))) {
                const cat = legacyItem.category || 'ผลแล็บ';
                if (!files.some(f => (legacyItem.id && f.id === legacyItem.id) || (f.fileName === legacyItem.fileName && f.category === cat))) {
                    files.push(legacyItem);
                }
            }
        });
    } catch (e) { }

    return files;
}

async function getLabFilesForVisitAsync(visitId, rowPdfUrl) {
    let files = getLabFilesForVisit(visitId, rowPdfUrl);

    // 1. ดึงจาก IndexedDB (LabDB)
    try {
        const idbFiles = await LabDB.getFilesByVisit(visitId);
        if (Array.isArray(idbFiles)) {
            idbFiles.forEach(idbItem => {
                if (idbItem && (idbItem.id || isValidLabFileUrl(idbItem.url || idbItem.publicUrl))) {
                    const cat = idbItem.category || 'ผลแล็บ';
                    if (!files.some(f => (idbItem.id && f.id === idbItem.id) || (f.fileName === idbItem.fileName && f.category === cat))) {
                        files.push(idbItem);
                    }
                }
            });
        }
    } catch (e) { }

    // 2. ดึงจาก Supabase DB (visits)
    if (visitId && typeof _supabase !== 'undefined') {
        try {
            const { data } = await _supabase
                .from('visits')
                .select('pdf_url')
                .eq('visit_id', visitId)
                .maybeSingle();

            if (data && data.pdf_url) {
                const rawUrl = data.pdf_url;
                if (rawUrl.trim().startsWith('[')) {
                    try {
                        const parsed = JSON.parse(rawUrl);
                        if (Array.isArray(parsed)) {
                            parsed.forEach(p => {
                                if (p && (p.id || isValidLabFileUrl(p.url || p.publicUrl))) {
                                    const u = p.url || p.publicUrl || '';
                                    const cat = p.category || 'ผลแล็บ';
                                    if (!files.some(f => (p.id && f.id === p.id) || (f.fileName === p.fileName && f.category === cat) || (u && (f.url === u || f.publicUrl === u)))) {
                                        files.push({
                                            id: p.id || 'FILE-DB-' + Date.now(),
                                            url: u,
                                            publicUrl: u,
                                            fileName: p.fileName || 'ไฟล์ผลแล็บ',
                                            category: cat,
                                            fileType: p.fileType || 'application/pdf',
                                            updatedAt: p.updatedAt || new Date().toISOString()
                                        });
                                    }
                                }
                            });
                        }
                    } catch (e) { }
                } else if (isValidLabFileUrl(rawUrl)) {
                    if (!files.some(f => f.url === rawUrl || f.publicUrl === rawUrl)) {
                        files.push({
                            id: 'FILE-DB-' + Date.now(),
                            url: rawUrl,
                            publicUrl: rawUrl,
                            fileName: 'ไฟล์ผลแล็บ',
                            category: 'ผลแล็บ',
                            updatedAt: new Date().toISOString()
                        });
                    }
                }
            }
        } catch (e) {
            console.warn('Supabase getLabFilesForVisitAsync warn:', e);
        }
    }

    return files;
}

/**
 * ฟังก์ชันสำหรับเปลี่ยนสถานะและส่งผู้ป่วยไปยังห้องจัดคิวอ่านผล (รองรับทั้งส่งครบถ้วน และ ส่งผลบางส่วน)
 */
async function sendToReportQueue(visitId) {
    if (!visitId) return;

    // ตรวจสอบว่าเคสนี้เป็น Partial Lab อยู่ก่อนหรือไม่
    let isCurrentlyPartial = false;
    let currentPendingNote = '';

    let partialMap = {};
    try { partialMap = JSON.parse(localStorage.getItem('clinic_partial_labs') || '{}'); } catch (e) { }
    if (partialMap[visitId]) {
        isCurrentlyPartial = true;
        currentPendingNote = partialMap[visitId].pendingNote || '';
    }

    // ดึงข้อมูล lab_note และสถานะปัจจุบันจาก Supabase
    let currentLabNote = '';
    try {
        const { data: vData } = await _supabase.from('visits').select('lab_note, status').eq('visit_id', visitId).maybeSingle();
        if (vData) {
            currentLabNote = vData.lab_note || '';
            if (currentLabNote.includes('[รอผลแล็บเพิ่มเติม]')) {
                isCurrentlyPartial = true;
                const match = currentLabNote.match(/\[รอผลแล็บเพิ่มเติม(?::\s*([^\]]*))?\]/);
                if (match && match[1]) currentPendingNote = match[1];
            }
        }
    } catch (e) { }

    const isLao = (window.currentLang || localStorage.getItem('clinic_lang') || 'la') === 'la';

    // แสดงหน้าต่างเลือกรูปแบบการจัดคิว
    const modalTitle = isLao ? 'ເລືອກຮູບແບບການສົ່ງຜົນກວດ' : 'เลือกรูปแบบการส่งผลตรวจ';
    const modalText = isLao
        ? `ລະຫັດ VISIT: <strong>${visitId}</strong>`
        : `รหัส VISIT: <strong>${visitId}</strong>`;

    await Swal.fire({
        title: modalTitle,
        html: `
            <div class="text-start mb-2">
                <p class="text-secondary small mb-3">${modalText}</p>
                <div class="d-grid gap-2">
                    <button type="button" id="swalBtnComplete" class="btn btn-outline-success text-start p-3 rounded-3 border-2 d-flex align-items-center justify-content-between">
                        <div>
                            <div class="fw-bold fs-6 text-success"><i class="bi bi-check-circle-fill me-2"></i>1. ຜົນອອກຄົບໝົດແລ້ວ (ສົ່ງອ່ານຜົນ)</div>
                            <div class="small text-muted mt-1">ສົ່ງຄິວໃຫ້ທ່ານໝໍອ່ານຜົນ ແລະ ປົດເຄສອອກຈາກຫ້ອງ Lab ຢ່າງສົມບູນ</div>
                        </div>
                        <i class="bi bi-arrow-right-circle text-success fs-5"></i>
                    </button>
                    <button type="button" id="swalBtnPartial" class="btn btn-outline-warning text-start p-3 rounded-3 border-2 d-flex align-items-center justify-content-between" style="border-color: #f59e0b;">
                        <div>
                            <div class="fw-bold fs-6" style="color: #d97706 !important;"><i class="bi bi-hourglass-split me-2"></i>2. ຜົນອອກບາງສ່ວນ (ຍັງລໍຖ້າຜົນເພີ່ມເຕີມ)</div>
                            <div class="small text-muted mt-1">ສົ່ງຜົນຕົວທີ່ອອກກ່ອນໃຫ້ທ່ານໝໍ, ແຕ່ເຄສຍັງຄົງຄ້າງຢູ່ໃນຫ້ອງ Lab ເພື່ອລໍຖ້າຜົນຕໍ່ໄປ (ເຊັ່ນ: ລໍຖ້າອີກ 3 ວັນ)</div>
                        </div>
                        <i class="bi bi-arrow-right-circle text-warning fs-5"></i>
                    </button>
                </div>
            </div>
        `,
        showConfirmButton: false,
        showCancelButton: true,
        cancelButtonText: isLao ? 'ຍົກເລີກ' : 'ยกเลิก',
        cancelButtonColor: '#64748b',
        width: '580px',
        didOpen: () => {
            const btnComplete = document.getElementById('swalBtnComplete');
            const btnPartial = document.getElementById('swalBtnPartial');

            if (btnComplete) {
                btnComplete.addEventListener('click', () => {
                    Swal.close();
                    handleCompleteLabSend(visitId, currentLabNote);
                });
            }
            if (btnPartial) {
                btnPartial.addEventListener('click', () => {
                    Swal.close();
                    handlePartialLabSend(visitId, currentLabNote, currentPendingNote);
                });
            }
        }
    });
}

/**
 * จัดการส่งผลแล็บแบบครบถ้วน (ออกจากห้องแล็บ)
 */
async function handleCompleteLabSend(visitId, currentLabNote) {
    Swal.fire({ title: 'ກຳລັງບັນທຶກ...', allowOutsideClick: false, didOpen: () => Swal.showLoading() });

    // 1. ล้างแท็ก [รอผลแล็บเพิ่มเติม] ออกจาก lab_note
    let updatedNote = (currentLabNote || '')
        .replace(/\[รอผลแล็บเพิ่มเติม(?::\s*[^\]]*)?\]/g, '')
        .trim();

    // 2. อัปเดต visits ใน Supabase ให้เป็น "รอจัดคิว"
    const { error } = await _supabase
        .from('visits')
        .update({
            status: 'รอจัดคิว',
            lab_note: updatedNote
        })
        .eq('visit_id', visitId);

    if (error) {
        Swal.fire('ຂໍ້ຜິດພາດ', error.message, 'error');
        return;
    }

    // 3. ล้างออกจาก LocalStorage clinic_partial_labs
    try {
        let partialMap = JSON.parse(localStorage.getItem('clinic_partial_labs') || '{}');
        delete partialMap[visitId];
        localStorage.setItem('clinic_partial_labs', JSON.stringify(partialMap));
        if (window._clinicPartialLabsMap) delete window._clinicPartialLabsMap[visitId];
    } catch (e) { }

    Swal.fire({
        title: 'ສຳເລັດ!',
        html: `ສົ່ງຜົນກວດຄົບຖ້ວນຂອງເຄສ <strong>${visitId}</strong> ໄປຫ້ອງຈັດຄິວອ່ານຜົນແລ້ວ<br><span class="small text-muted">ເຄສນີ້ໄດ້ອອກຈາກຫ້ອງ Lab ຮຽບຮ້ອຍແລ້ວ</span>`,
        icon: 'success',
        confirmButtonColor: '#0b3c73'
    });

    // รีเฟรชตารางห้องแล็บ และห้องจัดคิว
    if (typeof loadLabQueue === 'function') loadLabQueue();
    if (typeof loadQueueList === 'function') loadQueueList();
}

/**
 * จัดการส่งผลแล็บแบบบางส่วน (ยังคงค้างอยู่ในห้องแล็บ)
 */
async function handlePartialLabSend(visitId, currentLabNote, currentPendingNote) {
    const isLao = (window.currentLang || localStorage.getItem('clinic_lang') || 'la') === 'la';

    // ให้ระบุหมายเหตุสั้นๆ ว่ารอผลอะไร หรือรออีกกี่วัน
    const { value: pendingText, isConfirmed } = await Swal.fire({
        title: isLao ? 'ລະບຸລາຍລະອຽດຜົນກວດທີ່ຍັງລໍຖ້າ' : 'ระบุรายละเอียดผลตรวจที่ยังรอ',
        input: 'text',
        inputLabel: isLao ? 'ລາຍການທີ່ຍັງລໍຖ້າ ຫຼື ຈຳນວນມື້ (ຕົວຢ່າງ: ລໍຖ້າຜົນກວດ 3 ວັນ, ລໍຖ້າຜົນຊິ້ນຊີ້ນ):' : 'รายการที่ยังรอ หรือจำนวนวัน (ตัวอย่าง: รอผลตรวจ 3 วัน, รอผลชิ้นเนื้อ):',
        inputValue: currentPendingNote || (isLao ? 'ລໍຖ້າຜົນກວດເພີ່ມເຕີມ 3 ວັນ' : 'รอผลตรวจเพิ่มเติม 3 วัน'),
        showCancelButton: true,
        confirmButtonColor: '#f59e0b',
        cancelButtonColor: '#64748b',
        confirmButtonText: isLao ? 'ຢືນຢັນສົ່ງຜົນບາງສ່ວນ' : 'ยืนยันส่งผลบางส่วน',
        cancelButtonText: isLao ? 'ຍົກເລີກ' : 'ยกเลิก'
    });

    if (!isConfirmed) return;

    Swal.fire({ title: 'ກຳລັງບັນທຶກ...', allowOutsideClick: false, didOpen: () => Swal.showLoading() });

    const noteTag = `[รอผลแล็บเพิ่มเติม: ${pendingText ? pendingText.trim() : 'รอผลตรวจเพิ่มเติม'}]`;

    // ลบแท็กเก่าออกก่อน (ถ้ามี) แล้วต่อท้ายอันใหม่
    let cleanedNote = (currentLabNote || '')
        .replace(/\[รอผลแล็บเพิ่มเติม(?::\s*[^\]]*)?\]/g, '')
        .trim();
    let finalNote = cleanedNote ? `${cleanedNote}\n${noteTag}` : noteTag;

    // 1. อัปเดต Supabase: เปลี่ยนสถานะเป็น "รอผลแล็บเพิ่มเติม" เพื่อให้ค้างอยู่ในห้อง Lab และห้องจัดคิว
    const { error } = await _supabase
        .from('visits')
        .update({
            status: 'รอผลแล็บเพิ่มเติม',
            lab_note: finalNote
        })
        .eq('visit_id', visitId);

    if (error) {
        Swal.fire('ຂໍ້ຜິດພາດ', error.message, 'error');
        return;
    }

    // 2. บันทึกลง LocalStorage clinic_partial_labs
    try {
        let partialMap = JSON.parse(localStorage.getItem('clinic_partial_labs') || '{}');
        partialMap[visitId] = {
            visitId: visitId,
            pendingNote: pendingText ? pendingText.trim() : 'รอผลตรวจเพิ่มเติม',
            updatedAt: new Date().toISOString()
        };
        localStorage.setItem('clinic_partial_labs', JSON.stringify(partialMap));
        if (window._clinicPartialLabsMap) window._clinicPartialLabsMap[visitId] = partialMap[visitId];
    } catch (e) { }

    Swal.fire({
        title: isLao ? 'ສົ່ງຜົນກວດບາງສ່ວນສຳເລັດ!' : 'ส่งผลตรวจบางส่วนสำเร็จ!',
        html: `
            <div class="text-start">
                <p>ສົ່ງຜົນກວດຕົວທຳອິດຂອງເຄສ <strong>${visitId}</strong> ໄປໃຫ້ທ່ານໝໍອ່ານຜົນຮຽບຮ້ອຍແລ້ວ</p>
                <div class="alert alert-warning py-2 px-3 small border-0" style="background-color: #fef3c7; color: #92400e;">
                    <i class="bi bi-info-circle-fill me-1"></i> <strong>ຫມາຍເຫດ:</strong> ເຄສນີ້ຈະຍັງຄົງສະແດງຢູ່ໃນຫ້ອງ Lab ພ້ອມປ້າຍ <strong>"ລໍຖ້າຜົນເພີ່ມເຕີມ"</strong> ເພື່ອໃຫ້ທ່ານກັບມາອັບໂຫຼດຜົນທີ່ເຫຼືອເມື່ອຮອດກຳນົດ
                </div>
            </div>
        `,
        icon: 'success',
        confirmButtonColor: '#0b3c73'
    });

    // รีเฟรชตารางห้องแล็บ และห้องจัดคิว
    if (typeof loadLabQueue === 'function') loadLabQueue();
    if (typeof loadQueueList === 'function') loadQueueList();
}
function openLabUploadModal(visitId) {
    try {
        // 1. เคลียร์ฉากหลัง (Backdrop) ที่อาจตกค้างออกทั้งหมด ป้องกันอาการจอมืดค้าง
        document.querySelectorAll('.modal-backdrop').forEach(el => el.remove());
        document.body.classList.remove('modal-open');
        document.body.style.removeProperty('overflow');
        document.body.style.removeProperty('padding-right');

        // 2. รีเซ็ตฟอร์มอัปโหลดอย่างปลอดภัย
        const form = document.getElementById('labUploadForm');
        if (form) form.reset();

        const visitIdInput = document.getElementById('uploadVisitId');
        if (visitIdInput) visitIdInput.value = visitId;

        const previewContainer = document.getElementById('labFilePreviewContainer');
        if (previewContainer) {
            previewContainer.innerHTML = '';
            previewContainer.style.display = 'none';
        }

        // 3. แสดง Modal อัปโหลดผลตรวจแล็บ
        const modalEl = document.getElementById('labUploadModal');
        if (modalEl) {
            modalEl.style.zIndex = '1060';
            const modalInstance = bootstrap.Modal.getOrCreateInstance(modalEl);
            modalInstance.show();
        } else {
            console.error('ไม่พบ element #labUploadModal');
        }
    } catch (err) {
        console.error('openLabUploadModal Error:', err);
    }
}

async function submitLabUpload() {
    const fileInput = document.getElementById('pdfFile');
    const file = fileInput ? fileInput.files[0] : null;
    const visitId = document.getElementById('uploadVisitId')?.value || document.getElementById('vascVisitId')?.value || '';
    const categorySelect = document.getElementById('labCategorySelect');
    const category = categorySelect ? categorySelect.value : '';

    if (!file) {
        Swal.fire('แจ้งเตือน', 'กรุณาเลือกไฟล์ผลแล็บที่ต้องการอัปโหลด (PDF หรือ รูปภาพ)', 'warning');
        return;
    }

    if (!visitId) {
        Swal.fire('แจ้งเตือน', 'ไม่พบรหัส VISIT ผู้ป่วย กรุณาลองใหม่อีกครั้ง', 'warning');
        return;
    }

    Swal.fire({ title: 'กำลังบันทึกไฟล์ผลแล็บ...', html: 'กรุณารอสักครู่ ห้ามปิดหน้าจอ', allowOutsideClick: false, didOpen: () => Swal.showLoading() });

    const reader = new FileReader();
    reader.onload = async function (e) {
        const fileDataUrl = e.target.result; // Base64
        let publicUrl = fileDataUrl; // ลิงก์สำหรับบันทึก

        const ext = file.name.split('.').pop() || 'pdf';
        const fileName = `${visitId}_LabResult_${Date.now()}.${ext}`;
        const fileId = `FILE-${visitId}-${Date.now()}-${Math.floor(Math.random() * 1000)}`;

        // 1. พยายามอัปโหลดขึ้น Supabase Storage (หากใช้งานได้)
        if (typeof _supabase !== 'undefined' && _supabase.storage) {
            try {
                const { data: uploadData, error: uploadError } = await _supabase
                    .storage
                    .from('lab-results')
                    .upload(fileName, file, { cacheControl: '3600', upsert: true, contentType: file.type });

                if (!uploadError) {
                    const { data: urlData } = _supabase
                        .storage
                        .from('lab-results')
                        .getPublicUrl(fileName);

                    if (urlData && urlData.publicUrl) {
                        publicUrl = urlData.publicUrl;
                    }
                } else {
                    console.warn("Storage Upload Warning:", uploadError);
                }
            } catch (err) {
                console.warn("Storage Catch Warning:", err);
            }
        }

        const newFileItem = {
            id: fileId,
            visitId: visitId,
            url: publicUrl || fileDataUrl,
            publicUrl: publicUrl || fileDataUrl,
            fileName: file.name,
            fileType: file.type,
            category: category || 'ผลแล็บ',
            updatedAt: new Date().toISOString()
        };

        // 2. บันทึกไฟล์ฉบับเต็มลงใน IndexedDB ของเครื่องปัจจุบัน
        await LabDB.saveFile(newFileItem);

        // 3. บันทึก Metadata น้ำหนักเบาลงใน LocalStorage ของเครื่องปัจจุบัน
        try {
            const metaMap = JSON.parse(localStorage.getItem('clinic_lab_files_meta') || '{}');
            let visitMetaList = metaMap[visitId];

            if (!Array.isArray(visitMetaList)) {
                visitMetaList = [];
            }

            // เฉพาะ URL ภายนอกที่ไม่ใช่ Data URL ขนาดใหญ่
            const safePublicUrl = (newFileItem.publicUrl && !newFileItem.publicUrl.startsWith('data:')) ? newFileItem.publicUrl : '';
            const safeUrl = (newFileItem.url && !newFileItem.url.startsWith('data:')) ? newFileItem.url : '';

            visitMetaList.push({
                id: fileId,
                visitId: visitId,
                fileName: file.name,
                fileType: file.type,
                category: category || 'ผลแล็บ',
                publicUrl: safePublicUrl,
                url: safeUrl,
                updatedAt: new Date().toISOString()
            });

            metaMap[visitId] = visitMetaList;
            if (typeof window.safeSetLocalStorage === 'function') {
                window.safeSetLocalStorage('clinic_lab_files_meta', metaMap);
            } else {
                localStorage.setItem('clinic_lab_files_meta', JSON.stringify(metaMap));
            }
        } catch (ex) {
            console.warn('LocalStorage meta save notice:', ex);
        }

        // 4. 🌟 บันทึกไฟล์ทั้งหมดลงใน Supabase DB (visits.pdf_url) เพื่อให้ทุกเครื่องในระบบและเครือข่ายเปิดดูได้ 100%
        if (typeof _supabase !== 'undefined') {
            try {
                let existingFiles = [];
                const { data: visitRow } = await _supabase
                    .from('visits')
                    .select('pdf_url')
                    .eq('visit_id', visitId)
                    .maybeSingle();

                if (visitRow && visitRow.pdf_url) {
                    const rawUrl = visitRow.pdf_url;
                    if (rawUrl.trim().startsWith('[')) {
                        try {
                            const parsed = JSON.parse(rawUrl);
                            if (Array.isArray(parsed)) existingFiles = parsed;
                        } catch (e) { }
                    } else if (isValidLabFileUrl(rawUrl)) {
                        existingFiles.push({
                            id: 'FILE-LEGACY-' + Date.now(),
                            fileName: 'ไฟล์ผลแล็บเดิม',
                            category: 'ผลแล็บ',
                            url: rawUrl,
                            publicUrl: rawUrl,
                            updatedAt: new Date().toISOString()
                        });
                    }
                }

                // กรองไม่ให้ซ้ำ แล้วเพิ่มไฟล์ใหม่เข้าไป
                existingFiles = existingFiles.filter(f => f && (f.id !== newFileItem.id && f.fileName !== newFileItem.fileName));
                existingFiles.push({
                    id: newFileItem.id,
                    fileName: newFileItem.fileName,
                    fileType: newFileItem.fileType,
                    category: newFileItem.category,
                    url: newFileItem.url,
                    publicUrl: newFileItem.publicUrl,
                    updatedAt: newFileItem.updatedAt
                });

                await _supabase
                    .from('visits')
                    .update({
                        pdf_url: JSON.stringify(existingFiles)
                    })
                    .eq('visit_id', visitId);

                console.log('Successfully synced lab files to Supabase DB for visit', visitId);
            } catch (dbErr) {
                console.warn('Update visit pdf_url warn:', dbErr);
            }
        }

        const catText = category ? `หมวดหมู่ "${category}"` : 'ผลแล็บ';
        Swal.fire({
            icon: 'success',
            title: 'อัปโหลดสำเร็จ',
            text: `บันทึกเอกสาร ${catText} ("${file.name}") ลงคอลัมน์ผลตรวจทั้งหมดเรียบร้อยแล้ว`,
            timer: 1800,
            showConfirmButton: false
        });

        const modalEl = document.getElementById('labUploadModal');
        if (modalEl) {
            const instance = bootstrap.Modal.getInstance(modalEl);
            if (instance) instance.hide();
            setTimeout(() => {
                document.querySelectorAll('.modal-backdrop').forEach(el => el.remove());
                document.body.classList.remove('modal-open');
                document.body.style.removeProperty('overflow');
            }, 300);
        }

        // รีเฟรชตารางห้องแล็บเพื่อโชว์ปุ่มไฟล์แล็บตามหมวดหมู่ในช่อง "ผลตรวจทั้งหมด" ทันที!
        if (typeof loadLabQueue === 'function') loadLabQueue();
        if (typeof loadQueueList === 'function') loadQueueList();
        if (typeof loadPrescriptionList === 'function') loadPrescriptionList();
    };

    reader.readAsDataURL(file);
}

// ฟังก์ชั่นเปิดดูเอกสารผลแล็บจริง (PDF / รูปภาพ JPG, PNG, WEBP)
async function viewRealLabFile(fileUrlOrId, visitId, patientName, categoryName) {
    let fileUrl = fileUrlOrId || '';
    let titleText = categoryName ? `เอกสาร ${categoryName}` : 'ผลตรวจ Lab';

    // 1. ถ้าระบุเป็น fileId (ขึ้นต้นด้วย FILE-) ให้พยายามดึงไฟล์ฉบับเต็มจาก IndexedDB
    if (fileUrl && fileUrl.startsWith('FILE-')) {
        try {
            const fileObj = await LabDB.getFile(fileUrl);
            if (fileObj && isValidLabFileUrl(fileObj.url || fileObj.publicUrl)) {
                fileUrl = fileObj.url || fileObj.publicUrl;
                if (fileObj.category) titleText = `เอกสาร ${fileObj.category}`;
            }
        } catch (e) {
            console.warn('LabDB getFile error:', e);
        }
    }

    // 2. หากยังไม่มี URL ที่ถูกต้อง ให้ค้นหาไฟล์สำหรับ visitId นี้โดยอัตโนมัติ
    if (!isValidLabFileUrl(fileUrl)) {
        const availableFiles = await getLabFilesForVisitAsync(visitId);
        let matchFile = null;
        if (categoryName) {
            matchFile = availableFiles.find(f => f.category === categoryName && isValidLabFileUrl(f.url || f.publicUrl));
        }
        if (!matchFile && availableFiles.length > 0) {
            matchFile = availableFiles.find(f => isValidLabFileUrl(f.url || f.publicUrl));
        }
        if (matchFile) {
            if (matchFile.id && matchFile.id.startsWith('FILE-')) {
                try {
                    const fObj = await LabDB.getFile(matchFile.id);
                    if (fObj && isValidLabFileUrl(fObj.url || fObj.publicUrl)) {
                        fileUrl = fObj.url || fObj.publicUrl;
                    }
                } catch (e) { }
            }
            if (!isValidLabFileUrl(fileUrl)) {
                fileUrl = matchFile.url || matchFile.publicUrl;
            }
            if (matchFile.category) titleText = `เอกสาร ${matchFile.category}`;
        }
    }

    // 3. หากไม่มีไฟล์จริง ให้แจ้งเตือนผู้ใช้งานอย่างชัดเจน และหยุดทำงาน
    if (!isValidLabFileUrl(fileUrl)) {
        Swal.fire({
            icon: 'info',
            title: '<h5 class="fw-bold mb-0 text-primary">ยังไม่มีไฟล์เอกสารผลตรวจ</h5>',
            html: `
                <div class="text-center p-3">
                    <div class="mb-3">
                        <i class="bi bi-file-earmark-x text-warning" style="font-size: 3.5rem;"></i>
                    </div>
                    <div class="fw-bold text-dark fs-6 mb-1">ผู้ป่วย: ${patientName || '-'}</div>
                    <div class="text-muted small mb-2">รหัสเคส: <span class="font-monospace">${visitId || '-'}</span></div>
                    <div class="alert alert-light border small text-muted text-start mt-3 mb-0">
                        <i class="bi bi-info-circle me-1 text-primary"></i> ยังไม่มีการอัปโหลดไฟล์ผลตรวจ <strong>${categoryName || ''}</strong> จากห้อง Lab เข้าสู่ระบบ
                    </div>
                </div>
            `,
            confirmButtonText: 'รับทราบ / ปิดหน้าต่าง',
            confirmButtonColor: '#0b3c73',
            width: '460px'
        });
        return;
    }

    const isImage = fileUrl.startsWith('data:image/') ||
        fileUrl.match(/\.(jpeg|jpg|gif|png|webp)($|\?)/i);

    if (isImage) {
        Swal.fire({
            title: `<h5 class="fw-bold mb-0 text-primary"><i class="bi bi-file-earmark-image me-2"></i>${titleText} - ${patientName || visitId}</h5>`,
            html: `
                <div class="text-center p-2">
                    <div class="d-flex justify-content-end mb-2">
                        <button type="button" onclick="openLabPdfDirect('${fileUrl}', 'lab_${visitId}.png')" class="btn btn-sm btn-outline-primary rounded-pill px-3 fw-semibold">
                            <i class="bi bi-box-arrow-up-right me-1"></i> เปิดดูรูปขนาดเต็ม / ดาวน์โหลด
                        </button>
                    </div>
                    <img src="${fileUrl}" class="img-fluid rounded border shadow-sm" style="max-height: 70vh; object-fit: contain;">
                </div>
            `,
            width: '850px',
            showCloseButton: true,
            confirmButtonText: 'ปิดหน้าต่าง',
            confirmButtonColor: '#0b3c73'
        });
    } else {
        let pdfTargetUrl = fileUrl;
        if (fileUrl.startsWith('data:application/pdf;base64,')) {
            try {
                const base64Data = fileUrl.split(',')[1];
                const blob = base64ToBlob(base64Data, 'application/pdf');
                pdfTargetUrl = URL.createObjectURL(blob);
            } catch (e) {
                console.error('Base64 pdf decode error:', e);
            }
        }

        window._currentLabPdfBlobUrl = pdfTargetUrl;
        window._currentLabPdfRawUrl = fileUrl;

        Swal.fire({
            title: `<h5 class="fw-bold mb-0 text-danger"><i class="bi bi-file-earmark-pdf-fill me-2"></i>${titleText} (PDF) - ${patientName || visitId}</h5>`,
            html: `
                <div class="p-1 d-flex flex-column" style="height: 72vh;">
                    <div class="d-flex justify-content-between align-items-center mb-2 px-1">
                        <span class="small text-muted"><i class="bi bi-person me-1"></i>${patientName || visitId}</span>
                        <div class="d-flex gap-2">
                            <button type="button" class="btn btn-sm btn-primary rounded-pill px-3 fw-bold shadow-xs" onclick="openLabPdfDirect(window._currentLabPdfBlobUrl || window._currentLabPdfRawUrl, 'lab_${visitId}.pdf')">
                                <i class="bi bi-box-arrow-up-right me-1"></i> เปิดในแท็บใหม่ / ดาวน์โหลด PDF
                            </button>
                        </div>
                    </div>
                    <div class="flex-grow-1 border rounded-3 overflow-hidden bg-light position-relative d-flex flex-column">
                        <iframe src="${pdfTargetUrl}" style="width: 100%; height: 100%; min-height: 480px; border: none;" allowfullscreen></iframe>
                        <div class="p-3 bg-white border-top text-center">
                            <button type="button" class="btn btn-sm btn-outline-danger rounded-pill px-4 fw-semibold" onclick="openLabPdfDirect(window._currentLabPdfBlobUrl || window._currentLabPdfRawUrl, 'lab_${visitId}.pdf')">
                                <i class="bi bi-file-earmark-pdf me-1"></i> หากเอกสารไม่แสดงผล กรุณากดที่นี่เพื่อเปิดดูหรือดาวน์โหลดไฟล์ PDF
                            </button>
                        </div>
                    </div>
                </div>
            `,
            width: '950px',
            showCloseButton: true,
            confirmButtonText: 'ปิดหน้าต่าง',
            confirmButtonColor: '#0b3c73'
        });
    }
}

window.openLabPdfDirect = function (targetUrl, filename) {
    const urlToOpen = targetUrl || window._currentLabPdfBlobUrl || window._currentLabPdfRawUrl;
    if (!urlToOpen) return;

    if (urlToOpen.startsWith('data:application/pdf;base64,')) {
        try {
            const base64Data = urlToOpen.split(',')[1];
            const blob = base64ToBlob(base64Data, 'application/pdf');
            const blobUrl = URL.createObjectURL(blob);
            const w = window.open(blobUrl, '_blank');
            if (!w) {
                const a = document.createElement('a');
                a.href = blobUrl;
                a.target = '_blank';
                a.download = filename || 'lab_result.pdf';
                document.body.appendChild(a);
                a.click();
                document.body.removeChild(a);
            }
            return;
        } catch (e) {
            console.warn('openLabPdfDirect blob error:', e);
        }
    }

    const w = window.open(urlToOpen, '_blank');
    if (!w) {
        const a = document.createElement('a');
        a.href = urlToOpen;
        a.target = '_blank';
        a.download = filename || 'lab_result.pdf';
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
    }
};

function base64ToBlob(base64, type = 'application/octet-stream') {
    const binStr = atob(base64);
    const len = binStr.length;
    const arr = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
        arr[i] = binStr.charCodeAt(i);
    }
    return new Blob([arr], { type: type });
}

