window.selectedCommLogIds = window.selectedCommLogIds || new Set();

function toggleSelectAllCommLogs(masterCb) {
    const checkboxes = document.querySelectorAll('.comm-log-checkbox');
    checkboxes.forEach(cb => {
        cb.checked = masterCb.checked;
        if (masterCb.checked) {
            window.selectedCommLogIds.add(String(cb.value));
        } else {
            window.selectedCommLogIds.delete(String(cb.value));
        }
    });
    updateCommLogSelectState();
}

function onCommLogCheckboxChange(id, checked) {
    if (checked) {
        window.selectedCommLogIds.add(String(id));
    } else {
        window.selectedCommLogIds.delete(String(id));
    }
    updateCommLogSelectState();
}

function updateCommLogSelectState() {
    const checkboxes = document.querySelectorAll('.comm-log-checkbox');
    const master = document.getElementById('selectAllCommLogs');
    const countEl = document.getElementById('selectedCommCount');
    const batchBtn = document.getElementById('btnBatchPayoutCommLogs');

    let checkedCount = 0;
    checkboxes.forEach(cb => {
        if (cb.checked) checkedCount++;
    });

    if (master) {
        master.checked = (checkboxes.length > 0 && checkedCount > 0 && checkedCount === checkboxes.length);
        master.indeterminate = (checkedCount > 0 && checkedCount < checkboxes.length);
    }

    const selectedSize = window.selectedCommLogIds ? window.selectedCommLogIds.size : 0;
    if (countEl) countEl.textContent = selectedSize;

    if (batchBtn) {
        if (selectedSize > 0) {
            batchBtn.classList.remove('d-none');
            batchBtn.classList.add('d-flex');
        } else {
            batchBtn.classList.add('d-none');
            batchBtn.classList.remove('d-flex');
        }
    }
}

async function batchPayoutCommissionLogs() {
    if (!window.selectedCommLogIds || window.selectedCommLogIds.size === 0) {
        Swal.fire('ข้อผิดพลาด', 'โปรดเลือกรายการเงินปันผลที่ต้องการจ่ายเงินก่อน', 'warning');
        return;
    }

    const selectedIds = Array.from(window.selectedCommLogIds);
    const pendingLogs = (window.commissionLogs || []).filter(l => selectedIds.includes(String(l.id)) && l.status === 'pending');

    if (pendingLogs.length === 0) {
        Swal.fire('แจ้งเตือน', 'รายการที่เลือกทั้งหมดมีสถานะจ่ายเงินเรียบร้อยแล้ว', 'info');
        return;
    }

    let totalBatchAmount = 0;
    pendingLogs.forEach(l => {
        const b = l.base_amount !== undefined ? parseFloat(l.base_amount) : parseFloat(l.amount || 0);
        const i = parseFloat(l.item_amount || 0);
        totalBatchAmount += (b + i);
    });

    const { value: formValues } = await Swal.fire({
        title: '<h5 class="fw-bold mb-0 text-success"><i class="ph ph-hand-coins me-2"></i>อนุมัติจ่ายเงินปันผลที่เลือก (' + pendingLogs.length + ' รายการ)</h5>',
        html: `
            <div class="text-start p-2" style="font-size: 0.9rem;">
                <div class="p-3 bg-light rounded-3 border mb-3">
                    <div class="d-flex justify-content-between mb-1">
                        <span class="text-muted">จำนวนรายการรอจ่าย:</span>
                        <strong class="text-dark">${pendingLogs.length} รายการ</strong>
                    </div>
                    <div class="d-flex justify-content-between mt-2 pt-1 border-top">
                        <span class="fw-bold text-dark fs-6">ยอดรวมปันผลจ่ายสุทธิ:</span>
                        <strong class="text-success fs-5">${formatCommissionAmount(totalBatchAmount)}</strong>
                    </div>
                </div>

                <div class="mb-3">
                    <label class="form-label fw-bold small text-secondary">ช่องทางการจ่ายเงิน</label>
                    <select id="swalBatchPayoutMethod" class="form-select custom-input py-2">
                        <option value="โอนเงินผ่านธนาคาร (อนุมัติจ่ายแล้ว)">โอนเงินผ่านธนาคาร</option>
                        <option value="เงินสด">เงินสด</option>
                        <option value="เช็ค / อื่นๆ">เช็ค / อื่นๆ</option>
                    </select>
                </div>
                <div class="mb-2">
                    <label class="form-label fw-bold small text-secondary">เลขที่อ้างอิง / สลิปโอนเงิน (ถ้ามี)</label>
                    <input type="text" id="swalBatchPayoutRef" class="form-control custom-input py-2" placeholder="เช่น BATCH-${Date.now().toString().slice(-6)}">
                </div>
            </div>
        `,
        focusConfirm: false,
        showCancelButton: true,
        confirmButtonText: '<i class="bi bi-check-circle-fill me-1"></i> ยืนยันอนุมัติจ่ายเงิน',
        cancelButtonText: 'ยกเลิก',
        confirmButtonColor: '#10b981',
        preConfirm: () => {
            const method = document.getElementById('swalBatchPayoutMethod').value;
            const ref = document.getElementById('swalBatchPayoutRef').value.trim() || 'อนุมัติจ่ายแล้ว (แบบกลุ่ม)';
            return { method, ref };
        }
    });

    if (formValues) {
        const nowIso = new Date().toISOString();
        for (const log of pendingLogs) {
            log.status = 'paid';
            log.paid_at = nowIso;
            log.payout_method = formValues.method;
            log.payout_ref = formValues.ref;

            try {
                if (typeof _supabase !== 'undefined') {
                    await _supabase.from('commission_logs').update({
                        status: 'paid',
                        paid_at: log.paid_at,
                        payout_method: formValues.method,
                        payout_ref: formValues.ref
                    }).eq('id', log.id);
                }
            } catch (e) {
                console.warn('Supabase log batch payout update fallback');
            }
        }

        saveReferralLocalData();
        window.selectedCommLogIds.clear();

        updateReferralSummaryCards();
        renderCommissionLogsTable();
        renderReferrersTable();

        Swal.fire({
            icon: 'success',
            title: 'อนุมัติจ่ายเงินปันผลเรียบร้อย!',
            text: `ทำการจ่ายเงินปันผลจำนวน ${pendingLogs.length} รายการ เรียบร้อยแล้ว`,
            confirmButtonColor: '#003f88'
        });
    }
}
window.batchPayoutCommissionLogs = batchPayoutCommissionLogs;

window.commLogCurrentPage = 1;
const COMM_LOGS_PER_PAGE = 25;

function changeCommLogPage(page) {
    renderCommissionLogsTable(page);
}
window.changeCommLogPage = changeCommLogPage;

// ⏱️ Debounce Search (350ms) เพื่อลดภาระการประมวลผลขณะพิมพ์
let commLogSearchTimer = null;
function debounceCommLogSearch() {
    clearTimeout(commLogSearchTimer);
    commLogSearchTimer = setTimeout(() => {
        if (typeof renderCommissionLogsTable === 'function') {
            renderCommissionLogsTable(1);
        }
    }, 350);
}
window.debounceCommLogSearch = debounceCommLogSearch;

let referrerSearchTimer = null;
function debounceReferrerSearch() {
    clearTimeout(referrerSearchTimer);
    referrerSearchTimer = setTimeout(() => {
        if (typeof filterReferrersTable === 'function') {
            filterReferrersTable();
        }
    }, 350);
}
window.debounceReferrerSearch = debounceReferrerSearch;

function renderCommissionLogsTable(page) {
    if (typeof page === 'number' && !isNaN(page)) {
        window.commLogCurrentPage = page;
    }
    if (!window.commLogCurrentPage || isNaN(window.commLogCurrentPage) || window.commLogCurrentPage < 1) {
        window.commLogCurrentPage = 1;
    }

    const tbody = document.querySelector('#commissionLogsTable tbody');
    if (!tbody) return;

    const filterEl = document.getElementById('filterLogStatus');
    const filterStatus = filterEl ? filterEl.value : 'all';

    const searchInput = document.getElementById('searchLogInput');
    const searchText = searchInput ? searchInput.value.toLowerCase().trim() : '';

    const sDateInput = document.getElementById('filterLogStartDate');
    const eDateInput = document.getElementById('filterLogEndDate');
    const sDate = sDateInput ? sDateInput.value : '';
    const eDate = eDateInput ? eDateInput.value : '';

    tbody.innerHTML = '';

    // ป้องกัน Error หาก array ยังไม่ถูกโหลด
    let logs = [...(window.commissionLogs || [])];

    // กรอง mock data เก่า และรายการที่ถูกลบออกเด็ดขาด
    const isMockCommLog = (l) => {
        if (!l) return false;
        const id = String(l.id || '');
        const vId = String(l.visit_id || '');
        if (/^COM-5000[1-9]$/.test(id)) return true;
        if (/^VIS-34517[3-9]$/.test(vId) || /^VIS-34518[0-1]$/.test(vId)) return true;
        return false;
    };
    logs = logs.filter(l => l && !isMockCommLog(l));

    // 1. นำการกรอง visit_id ออก เพื่อให้แสดงปันผลได้ครบทุกรายการแม้อยู่ในบิลเดียวกัน
    const seenLogIds = new Set();
    logs = logs.filter(l => {
        if (l.id) {
            if (seenLogIds.has(l.id)) return false;
            seenLogIds.add(l.id);
        }
        return true;
    });

    // Filter out logs for visits that are currently unpaid at Cashier
    const unpaidVisitIds = new Set();
    const allVis = (window.clinicVisits || []).concat(window.allPaymentQueue || []);
    allVis.forEach(v => {
        const vId = v.visit_id || v.id;
        const vStatus = (v.status || '').trim();
        if (vId && vStatus === 'รอชำระเงิน' && v.payment_status !== 'paid' && !v.bill_id) {
            unpaidVisitIds.add(vId);
        }
    });

    if (unpaidVisitIds.size > 0) {
        logs = logs.filter(l => !l.visit_id || !unpaidVisitIds.has(l.visit_id));
    }

    // 3. Filter by Status
    if (filterStatus !== 'all') {
        logs = logs.filter(l => l.status === filterStatus);
    }

    const allVisitsList = (window.clinicVisits || []).concat(window.allVisitsCache || []);
    const getTrueLogDate = (l) => {
        if (!l) return '';
        if (l.visit_id) {
            const mv = allVisitsList.find(v => (v.visit_id || v.id) === l.visit_id);
            if (mv && (mv.created_at || mv.date)) return mv.created_at || mv.date;
        }
        return l.created_at || '';
    };

    // 4. Filter by Date Range (Start Date - End Date)
    if (sDate || eDate) {
        logs = logs.filter(l => {
            const rawD = getTrueLogDate(l);
            if (!rawD) return false;
            const logDate = parseLogDateToYMD(rawD);
            if (!logDate) return false;
            if (sDate && logDate < sDate) return false;
            if (eDate && logDate > eDate) return false;
            return true;
        });
    }

    // 5. Filter by Search input text
    if (searchText) {
        logs = logs.filter(l => {
            const refName = (l.referrer_name || '').toLowerCase();
            const patName = (l.patient_name || '').toLowerCase();
            const logId = (l.id || '').toLowerCase();
            const visitId = (l.visit_id || '').toLowerCase();
            const itemDetails = (l.item_details || '').toLowerCase();
            const payoutMethod = (l.payout_method || '').toLowerCase();
            const payoutRef = (l.payout_ref || '').toLowerCase();

            return refName.includes(searchText) ||
                patName.includes(searchText) ||
                logId.includes(searchText) ||
                visitId.includes(searchText) ||
                itemDetails.includes(searchText) ||
                payoutMethod.includes(searchText) ||
                payoutRef.includes(searchText);
        });
    }

    // 4. Sort logs: Pending status items ALWAYS come first at Rank 1, followed by newest timestamp
    logs.sort((a, b) => {
        const isPendingA = a.status === 'pending' ? 1 : 0;
        const isPendingB = b.status === 'pending' ? 1 : 0;

        if (isPendingA !== isPendingB) {
            return isPendingB - isPendingA; // Pending items appear FIRST at the top!
        }

        const timeA = new Date(getTrueLogDate(a) || 0).getTime();
        const timeB = new Date(getTrueLogDate(b) || 0).getTime();
        if (timeA !== timeB) {
            return timeB - timeA; // Secondary sort: Newest timestamp first
        }
        return (b.id || '').localeCompare(a.id || '', undefined, { numeric: true, sensitivity: 'base' });
    });

    // Calculate totals across ALL filtered logs for the summary bar
    let totalInvoiceSum = 0;
    let totalBaseSum = 0;
    let totalItemSum = 0;
    logs.forEach(l => {
        const baseVal = (l.base_amount !== undefined && l.base_amount !== null) ? parseFloat(l.base_amount) : 0;
        const itemVal = (l.item_amount !== undefined && l.item_amount !== null) ? parseFloat(l.item_amount) : 0;
        const invoiceVal = parseFloat(l.total_invoice || 0);
        totalInvoiceSum += invoiceVal;
        totalBaseSum += baseVal;
        totalItemSum += itemVal;
    });

    // Pagination: 15 items per page
    const totalLogs = logs.length;
    const totalPages = Math.ceil(totalLogs / COMM_LOGS_PER_PAGE) || 1;
    if (window.commLogCurrentPage > totalPages) {
        window.commLogCurrentPage = totalPages;
    }
    const currentPage = window.commLogCurrentPage;
    const startIndex = (currentPage - 1) * COMM_LOGS_PER_PAGE;
    const pageLogs = logs.slice(startIndex, startIndex + COMM_LOGS_PER_PAGE);

    if (totalLogs === 0) {
        tbody.innerHTML = '<tr><td colspan="12" class="text-center text-muted py-5">ไม่มีประวัติรายการเงินปันผล/คอมมิชชั่น</td></tr>';
    } else {
        pageLogs.forEach((l, index) => {
            const rowNumber = startIndex + index + 1;
            const trueDateVal = getTrueLogDate(l);
            let dateStr = trueDateVal ? new Date(trueDateVal).toLocaleDateString('th-TH') : '-';
            let statusBadge = l.status === 'paid'
                ? '<span class="badge badge-paid"><i class="bi bi-check-circle-fill me-1"></i>จ่ายแล้ว</span>'
                : '<span class="badge badge-pending"><i class="bi bi-clock-history me-1"></i>รออนุมัติ / รอจ่าย</span>';

            let actionBtn = l.status === 'paid'
                ? `<span class="text-muted small"><i class="bi bi-info-circle me-1"></i>${l.payout_method || 'จ่ายแล้ว'} (${l.payout_ref || '-'})</span>`
                : `<button class="btn btn-sm btn-success px-3 fw-semibold shadow-xs" onclick="openPayoutModal('${l.id}')"><i class="ph ph-hand-coins me-1"></i> จ่ายเงินปันผล</button>`;

            let bonusBadge = l.is_bonus ? '<span class="badge bg-warning text-dark me-1" style="font-size: 0.7rem;"><i class="bi bi-trophy-fill"></i> โบนัสเป้าหมาย</span>' : '';

            let baseVal = (l.base_amount !== undefined && l.base_amount !== null) ? parseFloat(l.base_amount) : 0;
            let itemVal = (l.item_amount !== undefined && l.item_amount !== null) ? parseFloat(l.item_amount) : 0;
            let totalVal = (l.amount !== undefined && l.amount !== null) ? parseFloat(l.amount) : (baseVal + itemVal);

            let invoiceVal = parseFloat(l.total_invoice || 0);

            let overallText = formatCommissionAmount(baseVal);
            let itemText = formatCommissionAmount(itemVal);
            let totalText = formatCommissionAmount(totalVal);

            let isChecked = window.selectedCommLogIds.has(String(l.id));
            let checkAttr = isChecked ? 'checked' : '';

            // Resolve HN and Visit ID
            let resolvedHn = '';
            const allVisits = (window.clinicVisits || []).concat(window.allVisitsCache || []);
            const matchedVisit = allVisits.find(v => (v.visit_id || v.id) === l.visit_id);
            if (matchedVisit && matchedVisit.hn) {
                resolvedHn = matchedVisit.hn;
            } else if (l.patient_name && l.patient_name.includes(' - ')) {
                const parts = l.patient_name.split(' - ');
                if (parts[0] && parts[0].length >= 3 && parts[0].length <= 15) {
                    resolvedHn = parts[0].trim();
                }
            }
            if (!resolvedHn && window.allPatients && Array.isArray(window.allPatients)) {
                const cleanName = (l.patient_name || '').replace(/^[A-Za-z0-9_-]+\s*-\s*/, '').trim().toLowerCase();
                const matchedPat = window.allPatients.find(p =>
                    (p.patient_name || p.name || '').trim().toLowerCase() === cleanName ||
                    (p.patient_name || p.name || '').trim().toLowerCase() === (l.patient_name || '').trim().toLowerCase()
                );
                if (matchedPat && matchedPat.hn) resolvedHn = matchedPat.hn;
            }

            let billIdVal = l.bill_id || (l.id && l.id.startsWith('COM-BILL-') ? l.id.replace(/^COM-/, '') : '');
            let billBadge = billIdVal ? `<span class="badge bg-info-subtle text-info border border-info-subtle px-1.5 py-0.5 me-1" style="font-size: 0.7rem; font-weight: 500;" title="Bill ID"><i class="bi bi-receipt me-1"></i>${billIdVal}</span>` : '';
            let visitBadge = l.visit_id ? `<span class="badge bg-light text-secondary border px-1.5 py-0.5 me-1" style="font-size: 0.7rem; font-weight: 500;" title="Visit ID"><i class="bi bi-tag me-1"></i>${l.visit_id}</span>` : '';
            let hnBadge = resolvedHn ? `<span class="badge bg-primary-subtle text-primary border border-primary-subtle px-1.5 py-0.5 me-1" style="font-size: 0.7rem; font-weight: 600;" title="HN ผู้ป่วย">HN: ${resolvedHn}</span>` : '';

            // 🌟 แยกรหัสผู้แนะนำ (code) ออกจากชื่อ
            // รูปแบบที่เป็นไปได้: "L04280 - LOVE STK" หรือ "L04280-LOVE STK" หรือ "L04280 LOVE STK"
            const rawRefName = l.referrer_name || '-';
            let refCode = '';
            let refDisplayName = rawRefName;
            const codeNameSep = rawRefName.match(/^([A-Za-z0-9_\-]+?)\s*[-–]\s*(.+)$/);
            if (codeNameSep) {
                refCode = codeNameSep[1].trim();
                refDisplayName = codeNameSep[2].trim();
            } else {
                // ตรวจสอบจาก referrer_id โดยตรง
                if (l.referrer_id && l.referrer_id !== rawRefName) {
                    refCode = l.referrer_id;
                }
            }
            const refCodeBadge = refCode
                ? `<span class="badge bg-dark-subtle text-dark border fw-bold" style="font-size: 0.78rem; letter-spacing: 0.02em;">${refCode}</span>`
                : `<span class="text-muted small">-</span>`;

            tbody.innerHTML += `
                <tr class="${l.status === 'pending' ? 'table-warning-subtle fw-semibold' : ''}">
                    <td class="text-center ps-3" style="width: 40px;">
                        <input type="checkbox" class="form-check-input comm-log-checkbox" value="${l.id}" ${checkAttr} onchange="onCommLogCheckboxChange('${l.id}', this.checked)">
                    </td>
                    <td class="ps-2 fw-bold text-muted" style="width: 50px;">${rowNumber}</td>
                    <td class="small text-muted">${dateStr}</td>
                    <td class="text-center">${refCodeBadge}</td>
                    <td class="fw-bold text-dark">${refDisplayName}</td>
                    <td class="fw-medium">
                        <div class="fw-semibold text-dark">${l.patient_name || '-'} ${bonusBadge}</div>
                        <div class="d-flex align-items-center gap-1 mt-1 flex-wrap">
                            ${hnBadge}
                            ${visitBadge}
                            ${billBadge}
                        </div>
                    </td>
                    <td class="fw-semibold text-dark">${formatCommissionAmount(invoiceVal)}</td>
                    <td class="text-end">
                        <div class="fw-bold text-success fs-6">${overallText}</div>
                        <div class="extra-small text-muted font-monospace" style="font-size: 0.72rem;">ภาพรวม: ${overallText}</div>
                    </td>
                    <td class="text-end">
                        <div class="fw-bold text-success fs-6">${itemText}</div>
                        ${l.item_details ? `<div class="extra-small text-muted text-truncate" style="font-size: 0.72rem; max-width: 200px; margin-left: auto;" title="${l.item_details}"><i class="bi bi-card-checklist me-1"></i>${l.item_details}</div>` : `<div class="extra-small text-muted font-monospace" style="font-size: 0.72rem;">รายรายการ: ${itemText}</div>`}
                    </td>
                    <td class="text-end bg-light-subtle">
                        <div class="fw-bold text-success fs-6">${totalText}</div>
                        <div class="extra-small text-muted font-monospace" style="font-size: 0.72rem;">รวมทั้งหมด: ${totalText}</div>
                    </td>
                    <td class="text-center">${statusBadge}</td>
                    <td class="text-center pe-4">${actionBtn}</td>
                </tr>
            `;
        });
    }

    const totalCombinedSum = totalBaseSum + totalItemSum;

    if (document.getElementById('commFooterCount')) {
        document.getElementById('commFooterCount').textContent = totalLogs > 0
            ? `${totalLogs} รายการ (หน้า ${currentPage}/${totalPages})`
            : `0 รายการ`;
    }
    if (document.getElementById('commFooterInvoice')) document.getElementById('commFooterInvoice').textContent = formatCommissionAmount(totalInvoiceSum);
    if (document.getElementById('commFooterBase')) document.getElementById('commFooterBase').textContent = formatCommissionAmount(totalBaseSum);
    if (document.getElementById('commFooterItem')) document.getElementById('commFooterItem').textContent = formatCommissionAmount(totalItemSum);
    if (document.getElementById('commFooterTotal')) document.getElementById('commFooterTotal').textContent = formatCommissionAmount(totalCombinedSum);

    // วาดปุ่ม Pagination แสดง 15 รายการ/หน้า และตัวเลือกหน้า 1, 2, 3...
    const paginationContainer = document.getElementById('commLogPaginationContainer');
    if (paginationContainer) {
        if (totalLogs === 0) {
            paginationContainer.innerHTML = '';
        } else {
            const startDisplay = startIndex + 1;
            const endDisplay = Math.min(startIndex + COMM_LOGS_PER_PAGE, totalLogs);

            let pagHtml = `
                <div class="d-flex justify-content-between align-items-center w-100 px-2 flex-wrap gap-2">
                    <div class="text-muted small fw-semibold">
                        แสดง <strong class="text-dark">${startDisplay} - ${endDisplay}</strong> จากทั้งหมด <strong class="text-dark">${totalLogs}</strong> รายการ
                    </div>
                    <div class="d-flex justify-content-center align-items-center gap-1 flex-wrap">
            `;

            if (totalPages > 1) {
                // ปุ่มย้อนกลับ
                pagHtml += `
                    <button type="button" class="btn btn-sm btn-light border text-muted px-2.5 py-1 rounded-2" onclick="changeCommLogPage(${currentPage - 1})" ${currentPage === 1 ? 'disabled' : ''} style="font-size: 0.82rem;" title="หน้าก่อนหน้า">
                        <i class="bi bi-chevron-left"></i>
                    </button>
                `;

                // ปุ่มเลขหน้า 1, 2, 3...
                for (let i = 1; i <= totalPages; i++) {
                    if (i === 1 || i === totalPages || (i >= currentPage - 2 && i <= currentPage + 2)) {
                        const activeClass = (i === currentPage)
                            ? 'btn-primary text-white fw-bold shadow-xs'
                            : 'btn-light border text-dark';
                        pagHtml += `<button type="button" class="btn btn-sm ${activeClass} px-3 py-1 rounded-2" onclick="changeCommLogPage(${i})" style="font-size: 0.82rem; min-width: 34px;">${i}</button>`;
                    } else if (i === currentPage - 3 || i === currentPage + 3) {
                        pagHtml += `<span class="px-2 text-muted small">...</span>`;
                    }
                }

                // ปุ่มหน้าถัดไป
                pagHtml += `
                    <button type="button" class="btn btn-sm btn-light border text-muted px-2.5 py-1 rounded-2" onclick="changeCommLogPage(${currentPage + 1})" ${currentPage === totalPages ? 'disabled' : ''} style="font-size: 0.82rem;" title="หน้าถัดไป">
                        <i class="bi bi-chevron-right"></i>
                    </button>
                `;
            }

            pagHtml += `
                    </div>
                    <div class="text-muted small fw-semibold text-end d-none d-md-block" style="min-width: 140px;">
                        หน้า <strong class="text-primary">${currentPage}</strong> / <strong class="text-dark">${totalPages}</strong>
                    </div>
                </div>
            `;
            paginationContainer.innerHTML = pagHtml;
        }
    }

    updateCommLogSelectState();
}

