function populateReferrerDropdowns() {
    const datalist = document.getElementById('referrerDatalist');
    const selectEl = document.getElementById('patientReferredBySelect');
    const apptSelect = document.getElementById('apptReferredBySelect');

    let optionsHtml = '';
    const allEmp = window.allEmployeesData || [];

    allEmp.forEach(emp => {
        const code = emp.emp_code || emp.id || '';
        const name = emp.full_name || emp.name || '';
        if (code || name) {
            const valStr = `${code} - ${name}`;
            optionsHtml += `<option value="${valStr}">${valStr}</option>`;
        }
    });

    if (datalist) {
        datalist.innerHTML = optionsHtml;
    }

    [selectEl, apptSelect].forEach(el => {
        if (!el) return;
        if (el.tagName === 'SELECT') {
            const currVal = el.value;
            el.innerHTML = '<option value="">-- ไม่ระบุผู้แนะนำ (ไม่มีค่าปันผล) --</option>' + optionsHtml;
            if (currVal) el.value = currVal;
        } else if (el.tagName === 'INPUT') {
            el.setAttribute('list', 'referrerDatalist');
        }
    });
}

function saveServicesLocalData() {
    try {
        localStorage.setItem('hr_services_data', JSON.stringify(window.servicesData || []));
    } catch (e) {
        console.error('Save services local data error:', e);
    }
}
window.saveServicesLocalData = saveServicesLocalData;

async function loadServicesData() {
    let localData = [];
    const cached = localStorage.getItem('hr_services_data');
    if (cached) {
        try {
            localData = JSON.parse(cached) || [];
        } catch (e) { }
    }

    if (localData && localData.length > 0) {
        window.servicesData = localData;
    } else if (!window.servicesData || window.servicesData.length === 0) {
        window.servicesData = [
            { id: 'SRV-101', name: 'ตรวจความสมบูรณ์ของเม็ดเลือด (CBC)', price: 150000, currency: 'LAK', category: 'เลือดวิทยา (HEMATOLOGY)', description: 'Complete Blood Count', sub_items: [] },
            { id: 'SRV-102', name: 'ตรวจระดับน้ำตาลในเลือด (FBS)', price: 80000, currency: 'LAK', category: 'ชีวเคมี (Biochemistry)', description: 'Fasting Blood Sugar', sub_items: [] },
            { id: 'SRV-103', name: 'แพ็กเกจตรวจสุขภาพรวม (Health Checkup Package)', price: 300000, currency: 'LAK', category: 'ชีวเคมี (Biochemistry)', description: 'แพ็กเกจตรวจเลือดและปัสสาวะ', sub_items: [{ name: 'CBC', price: 150000 }, { name: 'FBS', price: 80000 }, { name: 'Urinalysis', price: 70000 }] }
        ];
    }
    renderServicesTable();

    try {
        const { data, error } = await _supabase.from('services').select('*').order('created_at', { ascending: false });
        if (!error && data && data.length > 0) {
            const processedData = data.map(item => {
                let parsedSubItems = item.sub_items;
                if (typeof parsedSubItems === 'string') {
                    try { parsedSubItems = JSON.parse(parsedSubItems); } catch (e) { parsedSubItems = []; }
                }
                return {
                    ...item,
                    category: getServiceCategory(item),
                    sub_items: Array.isArray(parsedSubItems) ? parsedSubItems : []
                };
            });

            window.servicesData = processedData;
            saveServicesLocalData();
            renderServicesTable();
        }
    } catch (e) {
        console.error('Error loading services from Supabase:', e);
        renderServicesTable();
    }
}

window.loadServices = loadServicesData;

window.servicesCurrentPage = 1;
window.servicesItemsPerPage = 10;
window.selectedServicesCategory = 'ALL';

function renderServicesTable(dataToRender) {
    const tbody = document.querySelector('#servicesTable tbody');
    if (!tbody) return;

    const services = dataToRender || window.servicesData || [];
    const countDisplay = document.getElementById('servicesTotalCountDisplay');
    const paginationEl = document.getElementById('servicesPagination');

    if (countDisplay) {
        countDisplay.textContent = `รายการตรวจทั้งหมด ${services.length} รายการ`;
    }

    if (!services || services.length === 0) {
        tbody.innerHTML = '<tr><td colspan="5" class="text-center text-muted py-5"><i class="bi bi-inbox fs-3 d-block mb-2 text-primary opacity-50"></i>ไม่มีข้อมูลรายการตรวจ</td></tr>';
        if (paginationEl) paginationEl.innerHTML = '';
        return;
    }

    // Pagination logic
    const totalPages = Math.ceil(services.length / window.servicesItemsPerPage) || 1;
    if (window.servicesCurrentPage > totalPages) window.servicesCurrentPage = totalPages;
    if (window.servicesCurrentPage < 1) window.servicesCurrentPage = 1;

    const startIndex = (window.servicesCurrentPage - 1) * window.servicesItemsPerPage;
    const paginatedServices = services.slice(startIndex, startIndex + window.servicesItemsPerPage);

    try {
        tbody.innerHTML = paginatedServices.map((service, idx) => {
            if (!service) return '';
            const overallIndex = startIndex + idx + 1;

            let subItems = service.sub_items;
            if (typeof subItems === 'string') {
                try { subItems = JSON.parse(subItems); } catch (e) { subItems = []; }
            }
            const isPackage = Array.isArray(subItems) && subItems.length > 0;

            let subItemsHtml = '';
            if (isPackage) {
                subItemsHtml = `
                    <div class="mt-2 pt-1 border-top border-light">
                        <div class="text-muted extra-small fw-semibold mb-1 opacity-75" style="font-size: 0.73rem;">
                            <i class="bi bi-diagram-3 me-1"></i>รายการย่อย (${subItems.length} รายการ):
                        </div>
                        <div class="d-flex flex-wrap gap-1.5">
                `;
                subItems.forEach(item => {
                    if (!item) return;
                    const itemPrice = item.price ? ` <span class="text-primary font-monospace">(${Number(item.price).toLocaleString()})</span>` : '';
                    subItemsHtml += `<span class="badge bg-light text-secondary border px-2 py-1 fw-normal text-nowrap" style="font-size: 0.76rem;"><i class="bi bi-check2 text-success me-1"></i>${item.name || ''}${itemPrice}</span>`;
                });
                subItemsHtml += `</div></div>`;
            }

            const cur = service.currency === 'THB' ? 'บาท' : (service.currency || 'LAK');
            const catName = getServiceCategory(service);

            const badgeTypeHtml = isPackage
                ? `<span class="badge bg-primary-subtle text-primary border border-primary-subtle px-2 py-0.5 rounded-pill me-2 text-nowrap" style="font-size: 0.72rem; font-weight: 500;"><i class="bi bi-box-seam me-1"></i>แพ็กเกจ</span>`
                : `<span class="badge bg-secondary-subtle text-secondary border px-2 py-0.5 rounded-pill me-2 text-nowrap" style="font-size: 0.72rem; font-weight: 500;"><i class="bi bi-card-checklist me-1"></i>รายการเดี่ยว</span>`;

            const badgeCatHtml = `<span class="badge bg-info-subtle text-info border border-info-subtle px-2 py-0.5 rounded-pill me-2 text-nowrap" style="font-size: 0.72rem; font-weight: 500;"><i class="bi bi-folder2 me-1"></i>${catName}</span>`;

            const descHtml = service.description
                ? `<span class="text-secondary" style="font-size: 0.82rem;">${service.description}</span>`
                : `<span class="text-muted opacity-50 fst-italic" style="font-size: 0.8rem;">-</span>`;

            return `
            <tr>
                <td class="ps-4 align-middle text-muted fw-semibold" style="font-size: 0.85rem;">${overallIndex}</td>
                <td class="align-middle py-3">
                    <div class="d-flex align-items-center mb-1 flex-wrap gap-1">
                        ${badgeTypeHtml}
                        ${badgeCatHtml}
                        <span class="fw-bold text-dark" style="font-size: 0.9rem;">${service.name || 'ไม่ระบุชื่อ'}</span>
                    </div>
                    ${subItemsHtml}
                </td>
                <td class="align-middle text-nowrap">
                    <span class="badge px-3 py-1.5 fw-semibold" style="background: #f0fdf4; color: #15803d; border: 1px solid #bbf7d0; border-radius: 20px; font-size: 0.82rem;">
                        <i class="bi bi-tag-fill me-1 opacity-75"></i>${Number(service.price || 0).toLocaleString()} ${cur}
                    </span>
                </td>
                <td class="align-middle"><div class="text-wrap" style="max-width: 280px;">${descHtml}</div></td>
                <td class="text-center align-middle text-nowrap">
                    <div class="d-flex gap-1 justify-content-center">
                        <button type="button" class="btn btn-sm btn-outline-secondary" onclick="openEditServiceModal('${service.id}')" title="แก้ไขรายการ"><i class="bi bi-pencil-square"></i></button>
                        <button type="button" class="btn btn-sm btn-outline-danger" onclick="deleteService('${service.id}')" title="ลบรายการ"><i class="bi bi-trash"></i></button>
                    </div>
                </td>
            </tr>
        `}).join('');
    } catch (err) {
        console.error('Error rendering services table:', err);
    }

    // Render pagination buttons
    if (paginationEl) {
        let pNextHtml = '';
        let prevDisabled = window.servicesCurrentPage === 1 ? 'disabled' : '';
        let nextDisabled = window.servicesCurrentPage === totalPages ? 'disabled' : '';

        pNextHtml += `<li class="page-item ${prevDisabled}"><a class="page-link" href="javascript:void(0);" onclick="changeServicesPage(${window.servicesCurrentPage - 1})"><i class="bi bi-chevron-left"></i></a></li>`;

        for (let i = 1; i <= totalPages; i++) {
            let active = i === window.servicesCurrentPage ? 'active' : '';
            pNextHtml += `<li class="page-item ${active}"><a class="page-link" href="javascript:void(0);" onclick="changeServicesPage(${i})">${i}</a></li>`;
        }

        pNextHtml += `<li class="page-item ${nextDisabled}"><a class="page-link" href="javascript:void(0);" onclick="changeServicesPage(${window.servicesCurrentPage + 1})"><i class="bi bi-chevron-right"></i></a></li>`;
        paginationEl.innerHTML = pNextHtml;
    }
}

function changeServicesPage(newPage) {
    window.servicesCurrentPage = newPage;
    filterServicesTable();
}
window.changeServicesPage = changeServicesPage;

function filterServicesCategory(catName, btnEl) {
    window.selectedServicesCategory = catName;
    window.servicesCurrentPage = 1;
    if (btnEl) {
        document.querySelectorAll('#servicesManagementCategoryTabs .service-mgmt-cat-tab').forEach(b => {
            b.classList.remove('btn-primary', 'active');
            b.classList.add('btn-light', 'border', 'text-secondary');
        });
        btnEl.classList.remove('btn-light', 'border', 'text-secondary');
        btnEl.classList.add('btn-primary', 'active');
    }
    filterServicesTable();
}
window.filterServicesCategory = filterServicesCategory;

function filterServicesTable() {
    const query = (document.getElementById('searchServiceInput')?.value || '').toLowerCase().trim();
    const cat = window.selectedServicesCategory || 'ALL';

    let services = window.servicesData || [];

    if (cat !== 'ALL' && cat !== 'ทั้งหมด (All)') {
        services = services.filter(s => {
            const itemCat = getServiceCategory(s);
            return isCategoryMatch(itemCat, cat);
        });
    }

    if (query) {
        services = services.filter(s =>
            (s.name || '').toLowerCase().includes(query) ||
            (getServiceCategory(s) || '').toLowerCase().includes(query) ||
            (s.description || '').toLowerCase().includes(query) ||
            (s.price || '').toString().includes(query) ||
            (s.sub_items || []).some(sub => (sub.name || '').toLowerCase().includes(query))
        );
    }
    renderServicesTable(services);
}
window.filterServicesTable = filterServicesTable;

function openAddServiceModal() {
    document.getElementById('serviceForm').reset();
    document.getElementById('serviceId').value = '';
    document.getElementById('addServiceModalTitle').innerHTML = '<i class="bi bi-plus-circle text-primary me-2"></i>เพิ่มรายการตรวจ/แพ็กเกจ';

    const catSelect = document.getElementById('serviceCategory');
    if (catSelect) catSelect.value = 'เลือดวิทยา (HEMATOLOGY)';

    const tbody = document.getElementById('serviceSubItemsBody');
    if (tbody) tbody.innerHTML = '';

    addServiceSubItemRow();
    addServiceSubItemRow();

    updatePackagePriceDisplay();
    bootstrap.Modal.getOrCreateInstance(document.getElementById('addServiceModal')).show();
}

function openEditServiceModal(id) {
    const service = window.servicesData.find(s => s.id === id);
    if (!service) return;

    document.getElementById('serviceId').value = service.id;
    document.getElementById('serviceName').value = service.name || '';
    document.getElementById('servicePrice').value = service.price || 0;
    document.getElementById('serviceDescription').value = service.description || '';

    const curSelect = document.getElementById('serviceCurrency');
    if (curSelect) curSelect.value = service.currency || 'LAK';

    const catSelect = document.getElementById('serviceCategory');
    if (catSelect) catSelect.value = service.category || 'เลือดวิทยา (HEMATOLOGY)';

    const tbody = document.getElementById('serviceSubItemsBody');
    if (tbody) tbody.innerHTML = '';

    // 🚀 ระบบช่วยกู้คืนข้อมูล (Robust Parsing)
    let subItems = [];
    try {
        if (Array.isArray(service.sub_items)) {
            subItems = service.sub_items;
        } else if (typeof service.sub_items === 'string') {
            let parsed = JSON.parse(service.sub_items);
            // ถ้าแปลงแล้วยังเป็น String ซ้อนอีกชั้น ให้แปลงอีกรอบ
            if (typeof parsed === 'string') parsed = JSON.parse(parsed);
            if (Array.isArray(parsed)) subItems = parsed;
        }
    } catch (e) {
        console.warn("ไม่สามารถอ่านข้อมูลรายการย่อยได้:", e);
    }

    // นำข้อมูลที่กู้คืนได้ มาแสดงในตาราง
    if (subItems.length > 0) {
        subItems.forEach(item => {
            // เช็คว่ามีฟังก์ชันนี้ไหม ถ้าไม่มีให้สร้าง HTML ตรงๆ ป้องกัน Error
            if (typeof addServiceSubItemRow === 'function') {
                addServiceSubItemRow(item.name, item.price);
            }
        });
    } else {
        if (typeof addServiceSubItemRow === 'function') {
            addServiceSubItemRow();
            addServiceSubItemRow();
        }
    }

    if (typeof updatePackagePriceDisplay === 'function') updatePackagePriceDisplay();

    const title = document.getElementById('addServiceModalTitle');
    if (title) title.innerHTML = '<i class="bi bi-pencil-square text-warning me-2"></i>แก้ไขรายการตรวจ/แพ็กเกจ';

    bootstrap.Modal.getOrCreateInstance(document.getElementById('addServiceModal')).show();
}

function addServiceSubItemRow(name = '', price = '') {
    const tbody = document.getElementById('serviceSubItemsBody');
    if (!tbody) return;
    const tr = document.createElement('tr');
    tr.innerHTML = `
        <td class="text-center row-number text-muted"></td>
        <td>
            <input type="text" class="form-control form-control-sm custom-input subitem-name" placeholder="ชื่อรายการตรวจย่อย..." value="${name.replace(/"/g, '&quot;')}" oninput="updatePackagePriceDisplay()">
        </td>
        <td>
            <input type="number" class="form-control form-control-sm custom-input subitem-price text-end" placeholder="0" value="${price}" oninput="updatePackagePriceDisplay()">
        </td>
        <td class="text-center">
            <button type="button" class="btn btn-sm btn-outline-danger border-0" onclick="this.closest('tr').remove(); updateServiceSubItemNumbers(); updatePackagePriceDisplay();">
                <i class="bi bi-x-lg"></i>
            </button>
        </td>
    `;
    tbody.appendChild(tr);
    updateServiceSubItemNumbers();
    updatePackagePriceDisplay();
}

function updateServiceSubItemNumbers() {
    const rows = document.querySelectorAll('#serviceSubItemsBody tr');
    rows.forEach((row, index) => {
        const numCell = row.querySelector('.row-number');
        if (numCell) numCell.textContent = index + 1;
    });
}

function updatePackagePriceDisplay() {
    const priceInput = document.getElementById('servicePrice');
    const display = document.getElementById('packageTotalPriceDisplay');
    const curSelect = document.getElementById('serviceCurrency');
    const cur = curSelect ? (curSelect.value === 'THB' ? 'บาท' : 'LAK') : 'LAK';

    let subItemsTotal = 0;
    let hasSubItemPrices = false;
    document.querySelectorAll('#serviceSubItemsBody .subitem-price').forEach(input => {
        const val = parseFloat(input.value);
        if (!isNaN(val) && val > 0) {
            subItemsTotal += val;
            hasSubItemPrices = true;
        }
    });

    if (display) {
        if (hasSubItemPrices) {
            display.innerHTML = `
                <span>${subItemsTotal.toLocaleString()} ${cur}</span>
                <button type="button" class="btn btn-sm btn-outline-primary ms-2 py-0 px-2 rounded-pill" style="font-size: 0.75rem;" onclick="applySubItemsTotalToPrice(${subItemsTotal})" title="ใช้ราคารวมย่อยนี้เป็นราคาแพ็กเกจหลัก">
                    <i class="bi bi-arrow-up-circle me-1"></i>ใช้ราคานี้เป็นราคาหลัก
                </button>
            `;
        } else {
            const val = parseFloat(priceInput?.value) || 0;
            display.textContent = val.toLocaleString() + ' ' + cur;
        }
    }
}

function applySubItemsTotalToPrice(total) {
    const priceInput = document.getElementById('servicePrice');
    if (priceInput) {
        priceInput.value = total;
        updatePackagePriceDisplay();
    }
}
window.applySubItemsTotalToPrice = applySubItemsTotalToPrice;

window.openAddServiceModal = openAddServiceModal;
window.openEditServiceModal = openEditServiceModal;
window.addServiceSubItemRow = addServiceSubItemRow;
window.updatePackagePriceDisplay = updatePackagePriceDisplay;

async function saveService() {
    const editId = document.getElementById('serviceId').value;
    const name = document.getElementById('serviceName').value.trim();
    const price = parseFloat(document.getElementById('servicePrice').value) || 0;
    const currency = document.getElementById('serviceCurrency').value;
    const category = document.getElementById('serviceCategory').value;
    const description = document.getElementById('serviceDescription').value.trim();

    if (!name) {
        Swal.fire('แจ้งเตือน', 'กรุณากรอกชื่อแพ็กเกจ/รายการตรวจ', 'warning');
        return;
    }

    const subItems = [];
    const rows = document.querySelectorAll('#serviceSubItemsBody tr');

    rows.forEach(row => {
        const inputs = row.querySelectorAll('input');
        if (inputs.length >= 2) {
            const subName = inputs[0].value.trim();
            const subPrice = parseFloat(inputs[1].value) || 0;
            if (subName !== '') {
                subItems.push({ name: subName, price: subPrice });
            }
        }
    });

    Swal.fire({ title: 'กำลังบันทึกข้อมูล...', allowOutsideClick: false, didOpen: () => Swal.showLoading() });

    const payload = {
        name: name,
        price: price,
        currency: currency,
        category: category,
        description: description,
        // 🚀 แก้ไข: ส่งข้อมูล Array ตรงๆ เข้าไปเลย ไม่ต้องใส่ JSON.stringify แล้วครับ
        sub_items: subItems
    };

    let error = null;

    try {
        if (editId) {
            const res = await _supabase.from('services').update(payload).eq('id', editId);
            error = res.error;
        } else {
            payload.id = 'SRV-' + Math.floor(100000 + Math.random() * 900000);
            const res = await _supabase.from('services').insert([payload]);
            error = res.error;
        }

        if (error) {
            Swal.fire('ข้อผิดพลาด', error.message, 'error');
        } else {
            Swal.fire('สำเร็จ', 'บันทึกข้อมูลรายการตรวจเรียบร้อยแล้ว', 'success');
            bootstrap.Modal.getOrCreateInstance(document.getElementById('addServiceModal')).hide();
            if (typeof loadServicesData === 'function') loadServicesData();
        }
    } catch (err) {
        console.error("Save Service Error:", err);
        Swal.fire('ข้อผิดพลาด', 'ไม่สามารถติดต่อฐานข้อมูลได้', 'error');
    }
}
window.saveService = saveService;

async function deleteService(id) {
    const result = await Swal.fire({
        title: 'ยืนยันการลบ?',
        text: "คุณต้องการลบรายการตรวจนี้ใช่หรือไม่?",
        icon: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#d33',
        cancelButtonColor: '#6e7d88',
        confirmButtonText: 'ลบข้อมูล',
        cancelButtonText: 'ยกเลิก'
    });

    if (result.isConfirmed) {
        window.servicesData = (window.servicesData || []).filter(s => s.id !== id);
        saveServicesLocalData();
        renderServicesTable();

        Swal.fire('ลบแล้ว!', 'ข้อมูลถูกลบเรียบร้อย', 'success');

        (async () => {
            try {
                await _supabase.from('services').delete().eq('id', id);
            } catch (e) {
                console.warn('Delete service Supabase warning:', e);
            }
        })();
    }
}
window.deleteService = deleteService;

function exportServicesToExcel() {
    let csv = "\uFEFF";
    csv += "ลำดับ,รหัส,ชื่อรายการตรวจ/แพ็กเกจ,หมวดหมู่,ราคา,หน่วย,คำอธิบาย\n";
    const services = window.servicesData || [];
    services.forEach((s, idx) => {
        const cat = getServiceCategory(s);
        const name = (s.name || '').replace(/,/g, ' ');
        const desc = (s.description || '').replace(/,/g, ' ');
        csv += `${idx + 1},${s.id},${name},${cat},${s.price || 0},${s.currency || 'LAK'},${desc}\n`;
    });
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `services_list_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
}
window.exportServicesToExcel = exportServicesToExcel;

async function saveReferrer() {
    const editId = document.getElementById('referrerEditId').value;
    const customCode = (document.getElementById('refCode')?.value || '').trim();
    const name = document.getElementById('refFullName').value.trim();
    const phone = document.getElementById('refPhone').value.trim();
    const bankName = document.getElementById('refBankName').value;
    const bankAccount = document.getElementById('refBankAccount').value.trim();
    const notes = document.getElementById('refNotes').value.trim();

    if (!name || !phone) {
        Swal.fire('กรุณากรอกข้อมูล', 'กรุณากรอกชื่อ-นามสกุล และเบอร์โทรศัพท์ผู้แนะนำ', 'warning');
        return;
    }

    if (editId) {
        const item = window.referrersData.find(r => r.id === editId);
        if (item) {
            item.code = customCode || item.code;
            item.name = name;
            item.phone = phone;
            item.bank_name = bankName;
            item.bank_account = bankAccount;
            item.notes = notes;
        }
    } else {
        const newCode = customCode || ('REF-' + (100 + window.referrersData.length + 1));
        const newItem = {
            id: generateId('REF'),
            code: newCode,
            name: name,
            phone: phone,
            bank_name: bankName,
            bank_account: bankAccount,
            notes: notes,
            created_at: new Date().toISOString()
        };
        window.referrersData.push(newItem);

        try {
            await _supabase.from('referrers').insert([newItem]);
        } catch (e) {
            console.log('Supabase referrers insert fallback');
        }
    }

    saveReferralLocalData();
    const modalEl = document.getElementById('addReferrerModal');
    if (modalEl) bootstrap.Modal.getOrCreateInstance(modalEl).hide();

    document.getElementById('referrerForm').reset();
    document.getElementById('referrerEditId').value = '';
    if (document.getElementById('refCode')) document.getElementById('refCode').value = '';

    Swal.fire('สำเร็จ', 'บันทึกข้อมูลสมาชิกผู้แนะนำเรียบร้อยแล้ว', 'success');
    loadReferralData();
}

function editReferrer(id) {
    const item = window.referrersData.find(r => r.id === id);
    if (!item) return;

    document.getElementById('referrerEditId').value = item.id;
    if (document.getElementById('refCode')) document.getElementById('refCode').value = item.code || item.id;
    document.getElementById('refFullName').value = item.name;
    document.getElementById('refPhone').value = item.phone;
    document.getElementById('refBankName').value = item.bank_name || 'กสิกรไทย (KBANK)';
    document.getElementById('refBankAccount').value = item.bank_account || '';
    document.getElementById('refNotes').value = item.notes || '';

    const titleEl = document.getElementById('addReferrerModalTitle');
    if (titleEl) titleEl.innerHTML = '<i class="ph ph-pencil-simple text-primary me-2"></i>แก้ไขข้อมูลผู้แนะนำ';

    bootstrap.Modal.getOrCreateInstance(document.getElementById('addReferrerModal')).show();
}

async function deleteReferrer(id) {
    const item = window.referrersData.find(r => r.id === id);
    if (!item) return;

    const res = await Swal.fire({
        title: 'ยืนยันการลบ?',
        text: `ต้องการลบคุณ ${item.name} ออกจากระบบผู้แนะนำใช่หรือไม่?`,
        icon: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#ef4444',
        confirmButtonText: 'ลบข้อมูล',
        cancelButtonText: 'ยกเลิก'
    });

    if (res.isConfirmed) {
        window.referrersData = window.referrersData.filter(r => r.id !== id);
        saveReferralLocalData();
        loadReferralData();
        Swal.fire('ลบข้อมูลแล้ว', 'ลบสมาชิกผู้แนะนำเรียบร้อย', 'success');
    }
}

function toggleTargetGoalDisplay() {
    const sw = document.getElementById('targetEnableSwitch');
    const container = document.getElementById('targetGoalConfigContainer');
    if (sw && container) {
        container.style.display = sw.checked ? 'block' : 'none';
    }

    const goalInput = document.getElementById('targetGoalCount');
    const helpDisplay = document.getElementById('targetHelpGoalDisplay');
    if (goalInput && helpDisplay) {
        helpDisplay.innerText = goalInput.value || '20';
    }
}

function toggleCommTypeDisplay() {
    const pctRadio = document.getElementById('commTypePercent');
    const currSelect = document.getElementById('commCurrencySelect');
    if (currSelect) {
        window.commissionSettings.currency = currSelect.value;
    }

    if (!pctRadio) return;
    const isPercent = pctRadio.checked;
    const label = document.getElementById('commRateLabel');
    const addon = document.getElementById('commUnitAddon');

    const unitName = getCurrencyUnitName();

    if (isPercent) {
        if (label) label.innerText = 'อัตราเงินปันผล (%) จากยอดค่ารักษา (ปกติ)';
        if (addon) addon.innerText = '%';
    } else {
        if (label) label.innerText = `จำนวนเงินปันผลต่อผู้ป่วย 1 คน (${unitName}) (ปกติ)`;
        if (addon) addon.innerText = unitName;
    }

    const targetBonusLabel = document.getElementById('targetBonusLabel');
    const targetBonusAddon = document.getElementById('targetBonusAddon');
    if (targetBonusLabel) {
        targetBonusLabel.innerText = isPercent ? 'อัตราโบนัสพิเศษเมื่อถึงเป้าหมาย (%)' : `จำนวนเงินโบนัสพิเศษต่อคน (${unitName})`;
    }
    if (targetBonusAddon) {
        targetBonusAddon.innerText = isPercent ? '%' : unitName;
    }

    toggleTargetGoalDisplay();
}

function initCommissionToggles() {
    const overallSwitch = document.getElementById('overallModeSwitch');
    const itemSwitch = document.getElementById('itemModeSwitch');

    if (overallSwitch) {
        // ดึงค่าจาก LocalStorage (ถ้าไม่มีค่า จะให้ค่าเริ่มต้นเป็น true/เปิด)
        const savedOverall = localStorage.getItem('clinic_comm_overall_enabled');
        if (savedOverall !== null) {
            overallSwitch.checked = (savedOverall === 'true' || savedOverall === true);
        }
        const label = document.getElementById('overallModeSwitchLabel');
        if (label) label.textContent = overallSwitch.checked ? 'เปิดใช้งาน' : 'ปิดใช้งาน';
    }

    if (itemSwitch) {
        // ดึงค่าจาก LocalStorage (ถ้าไม่มีค่า จะให้ค่าเริ่มต้นเป็น false/ปิด)
        const savedItem = localStorage.getItem('clinic_comm_item_enabled');
        if (savedItem !== null) {
            itemSwitch.checked = (savedItem === 'true' || savedItem === true);
        }
        const label = document.getElementById('itemModeSwitchLabel');
        if (label) label.textContent = itemSwitch.checked ? 'เปิดใช้งาน' : 'ปิดใช้งาน';
    }
}
window.initCommissionToggles = initCommissionToggles;

// 🌟 ฟังก์ชันโหลดสถานะปุ่มจาก Database มาแสดงที่หน้าเว็บ
async function loadCommissionToggleStates() {
    if (typeof _supabase === 'undefined') return;

    try {
        const { data, error } = await _supabase
            .from('commission_settings')
            .select('id, value')
            .in('id', ['toggle_overall_mode', 'toggle_item_mode']);

        if (!error && data) {
            data.forEach(setting => {
                if (setting.id === 'toggle_overall_mode') {
                    const isChecked = (setting.value === 1 || setting.value === '1' || setting.value === 1.00);
                    const sw = document.getElementById('overallModeSwitch');
                    const lbl = document.getElementById('overallModeSwitchLabel');
                    if (sw) sw.checked = isChecked;
                    if (lbl) lbl.textContent = isChecked ? 'เปิดใช้งาน' : 'ปิดใช้งาน';

                    localStorage.setItem('clinic_comm_overall_enabled', isChecked);
                    localStorage.setItem('hr_overall_commission_enabled', isChecked ? 'true' : 'false');
                    if (window.commissionSettings) window.commissionSettings.overall_enabled = isChecked;

                    const form = document.getElementById('commissionSettingsForm');
                    if (form) {
                        const inputs = form.querySelectorAll('input:not(#overallModeSwitch), select, button[type="submit"]');
                        inputs.forEach(el => { el.disabled = !isChecked; });
                        form.style.opacity = isChecked ? '1' : '0.55';
                        form.style.pointerEvents = isChecked ? 'auto' : 'none';
                    }
                }

                if (setting.id === 'toggle_item_mode') {
                    const isChecked = (setting.value === 1 || setting.value === '1' || setting.value === 1.00);
                    const sw = document.getElementById('itemModeSwitch');
                    const lbl = document.getElementById('itemModeSwitchLabel');
                    if (sw) sw.checked = isChecked;
                    if (lbl) lbl.textContent = isChecked ? 'เปิดใช้งาน' : 'ปิดใช้งาน';

                    localStorage.setItem('clinic_comm_item_enabled', isChecked);
                    localStorage.setItem('hr_item_commission_enabled', isChecked ? 'true' : 'false');

                    const addBtn = document.querySelector('button[onclick="openAddItemDividendModal()"]');
                    const saveBtn = document.querySelector('button[onclick="saveItemCommissionSettings()"]');
                    if (addBtn) { addBtn.disabled = !isChecked; addBtn.style.opacity = isChecked ? '1' : '0.55'; }
                    if (saveBtn) { saveBtn.disabled = !isChecked; saveBtn.style.opacity = isChecked ? '1' : '0.55'; }
                    const itemInputs = document.querySelectorAll('.item-comm-input');
                    itemInputs.forEach(inp => inp.disabled = !isChecked);
                    const deleteBtns = document.querySelectorAll('#itemDividendBody button');
                    deleteBtns.forEach(btn => btn.disabled = !isChecked);
                    const tableWrapper = document.querySelector('#itemDividendTable')?.parentElement;
                    if (tableWrapper) tableWrapper.style.opacity = isChecked ? '1' : '0.55';
                }
            });
        }
    } catch (e) {
        console.error('Error loading toggle states from database:', e);
    }
}
window.loadCommissionToggleStates = loadCommissionToggleStates;

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        initCommissionToggles();
        loadCommissionToggleStates();
        if (typeof loadItemCommissionSettings === 'function') {
            loadItemCommissionSettings();
        }
    });
} else {
    initCommissionToggles();
    loadCommissionToggleStates();
    if (typeof loadItemCommissionSettings === 'function') {
        loadItemCommissionSettings();
    }
}

// ฟังก์ชันเมื่อกดปุ่ม เปิด/ปิด "แบบภาพรวม"
async function toggleOverallModeDisplay() {
    const overallSwitch = document.getElementById('overallModeSwitch');
    if (!overallSwitch) return;
    const isChecked = overallSwitch.checked;

    // 1. บันทึกสถานะลงใน LocalStorage
    localStorage.setItem('clinic_comm_overall_enabled', isChecked);
    localStorage.setItem('hr_overall_commission_enabled', isChecked ? 'true' : 'false');
    if (window.commissionSettings) {
        window.commissionSettings.overall_enabled = isChecked;
        localStorage.setItem('clinic_commission_settings', JSON.stringify(window.commissionSettings));
    }

    // เปลี่ยนข้อความ Label
    const label = document.getElementById('overallModeSwitchLabel');
    if (label) label.textContent = isChecked ? 'เปิดใช้งาน' : 'ปิดใช้งาน';

    // 🌟 บันทึกสถานะลง Supabase Database ทันที (ตาราง commission_settings)
    if (typeof _supabase !== 'undefined') {
        try {
            await _supabase.from('commission_settings').upsert([{
                id: 'toggle_overall_mode',
                type: 'system_toggle',
                value: isChecked ? 1 : 0,
                auto_trigger: isChecked,
                updated_at: new Date().toISOString()
            }], { onConflict: 'id' });

            await _supabase.from('system_settings').upsert([
                { key: 'hr_overall_commission_enabled', value: isChecked ? 'true' : 'false', updated_at: new Date().toISOString() }
            ], { onConflict: 'key' });
        } catch (err) {
            console.warn('Error saving overall mode state:', err);
        }
    }

    // จัดการเปิด/ปิด Control ทั้งหมดใน Card 1
    const form = document.getElementById('commissionSettingsForm');
    if (form) {
        const inputs = form.querySelectorAll('input:not(#overallModeSwitch), select, button[type="submit"]');
        inputs.forEach(el => {
            el.disabled = !isChecked;
        });
        form.style.opacity = isChecked ? '1' : '0.55';
        form.style.pointerEvents = isChecked ? 'auto' : 'none';
    }
}
window.toggleOverallModeDisplay = toggleOverallModeDisplay;

async function saveCommissionSettings() {
    const typeRadio = document.querySelector('input[name="commType"]:checked');
    const commType = typeRadio ? typeRadio.value : 'fixed';
    const currency = document.getElementById('commCurrencySelect').value;

    // แก้ไข: ดึงค่ามาเป็นข้อความ ลบลูกน้ำออก แล้วค่อยแปลงเป็นตัวเลข
    const rawCommValue = document.getElementById('commValueInput').value;
    const commValue = parseFloat(rawCommValue.replace(/,/g, '')) || 0;

    // สำหรับ Target Bonus เผื่อมีการพิมพ์ลูกน้ำด้วย ก็ใส่ดักไว้เช่นกันครับ
    const rawTargetBonus = document.getElementById('targetBonusValue').value;
    const targetBonus = parseFloat(rawTargetBonus.replace(/,/g, '')) || 0;

    const targetEnabled = document.getElementById('targetEnableSwitch').checked;
    const targetGoal = parseInt(document.getElementById('targetGoalCount').value) || 0;
    const autoTrigger = document.getElementById('autoTriggerComm').checked;

    const overallSwitch = document.getElementById('overallModeSwitch');
    const overallEnabled = overallSwitch ? overallSwitch.checked : true;

    window.commissionSettings = {
        overall_enabled: overallEnabled,
        type: commType,
        value: commValue,
        currency: currency,
        target_enabled: targetEnabled,
        target_goal: targetGoal,
        target_bonus_value: targetBonus,
        auto_trigger: autoTrigger
    };

    // บันทึกลง Local Storage
    localStorage.setItem('hr_overall_commission_enabled', overallEnabled ? 'true' : 'false');
    localStorage.setItem('clinic_commission_settings', JSON.stringify(window.commissionSettings));

    // บันทึกลง Supabase Database (ตาราง commission_settings และ system_settings)
    try {
        if (typeof _supabase !== 'undefined') {
            await _supabase.from('commission_settings').upsert([{
                id: 'default',
                type: commType,
                value: commValue,
                currency: currency,
                auto_trigger: autoTrigger,
                target_enabled: targetEnabled,
                target_goal: targetGoal,
                target_bonus_value: targetBonus,
                updated_at: new Date().toISOString()
            }], { onConflict: 'id' });

            await _supabase.from('system_settings').upsert([
                { key: 'clinic_commission_settings', value: JSON.stringify(window.commissionSettings), updated_at: new Date().toISOString() },
                { key: 'hr_overall_commission_enabled', value: overallEnabled ? 'true' : 'false', updated_at: new Date().toISOString() }
            ], { onConflict: 'key' });
        }
    } catch (e) {
        console.warn('Save commission settings to DB error:', e);
    }

    Swal.fire({
        icon: 'success',
        title: 'บันทึกสำเร็จ',
        text: 'บันทึกการตั้งค่ารูปแบบการจ่ายปันผลเรียบร้อยแล้ว',
        confirmButtonColor: '#0b3c73'
    });
}
window.saveCommissionSettings = saveCommissionSettings;

// 🌟 ฟังก์ชันโหลดการตั้งค่าปันผลแบบรายรายการ
async function loadItemCommissionSettings() {
    const tbody = document.getElementById('itemDividendBody');
    if (!tbody) return;

    const renderRows = (settingsList, servicesList) => {
        if (!settingsList || settingsList.length === 0) {
            tbody.innerHTML = `
                <tr>
                    <td colspan="5" class="text-center text-muted py-5">
                        <i class="bi bi-plus-circle fs-2 d-block mb-2 text-primary opacity-50"></i>
                        ยังไม่มีรายการปันผลพิเศษ<br>
                        <small class="text-muted">กดปุ่ม "+ เพิ่มรายการปันผล" ด้านบน เพื่อเลือกรายการตรวจที่ต้องการคิดปันผลเพิ่ม</small>
                    </td>
                </tr>`;
            return;
        }

        const isItemActive = localStorage.getItem('clinic_comm_item_enabled') !== null
            ? (localStorage.getItem('clinic_comm_item_enabled') === 'true' || localStorage.getItem('clinic_comm_item_enabled') === true)
            : (localStorage.getItem('hr_item_commission_enabled') === 'true');

        tbody.innerHTML = settingsList.map((item, index) => {
            const rawId = item.id || '';
            const serviceId = rawId.replace(/^item_/, '');

            // ค้นหา Service จากหลายคีย์เพื่อความแม่นยำ 100%
            const srv = (servicesList || []).find(s =>
                String(s.id || '').toLowerCase() === String(serviceId).toLowerCase() ||
                String(s.service_id || '').toLowerCase() === String(serviceId).toLowerCase() ||
                String(s.name || '').toLowerCase() === String(serviceId).toLowerCase()
            ) || { name: item.name || `รายการตรวจ (${serviceId})`, category: item.category || 'บริการ', price: item.price || 0 };

            const cur = item.currency || srv.currency || 'LAK';
            const priceText = Number(srv.price || 0).toLocaleString() + ' ' + (cur === 'THB' ? 'บาท' : cur);
            const divValue = Number(item.value !== undefined ? item.value : 0);

            return `
                <tr>
                    <td class="text-center align-middle">${index + 1}</td>
                    <td class="align-middle">
                        <div class="fw-bold text-dark">${srv.name}</div>
                        <div class="text-muted small"><i class="bi bi-folder2-open me-1"></i>${srv.category || '-'}</div>
                    </td>
                    <td class="text-end align-middle">
                        <span class="badge bg-light text-success border px-2 py-1">${priceText}</span>
                    </td>
                    <td class="text-center align-middle">
                        <div class="input-group input-group-sm" style="width: 140px; margin: 0 auto;">
                            <!-- ใส่ Class 'item-dividend-input' และ 'item-comm-input' ไว้ให้ฟังก์ชัน Save กวาดข้อมูลไปบันทึก -->
                            <input type="number" class="form-control text-end item-dividend-input item-comm-input fw-bold text-primary" 
                                   data-id="${rawId}" value="${divValue}" ${isItemActive ? '' : 'disabled'}>
                            <span class="input-group-text">${cur}</span>
                        </div>
                    </td>
                    <td class="text-center align-middle">
                        <button type="button" class="btn btn-sm btn-outline-danger py-1 px-2" onclick="deleteItemCommission('${rawId}')" title="ลบรายการ" ${isItemActive ? '' : 'disabled'}>
                            <i class="bi bi-trash"></i>
                        </button>
                    </td>
                </tr>
            `;
        }).join('');
    };

    // 1. เรนเดอร์ทันทีจาก LocalStorage (Instant Cache) ไม่ให้หน้าจอกะพริบหรือหายตอนรีเฟรช
    let localServices = window.allServicesData || JSON.parse(localStorage.getItem('clinic_services_packages') || 'null') || window.servicesData || [];
    let localItemSettings = JSON.parse(localStorage.getItem('hr_item_commission_settings') || '{}');
    let localSettingsList = Object.keys(localItemSettings).map(sId => ({
        id: sId.startsWith('item_') ? sId : 'item_' + sId,
        type: 'item',
        value: localItemSettings[sId],
        currency: 'LAK'
    }));

    if (localSettingsList.length > 0) {
        renderRows(localSettingsList, localServices);
    }

    try {
        // 2. ดึงข้อมูลแพ็กเกจและรายการตรวจจาก Supabase
        let services = localServices;
        if (typeof _supabase !== 'undefined') {
            const { data: srvData } = await _supabase.from('services').select('*');
            if (srvData && srvData.length > 0) {
                services = srvData;
                window.allServicesData = srvData;
                if (typeof window.safeSetLocalStorage === 'function') {
                    window.safeSetLocalStorage('clinic_services_packages', srvData);
                } else {
                    try { localStorage.setItem('clinic_services_packages', JSON.stringify(srvData)); } catch (e) { }
                }
            }
        }

        // 3. ดึงข้อมูลรายการปันผลที่บันทึกไว้ใน commission_settings
        let dbSettings = [];
        if (typeof _supabase !== 'undefined') {
            const { data: commData, error } = await _supabase
                .from('commission_settings')
                .select('*');

            if (!error && commData && commData.length > 0) {
                dbSettings = commData.filter(r => r.type === 'item' || (r.id && r.id.startsWith('item_') && r.id !== 'item_config'));
            }
        }

        if (dbSettings.length > 0) {
            const cachedObj = {};
            dbSettings.forEach(item => {
                const sId = item.id.replace(/^item_/, '');
                cachedObj[sId] = parseFloat(item.value) || 0;
            });
            localStorage.setItem('hr_item_commission_settings', JSON.stringify(cachedObj));
            renderRows(dbSettings, services);
        } else if (localSettingsList.length > 0) {
            renderRows(localSettingsList, services);
        } else {
            renderRows([], services);
        }
    } catch (err) {
        console.error('Load Item Commission Error:', err);
        if (localSettingsList.length === 0) {
            tbody.innerHTML = '<tr><td colspan="5" class="text-center text-danger py-4">เกิดข้อผิดพลาดในการดึงข้อมูลจากฐานข้อมูล</td></tr>';
        }
    }
}
window.loadItemCommissionSettings = loadItemCommissionSettings;
window.renderItemCommissionSettingsTable = loadItemCommissionSettings;

async function deleteItemCommission(itemId) {
    const serviceId = itemId.replace(/^item_/, '');
    if (typeof removeItemCommissionSetting === 'function') {
        await removeItemCommissionSetting(serviceId);
    } else {
        const itemSettings = JSON.parse(localStorage.getItem('hr_item_commission_settings') || '{}');
        delete itemSettings[serviceId];
        localStorage.setItem('hr_item_commission_settings', JSON.stringify(itemSettings));
        if (typeof _supabase !== 'undefined') {
            await _supabase.from('commission_settings').delete().eq('id', itemId);
        }
    }
    await loadItemCommissionSettings();
}
window.deleteItemCommission = deleteItemCommission;

async function openAddItemDividendModal() {
    // ดึงข้อมูลรายการตรวจจาก Supabase (allServicesData) เสมอเพื่อให้ข้อมูลสดและครบถ้วน
    if (!window.allServicesData || window.allServicesData.length === 0) {
        if (typeof loadServicesData === 'function') {
            await loadServicesData();
        }
    }
    const services = window.allServicesData || window.servicesData || [];
    if (services.length === 0) {
        Swal.fire('แจ้งเตือน', 'ยังไม่มีรายการตรวจ/บริการในระบบ กรุณาเพิ่มรายการตรวจในเมนู "ตั้งค่ารายการตรวจ" ก่อนครับ', 'warning');
        return;
    }

    const itemSettings = JSON.parse(localStorage.getItem('hr_item_commission_settings') || '{}');
    const addedIds = Object.keys(itemSettings);
    const available = services.filter(s => !addedIds.includes(String(s.id)));

    if (available.length === 0) {
        Swal.fire('แจ้งเตือน', 'คุณได้เพิ่มรายการตรวจที่มีในระบบเข้ามาในตารางปันผลครบทั้งหมดแล้วครับ', 'info');
        return;
    }

    const optionsHtml = available.map(s => {
        const cur = s.currency === 'THB' ? 'บาท' : (s.currency || 'LAK');
        return `<option value="${s.id}">${s.name} (ราคา: ${Number(s.price || 0).toLocaleString()} ${cur})</option>`;
    }).join('');

    const { value: formValues } = await Swal.fire({
        title: '<h5 class="fw-bold mb-0 text-primary"><i class="bi bi-plus-circle me-2"></i>เพิ่มรายการปันผลพิเศษ</h5>',
        html: `
            <div class="text-start p-2">
                <div class="mb-3">
                    <label class="form-label fw-bold small text-secondary">เลือกรายการตรวจ / บริการ</label>
                    <select id="swalSelectService" class="form-select custom-input py-2">
                        ${optionsHtml}
                    </select>
                </div>
                <div class="mb-2">
                    <label class="form-label fw-bold small text-secondary">จำนวนเงินปันผล (LAK / THB)</label>
                    <input type="text" id="newItemAmount" class="form-control" placeholder="0" oninput="formatNumberInput(this)">
                </div>
            </div>
        `,
        focusConfirm: false,
        showCancelButton: true,
        confirmButtonText: '<i class="bi bi-plus-lg me-1"></i> เพิ่มรายการ',
        cancelButtonText: 'ยกเลิก',
        confirmButtonColor: '#003f88',
        preConfirm: () => {
            const sId = document.getElementById('swalSelectService').value;
            const val = parseFloat(document.getElementById('newItemAmount').value.replace(/,/g, '')) || 0;
            if (isNaN(val) || val < 0) {
                Swal.showValidationMessage('กรุณากรอกยอดเงินปันผลที่ถูกต้อง (ตัวเลขมากกว่าหรือเท่ากับ 0)');
                return false;
            }
            return { sId, val };
        }
    });

    if (formValues) {
        itemSettings[formValues.sId] = formValues.val;
        localStorage.setItem('hr_item_commission_settings', JSON.stringify(itemSettings));
        localStorage.setItem('hr_item_commission_enabled', 'true');
        const itemSw = document.getElementById('itemModeSwitch');
        if (itemSw) itemSw.checked = true;
        toggleItemModeDisplay(true);

        // บันทึกลง Supabase Database ตาราง commission_settings
        try {
            if (typeof _supabase !== 'undefined') {
                await _supabase.from('commission_settings').upsert([
                    {
                        id: 'item_' + formValues.sId,
                        type: 'item',
                        value: formValues.val,
                        currency: 'LAK',
                        auto_trigger: true,
                        target_enabled: false,
                        target_goal: 0,
                        target_bonus_value: 0,
                        updated_at: new Date().toISOString()
                    },
                    {
                        id: 'item_config',
                        type: 'item_mode',
                        value: 0,
                        currency: 'LAK',
                        auto_trigger: true,
                        target_enabled: false,
                        target_goal: 0,
                        target_bonus_value: 0,
                        updated_at: new Date().toISOString()
                    }
                ], { onConflict: 'id' });

                // บันทึก backup ลง system_settings
                await _supabase.from('system_settings').upsert([
                    { key: 'hr_item_commission_settings', value: JSON.stringify(itemSettings), updated_at: new Date().toISOString() },
                    { key: 'hr_item_commission_enabled', value: 'true', updated_at: new Date().toISOString() }
                ], { onConflict: 'key' });
            }
        } catch (e) {
            console.warn('Save added item commission to DB error:', e);
        }

        renderItemCommissionSettingsTable();
        Swal.fire('สำเร็จ', 'เพิ่มรายการปันผลเรียบร้อยแล้ว', 'success');
    }
}
window.openAddItemDividendModal = openAddItemDividendModal;

async function removeItemCommissionSetting(serviceId) {
    const itemSettings = JSON.parse(localStorage.getItem('hr_item_commission_settings') || '{}');
    if (itemSettings[serviceId] !== undefined) {
        delete itemSettings[serviceId];
        localStorage.setItem('hr_item_commission_settings', JSON.stringify(itemSettings));

        // ลบออกจาก Supabase Database ตาราง commission_settings
        try {
            if (typeof _supabase !== 'undefined') {
                await _supabase.from('commission_settings').delete().eq('id', 'item_' + serviceId);

                // อัปเดต backup ลง system_settings
                await _supabase.from('system_settings').upsert([
                    { key: 'hr_item_commission_settings', value: JSON.stringify(itemSettings), updated_at: new Date().toISOString() }
                ], { onConflict: 'key' });
            }
        } catch (e) {
            console.warn('Remove item commission from DB error:', e);
        }

        renderItemCommissionSettingsTable();
    }
}
window.removeItemCommissionSetting = removeItemCommissionSetting;

// ฟังก์ชันเมื่อกดปุ่ม เปิด/ปิด "แบบรายรายการ"
async function toggleItemModeDisplay() {
    const itemSwitch = document.getElementById('itemModeSwitch');
    if (!itemSwitch) return;
    const isChecked = itemSwitch.checked;

    // 1. บันทึกสถานะลงใน LocalStorage
    localStorage.setItem('clinic_comm_item_enabled', isChecked);
    localStorage.setItem('hr_item_commission_enabled', isChecked ? 'true' : 'false');

    // เปลี่ยนข้อความ Label
    const label = document.getElementById('itemModeSwitchLabel');
    if (label) label.textContent = isChecked ? 'เปิดใช้งาน' : 'ปิดใช้งาน';

    // 🌟 บันทึกสถานะลง Supabase Database ทันที (ตาราง commission_settings)
    if (typeof _supabase !== 'undefined') {
        try {
            await _supabase.from('commission_settings').upsert([{
                id: 'toggle_item_mode',
                type: 'system_toggle',
                value: isChecked ? 1 : 0,
                auto_trigger: isChecked,
                updated_at: new Date().toISOString()
            }], { onConflict: 'id' });

            await _supabase.from('system_settings').upsert([
                { key: 'hr_item_commission_enabled', value: isChecked ? 'true' : 'false', updated_at: new Date().toISOString() }
            ], { onConflict: 'key' });
        } catch (err) {
            console.warn('Error saving item mode state:', err);
        }
    }

    // จัดการเปิด/ปิด Control และตาราง
    const addBtn = document.querySelector('button[onclick="openAddItemDividendModal()"]');
    const saveBtn = document.querySelector('button[onclick="saveItemCommissionSettings()"]');
    if (addBtn) {
        addBtn.disabled = !isChecked;
        addBtn.style.opacity = isChecked ? '1' : '0.55';
    }
    if (saveBtn) {
        saveBtn.disabled = !isChecked;
        saveBtn.style.opacity = isChecked ? '1' : '0.55';
    }

    const itemInputs = document.querySelectorAll('.item-comm-input');
    itemInputs.forEach(inp => inp.disabled = !isChecked);

    const deleteBtns = document.querySelectorAll('#itemDividendBody button');
    deleteBtns.forEach(btn => btn.disabled = !isChecked);

    const tableWrapper = document.querySelector('#itemDividendTable')?.parentElement;
    if (tableWrapper) {
        tableWrapper.style.opacity = isChecked ? '1' : '0.55';
    }
}
window.toggleItemModeDisplay = toggleItemModeDisplay;

// 🌟 ฟังก์ชันบันทึกตัวเลขปันผลกลับลง Database
async function saveItemCommissionSettings() {
    const inputs = document.querySelectorAll('.item-dividend-input, .item-comm-input');
    if (inputs.length === 0) {
        Swal.fire('แจ้งเตือน', 'ไม่มีรายการให้บันทึก', 'warning');
        return;
    }

    Swal.fire({ title: 'กำลังบันทึก...', allowOutsideClick: false, didOpen: () => Swal.showLoading() });

    // จัดโครงสร้างข้อมูลให้ตรงกับ Database
    const settingsObj = {};
    const payload = Array.from(inputs).map(input => {
        const rawId = input.getAttribute('data-id') || '';
        const id = rawId.startsWith('item_') ? rawId : 'item_' + rawId;
        const serviceId = id.replace(/^item_/, '');
        const val = parseFloat(input.value) || 0;
        settingsObj[serviceId] = val;

        return {
            id: id,
            type: 'item',
            value: val,
            currency: 'LAK',
            auto_trigger: true,
            target_enabled: false,
            target_goal: 0,
            target_bonus_value: 0,
            updated_at: new Date().toISOString()
        };
    });

    localStorage.setItem('hr_item_commission_settings', JSON.stringify(settingsObj));

    let error = null;
    if (typeof _supabase !== 'undefined') {
        const res = await _supabase.from('commission_settings').upsert(payload, { onConflict: 'id' });
        error = res.error;

        try {
            await _supabase.from('system_settings').upsert([
                { key: 'hr_item_commission_settings', value: JSON.stringify(settingsObj), updated_at: new Date().toISOString() }
            ], { onConflict: 'key' });
        } catch (e) { }
    }

    if (error) {
        Swal.fire('ข้อผิดพลาด', error.message, 'error');
    } else {
        Swal.fire('สำเร็จ', 'บันทึกการตั้งค่าปันผลแบบรายรายการเรียบร้อยแล้ว', 'success');
    }
}
window.saveItemCommissionSettings = saveItemCommissionSettings;

async function calculateAndRecordCommission(visitRecordOrId, testsString = '', isBatch = false, targetBill = null) {
    let visitRecord = null;
    let visitId = null;

    if (targetBill && typeof targetBill === 'object') {
        visitId = targetBill.visit_id || null;
    }

    if (typeof visitRecordOrId === 'string') {
        visitId = visitRecordOrId;
        try {
            const { data } = await _supabase.from('visits').select('*').eq('visit_id', visitId).maybeSingle();
            visitRecord = data;
        } catch (e) { }

        if (!visitRecord && window.allPaymentQueue) {
            visitRecord = window.allPaymentQueue.find(v => v.visit_id === visitId || v.id === visitId);
        }
        if (!visitRecord) {
            const cachedVisits = JSON.parse(localStorage.getItem('clinic_visits_queue') || '[]');
            visitRecord = cachedVisits.find(v => (v.visit_id === visitId || v.id === visitId));
        }
    } else if (visitRecordOrId && typeof visitRecordOrId === 'object') {
        if (visitRecordOrId.bill_id && !targetBill) {
            targetBill = visitRecordOrId;
        }
        visitRecord = visitRecordOrId;
        visitId = visitRecord.visit_id || visitRecord.id || (targetBill ? targetBill.visit_id : null);
    }

    // 🌟 ຖ້າບໍ່ມີ targetBill ແຕ່ມີ visitId: ກວດສອບວ່າມີບິນໃນຕາຕະລາງ bills ຫຼືບໍ່
    // ຖ້າມີບິນ ໃຫ້ຄຳນວນແຍກຕາມແຕ່ລະບິນ (Option 1) ຫ້າມສ້າງ COM-VIS- ເດັດຂາດ
    if (!targetBill && visitId) {
        let vBills = (window.allBillsData || window.clinicBills || []).filter(b => b && b.visit_id === visitId && (b.status === 'ชำระแล้ว' || b.status === 'paid' || !b.status));
        if (vBills.length === 0 && typeof _supabase !== 'undefined') {
            try {
                const { data: dbBills } = await _supabase.from('bills').select('*').eq('visit_id', visitId);
                if (dbBills && dbBills.length > 0) vBills = dbBills.filter(b => b && (b.status === 'ชำระแล้ว' || b.status === 'paid' || !b.status));
            } catch (e) { }
        }
        if (vBills.length > 0) {
            for (const b of vBills) {
                await calculateAndRecordCommission(visitRecord || visitId, '', isBatch, b);
            }
            return;
        }
    }

    // Bill ID resolution (Option 1: ແຍກຕາມບິນຈິງ)
    const billId = targetBill ? (targetBill.bill_id || targetBill.id) : null;
    const logId = billId ? ('COM-' + billId) : (visitId ? ('COM-' + visitId) : generateId('COM'));

    // Check payment status
    if (!targetBill) {
        if (!visitRecord) return;
        const vStatus = (visitRecord.status || '').trim();
        const isPaidStatus = (
            visitRecord.payment_status === 'paid' ||
            vStatus === 'รอผลแล็บ' ||
            vStatus === 'ทำรายการสำเร็จ' ||
            vStatus === 'สำเร็จ' ||
            vStatus === 'ชำระแล้ว' ||
            !!visitRecord.bill_id ||
            (Array.isArray(window.clinicBills) && window.clinicBills.some(b => b.visit_id === visitId))
        );
        if (!isPaidStatus && vStatus === 'รอชำระเงิน') {
            return;
        }
    } else {
        const bStatus = (targetBill.status || '').trim();
        if (bStatus && bStatus !== 'ชำระแล้ว' && bStatus !== 'paid') {
            return;
        }
    }

    // Deduplication check: check by logId or bill_id (NOT by visit_id, to allow multiple bills per visit)
    window.commissionLogs = window.commissionLogs || [];
    if (billId) {
        const existingLog = window.commissionLogs.find(l => l.id === logId || l.bill_id === billId);
        if (existingLog && existingLog.status === 'paid') return;
    } else if (visitId) {
        const existingLog = window.commissionLogs.find(l => l.id === logId || (!l.bill_id && l.visit_id === visitId));
        if (existingLog && existingLog.status === 'paid') return;
    }

    // 1. ดึงรหัสผู้แนะนำจาก Bill หรือ Visit หรือค้นหาจากตาราง patients อัตโนมัติ
    let referrerCode = (targetBill && (targetBill.referred_by || targetBill.referrer)) ||
        (visitRecord && (visitRecord.referrer || visitRecord.ref_code || visitRecord.doctor_ref || visitRecord.referred_by)) || '';

    const patientHn = (targetBill && targetBill.hn) || (visitRecord && visitRecord.hn) || '';
    const rawPatientName = (targetBill && targetBill.patient_name) || (visitRecord && visitRecord.patient_name) || '';

    if (!referrerCode || referrerCode === '-' || referrerCode === 'null' || referrerCode === 'undefined') {
        // ค้นหาผู้แนะนำจากตาราง patients ตาม HN หรือชื่อคนไข้ (ใน memory)
        if (Array.isArray(window.allPatients)) {
            let patObj = null;
            if (patientHn && patientHn !== '-') {
                patObj = window.allPatients.find(p => p.hn === patientHn || p.HN === patientHn || p.id === patientHn);
            }
            if (!patObj && rawPatientName && rawPatientName !== 'ผู้ป่วย') {
                patObj = window.allPatients.find(p => p.patient_name === rawPatientName || p.FullName === rawPatientName);
            }
            if (patObj) {
                referrerCode = patObj.referrer || patObj.ref_code || patObj.referred_by || '';
            }
        }

        // 🌟 Direct Database Fallback: หากใน memory ไม่มี ให้ค้นหาจากฐานข้อมูล Supabase patients ໂດຍກົງ
        if ((!referrerCode || referrerCode === '-') && typeof _supabase !== 'undefined') {
            try {
                if (patientHn && patientHn !== '-') {
                    const { data: pDb } = await _supabase.from('patients').select('referred_by, referrer, ref_code, patient_name').eq('hn', patientHn).maybeSingle();
                    if (pDb) {
                        referrerCode = pDb.referred_by || pDb.referrer || pDb.ref_code || '';
                        if ((!rawPatientName || rawPatientName === 'ผู้ป่วย') && pDb.patient_name) rawPatientName = pDb.patient_name;
                    }
                }
                if (!referrerCode && rawPatientName && rawPatientName !== 'ผู้ป่วย') {
                    const { data: pDb } = await _supabase.from('patients').select('referred_by, referrer, ref_code, patient_name').ilike('patient_name', rawPatientName.trim()).maybeSingle();
                    if (pDb) {
                        referrerCode = pDb.referred_by || pDb.referrer || pDb.ref_code || '';
                    }
                }
            } catch (e) { }
        }
    }

    let referrerId = referrerCode || null;
    let patientName = rawPatientName || 'ผู้ป่วย';

    // 2. ค้นหาจาก LocalStorage Maps สำรอง (ยึด HN ก่อน)
    const patMap = JSON.parse(localStorage.getItem('clinic_patient_referrers') || '{}');
    if (!referrerId && patientHn && patMap[patientHn]) {
        referrerId = patMap[patientHn];
    }

    const apptMap = JSON.parse(localStorage.getItem('clinic_appointment_referrers') || '{}');
    if (!referrerId && visitRecord && visitRecord.appointment_id && apptMap[visitRecord.appointment_id]) {
        referrerId = apptMap[visitRecord.appointment_id];
    }

    // 3. ค้นหาใน memory cache ของผู้ป่วย (patients) สำรอง (ยึด HN ก่อน)
    if (!referrerId && (patientHn || patientName)) {
        let pat = null;
        if (patientHn && patientHn !== '-') {
            pat = (window.allPatients || []).find(p => p.hn === patientHn || p.HN === patientHn || p.id === patientHn);
        }
        if (!pat && patientName && patientName !== 'ผู้ป่วย') {
            pat = (window.allPatients || []).find(p => p.patient_name === patientName || p.FullName === patientName);
        }
        if (pat && (pat.referrer || pat.ref_code || pat.referred_by)) {
            referrerId = pat.referrer || pat.ref_code || pat.referred_by;
        }
    }

    if (!referrerId) {
        return;
    }

    let referrer = (window.referrersData || []).find(r => r.id === referrerId || r.code === referrerId || r.name === referrerId);
    let refName = referrer ? referrer.name : referrerId;

    if (!referrer) {
        const emp = (window.allEmployeesData || []).find(e => e.emp_code === referrerId || e.full_name === referrerId) ||
            (window.allStaffUsers || []).find(s => s.emp_code === referrerId || s.full_name === referrerId);
        if (emp) {
            refName = `${emp.emp_code || ''} - ${emp.full_name || ''}`.replace(/^ - /, '');
        }
    }

    // Calculate totalInvoice: Prioritize bill's payable amount
    let totalInvoice = 0;
    if (targetBill) {
        if (targetBill.payable_amount !== undefined && parseFloat(targetBill.payable_amount) >= 0) {
            totalInvoice = parseFloat(targetBill.payable_amount);
        } else if (targetBill.subtotal !== undefined && parseFloat(targetBill.subtotal) >= 0) {
            totalInvoice = parseFloat(targetBill.subtotal);
        }
    } else if (visitRecord) {
        if (visitRecord.payable_amount !== undefined && parseFloat(visitRecord.payable_amount) > 0) {
            totalInvoice = parseFloat(visitRecord.payable_amount);
        } else if (visitRecord.total_price !== undefined && parseFloat(visitRecord.total_price) > 0) {
            totalInvoice = parseFloat(visitRecord.total_price);
        } else if (visitRecord.price !== undefined && parseFloat(visitRecord.price) > 0) {
            totalInvoice = parseFloat(visitRecord.price);
        } else if (visitRecord.total_amount !== undefined && parseFloat(visitRecord.total_amount) > 0) {
            totalInvoice = parseFloat(visitRecord.total_amount);
        }
    }

    if (totalInvoice <= 0 && visitRecord) {
        let calcSum = 0;
        const testStr = testsString || visitRecord.lab_tests || '';
        if (testStr && typeof testStr === 'string') {
            const testNames = testStr.split(',').map(s => s.trim()).filter(Boolean);
            testNames.forEach(t => {
                if (typeof getTestItemDetails === 'function') {
                    calcSum += getTestItemDetails(t).price;
                } else {
                    const foundSvc = (window.servicesData || []).find(s => s.name === t);
                    if (foundSvc) calcSum += parseFloat(foundSvc.price || 0);
                }
            });
        }
        if (calcSum > 0) {
            const disc = parseFloat(visitRecord.discount || visitRecord.lab_discount || 0);
            totalInvoice = Math.max(0, calcSum - disc);
        }
    }

    if (totalInvoice <= 0) totalInvoice = 0;
    let commAmount = 0;
    let isBonusApplied = false;

    // 1. คำนวณปันผลแบบภาพรวม (Overall Dividend)
    let overallComm = 0;
    const overallSwitch = document.getElementById('overallModeSwitch');
    const isOverallActive = overallSwitch ? overallSwitch.checked : (
        (window.commissionSettings && window.commissionSettings.overall_enabled !== false) &&
        (localStorage.getItem('clinic_comm_overall_enabled') !== null
            ? (localStorage.getItem('clinic_comm_overall_enabled') === 'true' || localStorage.getItem('clinic_comm_overall_enabled') === true)
            : (localStorage.getItem('hr_overall_commission_enabled') !== 'false'))
    );

    if (isOverallActive) {
        const monthlyCount = getMonthlyReferredCount(referrerId, refName);
        const targetEnabled = window.commissionSettings.target_enabled === true;
        const targetGoal = window.commissionSettings.target_goal || 0;

        if (targetEnabled && targetGoal > 0 && (monthlyCount + 1) >= targetGoal) {
            isBonusApplied = true;
            const bonusValue = parseFloat(window.commissionSettings.target_bonus_value || 0);
            if (window.commissionSettings.type === 'percentage') {
                overallComm = totalInvoice * (bonusValue / 100);
            } else {
                overallComm = bonusValue;
            }
        } else {
            const standardValue = parseFloat(window.commissionSettings.value !== undefined ? window.commissionSettings.value : 0);
            if (window.commissionSettings.type === 'percentage') {
                overallComm = totalInvoice * (standardValue / 100);
            } else {
                overallComm = standardValue;
            }
        }
    }

    // 2. คำนวณปันผลแบบรายรายการบวกเพิ่ม (Item-based Dividend Add-on)
    let itemCommSum = 0;
    let itemDetailsArr = [];
    const itemSwitch = document.getElementById('itemModeSwitch');
    const itemModeEnabled = itemSwitch ? itemSwitch.checked : (
        localStorage.getItem('clinic_comm_item_enabled') !== null
            ? (localStorage.getItem('clinic_comm_item_enabled') === 'true' || localStorage.getItem('clinic_comm_item_enabled') === true)
            : (localStorage.getItem('hr_item_commission_enabled') !== 'false')
    );

    if (itemModeEnabled) {
        let itemSettings = JSON.parse(localStorage.getItem('hr_item_commission_settings') || '{}');
        if (Object.keys(itemSettings).length === 0 && window.allCommissionItemSettings) {
            itemSettings = window.allCommissionItemSettings;
        }

        // 🌟 Ensure both commission_settings and services catalog are loaded
        if (typeof _supabase !== 'undefined' && (Object.keys(itemSettings).length === 0 || !window.servicesData || window.servicesData.length === 0)) {
            try {
                const [{ data: cSettings }, { data: sData }] = await Promise.all([
                    _supabase.from('commission_settings').select('*'),
                    _supabase.from('services').select('id, name, price')
                ]);
                if (cSettings && cSettings.length > 0) {
                    itemSettings = itemSettings || {};
                    cSettings.forEach(cs => {
                        if (cs.type === 'item') {
                            const clean = cs.id.replace(/^item_/, '');
                            itemSettings[clean] = cs.value;
                            itemSettings[cs.id] = cs.value;
                        }
                    });
                }
                if (sData && sData.length > 0) {
                    window.servicesData = sData;
                    window.allServicesData = sData;
                }
            } catch (e) { }
        }

        // 🌟 Enrich itemSettings with all service names and normalized aliases
        const allServicesList = (window.allServicesData || window.servicesData || JSON.parse(localStorage.getItem('clinic_services_packages') || '[]') || []);
        if (Array.isArray(allServicesList) && allServicesList.length > 0) {
            allServicesList.forEach(s => {
                if (!s || !s.name) return;
                const sClean = String(s.id || '').replace(/^item_/, '').trim();
                const val = itemSettings[sClean] !== undefined ? itemSettings[sClean] : itemSettings['item_' + sClean];
                if (val !== undefined && parseFloat(val) > 0) {
                    const numVal = parseFloat(val);
                    const sName = s.name.trim();
                    itemSettings[sName] = numVal;
                    itemSettings[sName.toLowerCase()] = numVal;
                    const norm1 = sName.replace(/[.,\s]/g, '').toLowerCase();
                    if (norm1) itemSettings[norm1] = numVal;
                    const norm2 = sName.replace(/[.,]/g, ' ').replace(/\s+/g, ' ').toLowerCase();
                    if (norm2) itemSettings[norm2] = numVal;
                }
            });
        }

        let itemList = [];
        if (targetBill) {
            let billItems = targetBill.items;
            if (typeof billItems === 'string') {
                try { billItems = JSON.parse(billItems); } catch (e) { billItems = []; }
            }
            if (Array.isArray(billItems)) itemList = itemList.concat(billItems);
        } else if (visitRecord) {
            if (Array.isArray(visitRecord.items)) itemList = itemList.concat(visitRecord.items);
            if (Array.isArray(visitRecord.services)) itemList = itemList.concat(visitRecord.services);
            if (Array.isArray(visitRecord.lab_orders)) itemList = itemList.concat(visitRecord.lab_orders);
        }

        const currentLabTests = testsString || (visitRecord ? visitRecord.lab_tests : '');
        if (itemList.length === 0 && currentLabTests && typeof currentLabTests === 'string') {
            const labArr = currentLabTests.split(',').map(s => s.trim()).filter(Boolean);
            labArr.forEach(labName => {
                const exists = itemList.some(it => String(it.name || it.title || it.id || '').trim().toLowerCase() === labName.toLowerCase());
                if (!exists) {
                    itemList.push({ name: labName, id: labName });
                }
            });
        }

        itemList.forEach(item => {
            if (!item) return;
            const rawItemId = String(item.id || item.service_id || item.item_id || '').trim();
            const cleanItemId = rawItemId.replace(/^item_/, '').trim();
            const itemName = (item.name || item.title || '').trim();
            const qty = parseFloat(item.qty || item.quantity || 1) || 1;

            let matchedVal = null;

            // 1. ตรวจสอบโดยตรงจาก ID รายการบริการ (Direct Service ID)
            if (cleanItemId && cleanItemId !== '-' && cleanItemId !== 'null' && cleanItemId !== 'undefined') {
                if (itemSettings[cleanItemId] !== undefined && parseFloat(itemSettings[cleanItemId]) > 0) {
                    matchedVal = parseFloat(itemSettings[cleanItemId]);
                } else if (itemSettings['item_' + cleanItemId] !== undefined && parseFloat(itemSettings['item_' + cleanItemId]) > 0) {
                    matchedVal = parseFloat(itemSettings['item_' + cleanItemId]);
                }
            }

            // 2. ตรวจสอบโดยตรงจากชื่อรายการแบบตรงกันเป๊ะ (Exact Name Match 100%)
            if ((matchedVal === null || isNaN(matchedVal) || matchedVal <= 0) && itemName && itemName !== '-') {
                const lowerItemName = itemName.toLowerCase();
                const normItemName = itemName.replace(/[.,\s]/g, '').toLowerCase();

                if (itemSettings[itemName] !== undefined && parseFloat(itemSettings[itemName]) > 0) {
                    matchedVal = parseFloat(itemSettings[itemName]);
                } else if (itemSettings[lowerItemName] !== undefined && parseFloat(itemSettings[lowerItemName]) > 0) {
                    matchedVal = parseFloat(itemSettings[lowerItemName]);
                } else if (itemSettings[normItemName] !== undefined && parseFloat(itemSettings[normItemName]) > 0) {
                    matchedVal = parseFloat(itemSettings[normItemName]);
                } else {
                    // ตรวจสอบ Case-insensitive ตรงตัวกับ Key ใน itemSettings
                    const foundExactKey = Object.keys(itemSettings).find(k => {
                        const cleanK = k.replace(/^item_/, '').trim();
                        return (cleanK && cleanK.toLowerCase() === lowerItemName) ||
                               (cleanK && cleanK.replace(/[.,\s]/g, '').toLowerCase() === normItemName);
                    });
                    if (foundExactKey && parseFloat(itemSettings[foundExactKey]) > 0) {
                        matchedVal = parseFloat(itemSettings[foundExactKey]);
                    }
                }

                // 3. หากยังไม่พบ ค้นหาในรายการบริการหลัก (allServicesList) แบบตรงตัวเป๊ะเท่านั้น (Exact ID หรือ Exact Name)
                // 🛑 ตัดระบบ .includes() สุ่มคำคล้ายออกทั้งหมด เพื่อไม่ให้รายการตรวจอื่นถูกดึงมาคิดปันผลโดยไม่ได้รับอนุญาต
                if (matchedVal === null || isNaN(matchedVal) || matchedVal <= 0) {
                    const matchedSvc = allServicesList.find(s => {
                        if (!s) return false;
                        const sId = String(s.id || s.service_id || '').replace(/^item_/, '').trim();
                        const sName = String(s.name || '').trim();
                        if (cleanItemId && sId && sId.toLowerCase() === cleanItemId.toLowerCase()) return true;
                        if (sName && sName.toLowerCase() === lowerItemName) return true;
                        if (sName && sName.replace(/[.,\s]/g, '').toLowerCase() === normItemName) return true;
                        return false;
                    });

                    if (matchedSvc) {
                        const sId = String(matchedSvc.id || matchedSvc.service_id || '').replace(/^item_/, '').trim();
                        const sName = String(matchedSvc.name || '').trim();

                        if (sId && itemSettings[sId] !== undefined && parseFloat(itemSettings[sId]) > 0) {
                            matchedVal = parseFloat(itemSettings[sId]);
                        } else if (sId && itemSettings['item_' + sId] !== undefined && parseFloat(itemSettings['item_' + sId]) > 0) {
                            matchedVal = parseFloat(itemSettings['item_' + sId]);
                        } else if (sName && itemSettings[sName] !== undefined && parseFloat(itemSettings[sName]) > 0) {
                            matchedVal = parseFloat(itemSettings[sName]);
                        } else if (sName && itemSettings[sName.toLowerCase()] !== undefined && parseFloat(itemSettings[sName.toLowerCase()]) > 0) {
                            matchedVal = parseFloat(itemSettings[sName.toLowerCase()]);
                        }
                    }
                }
            }

            // 🌟 เฉพาะรายการที่เข้าเงื่อนไข (มีเงินปันผล > 0) เท่านั้นที่จะถูกนำมาคิดและบันทึก
            // รายการใดที่ไม่อยู่ในเงื่อนไข จะถูกข้าม (Skip) 100%
            if (matchedVal !== null && !isNaN(matchedVal) && matchedVal > 0) {
                const addVal = matchedVal * qty;
                itemCommSum += addVal;
                itemDetailsArr.push(`${itemName || 'รายการตรวจ'}: ${formatCommissionAmount(addVal)}`);
            }
        });
    }

    // Net dividend = Overall + Item-based
    commAmount = (isOverallActive ? overallComm : 0) + (itemModeEnabled ? itemCommSum : 0);

    // If no matching item with dividend and overall is 0, skip creating dividend log (and clean up any stale pending log)
    if ((!isOverallActive && !itemModeEnabled) || commAmount <= 0) {
        const remIdx = window.commissionLogs.findIndex(l => (l.id === logId || (billId && l.bill_id === billId)) && l.status === 'pending');
        if (remIdx !== -1) {
            const remLogId = window.commissionLogs[remIdx].id;
            window.commissionLogs.splice(remIdx, 1);
            if (typeof _supabase !== 'undefined') {
                try {
                    _supabase.from('commission_logs').delete().eq('id', remLogId).then(() => { }).catch(() => { });
                } catch (e) { }
            }
        }
        return;
    }

    // Resolve true transaction date
    let trueCreatedAt = (targetBill && targetBill.created_at) ||
        (visitRecord && (visitRecord.created_at || visitRecord.date || visitRecord.visit_date || visitRecord.payment_date)) ||
        '';
    if (!trueCreatedAt && visitId) {
        const allV = (window.allVisitsCache || []).concat(window.clinicVisits || []);
        const foundV = allV.find(x => (x.visit_id || x.id) === visitId);
        if (foundV && (foundV.created_at || foundV.date)) trueCreatedAt = foundV.created_at || foundV.date;
    }
    if (!trueCreatedAt) trueCreatedAt = new Date().toISOString();

    const existingIdx = window.commissionLogs.findIndex(l => l.id === logId || (billId && l.bill_id === billId));
    if (existingIdx !== -1) {
        if (window.commissionLogs[existingIdx].status === 'paid') {
            return;
        }
        window.commissionLogs[existingIdx] = {
            ...window.commissionLogs[existingIdx],
            bill_id: billId || window.commissionLogs[existingIdx].bill_id || null,
            visit_id: visitId || window.commissionLogs[existingIdx].visit_id || null,
            total_invoice: totalInvoice,
            base_amount: overallComm,
            item_amount: itemCommSum,
            item_details: itemDetailsArr.join(', '),
            amount: commAmount,
            patient_name: patientName || window.commissionLogs[existingIdx].patient_name,
            referrer_id: referrerId,
            referrer_name: refName,
            is_bonus: isBonusApplied,
            created_at: trueCreatedAt || window.commissionLogs[existingIdx].created_at
        };
        const updatedLog = window.commissionLogs[existingIdx];
        if (!isBatch) {
            saveReferralLocalData();
            updateReferralSummaryCards();
            if (typeof renderReferrersTable === 'function') renderReferrersTable();
            if (typeof renderCommissionLogsTable === 'function') renderCommissionLogsTable();

            try {
                if (typeof _supabase !== 'undefined') {
                    const dbPayload = {
                        id: updatedLog.id,
                        referrer_id: updatedLog.referrer_id,
                        referrer_name: updatedLog.referrer_name,
                        patient_name: updatedLog.patient_name,
                        visit_id: updatedLog.visit_id,
                        total_invoice: updatedLog.total_invoice,
                        base_amount: updatedLog.base_amount,
                        item_amount: updatedLog.item_amount,
                        item_details: updatedLog.item_details,
                        amount: updatedLog.amount,
                        status: updatedLog.status,
                        is_bonus: updatedLog.is_bonus,
                        created_at: updatedLog.created_at
                    };
                    await _supabase.from('commission_logs').upsert([dbPayload], { onConflict: 'id' });
                }
            } catch (e) { }
        }
        return;
    }

    const newLog = {
        id: logId,
        bill_id: billId || null,
        visit_id: visitId || null,
        referrer_id: referrerId,
        referrer_name: refName,
        patient_name: patientName,
        total_invoice: totalInvoice,
        base_amount: overallComm,
        item_amount: itemCommSum,
        item_details: itemDetailsArr.join(', '),
        amount: commAmount,
        status: 'pending',
        is_bonus: isBonusApplied,
        created_at: trueCreatedAt
    };

    window.commissionLogs.unshift(newLog);

    // If bill-based log created, clean up any superseded legacy visit-level log (COM-VIS-xxxx)
    if (billId && visitId) {
        const oldVisitLogIdx = window.commissionLogs.findIndex(l => l.id === ('COM-' + visitId) && !l.bill_id);
        if (oldVisitLogIdx !== -1) {
            window.commissionLogs.splice(oldVisitLogIdx, 1);
            if (typeof _supabase !== 'undefined') {
                try {
                    _supabase.from('commission_logs').delete().eq('id', 'COM-' + visitId).then(() => { });
                } catch (e) { }
            }
        }
    }

    if (!isBatch) {
        saveReferralLocalData();
        updateReferralSummaryCards();
        if (typeof renderReferrersTable === 'function') renderReferrersTable();
        if (typeof renderCommissionLogsTable === 'function') renderCommissionLogsTable();

        try {
            if (typeof _supabase !== 'undefined') {
                const dbPayload = {
                    id: newLog.id,
                    referrer_id: newLog.referrer_id,
                    referrer_name: newLog.referrer_name,
                    patient_name: newLog.patient_name,
                    visit_id: newLog.visit_id,
                    total_invoice: newLog.total_invoice,
                    base_amount: newLog.base_amount,
                    item_amount: newLog.item_amount,
                    item_details: newLog.item_details,
                    amount: newLog.amount,
                    status: newLog.status,
                    is_bonus: newLog.is_bonus,
                    created_at: newLog.created_at
                };
                await _supabase.from('commission_logs').upsert([dbPayload], { onConflict: 'id' });
            }
        } catch (e) { }
    }
}
window.calculateAndRecordCommission = calculateAndRecordCommission;
window.processPaymentCommission = calculateAndRecordCommission;

async function syncAllVisitsCommissionLogs() {
    window.commissionLogs = window.commissionLogs || [];
    let visits = Array.isArray(window.clinicVisits) && window.clinicVisits.length > 0 ? window.clinicVisits : [];
    let patients = Array.isArray(window.allPatients) && window.allPatients.length > 0 ? window.allPatients : [];
    let bills = Array.isArray(window.allBillsData) && window.allBillsData.length > 0 ? window.allBillsData : [];

    try {
        if (typeof _supabase !== 'undefined') {
            const needVisits = visits.length === 0;
            const needPatients = patients.length === 0;
            const needBills = bills.length === 0;
            const needServices = (!window.servicesData || window.servicesData.length === 0);

            if (needVisits || needPatients || needBills || needServices) {
                const [{ data: vData }, { data: pData }, { data: bData }, { data: sData }] = await Promise.all([
                    needVisits ? _supabase.from('visits').select('*').order('created_at', { ascending: false }).limit(100) : Promise.resolve({ data: visits }),
                    needPatients ? _supabase.from('patients').select('*').order('created_at', { ascending: false }).limit(100) : Promise.resolve({ data: patients }),
                    needBills ? _supabase.from('bills').select('*').order('created_at', { ascending: false }).limit(100) : Promise.resolve({ data: bills }),
                    needServices ? _supabase.from('services').select('id, name, price') : Promise.resolve({ data: window.servicesData })
                ]);
                if (vData && vData.length > 0) visits = vData;
                if (pData && pData.length > 0) patients = pData;
                if (bData && bData.length > 0) bills = bData;
                if (sData && sData.length > 0) {
                    window.servicesData = sData;
                    window.allServicesData = sData;
                }
            }
        }
    } catch (e) { }

    const localVisits = JSON.parse(localStorage.getItem('clinic_visits_queue') || '[]');
    if (Array.isArray(localVisits) && localVisits.length > 0) {
        const map = new Map();
        visits.forEach(v => { if (v && (v.visit_id || v.id)) map.set(v.visit_id || v.id, v); });
        localVisits.forEach(v => {
            if (v && (v.visit_id || v.id)) {
                const k = v.visit_id || v.id;
                const existing = map.get(k) || {};
                map.set(k, { ...existing, ...v, visit_id: k, created_at: v.created_at || existing.created_at });
            }
        });
        visits = Array.from(map.values());
    }

    const localBills = (window.clinicBills || []).concat(window.allBillsData || []).concat(JSON.parse(localStorage.getItem('clinic_bills_cache') || '[]'));
    const billMap = new Map();
    bills.forEach(b => { if (b && b.bill_id) billMap.set(b.bill_id, b); });
    localBills.forEach(b => { if (b && b.bill_id && !billMap.has(b.bill_id)) billMap.set(b.bill_id, b); });
    bills = Array.from(billMap.values());

    const patientMap = {};
    patients.forEach(p => {
        if (p.hn) patientMap[p.hn] = p;
        if (p.patient_name) patientMap[p.patient_name.trim().toLowerCase()] = p;
        if (p.name) patientMap[p.name.trim().toLowerCase()] = p;
    });

    const existingLogIds = new Set(window.commissionLogs.map(l => l.id).filter(Boolean));
    const existingBillLogIds = new Set(window.commissionLogs.map(l => l.bill_id || (l.id && l.id.startsWith('COM-BILL-') ? l.id.replace(/^COM-/, '') : null)).filter(Boolean));

    let addedCount = 0;
    const newLogsToUpsert = [];

    // 1. Process commissions by BILL (Option 1: แยกตามบิลจริง)
    const paidBills = bills.filter(b => b && (b.status === 'ชำระแล้ว' || b.status === 'paid' || !b.status));
    for (const b of paidBills) {
        const bId = b.bill_id;
        if (!bId) continue;
        const logId = 'COM-' + bId;
        const existingLog = (window.commissionLogs || []).find(l => l.id === logId || (bId && l.bill_id === bId));
        if (existingLog && existingLog.status === 'paid') continue;

        let v = visits.find(x => (x.visit_id || x.id) === b.visit_id) || {};
        let p = null;
        if (b.hn && patientMap[b.hn]) {
            p = patientMap[b.hn];
        } else if (v.hn && patientMap[v.hn]) {
            p = patientMap[v.hn];
        } else if (b.patient_name) {
            const cleanName = b.patient_name.trim().toLowerCase();
            p = patientMap[cleanName] || patients.find(pt => (pt.patient_name || pt.name || '').trim().toLowerCase() === cleanName);
        }

        const refBy = b.referred_by || b.referrer || v.referred_by || v.referrer || v.ref_code || v.doctor_ref || p?.referred_by || p?.referrer || p?.ref_code;
        if (refBy && refBy !== '-' && refBy !== 'null' && refBy !== 'undefined') {
            v.referrer = refBy;
            if (!v.hn && b.hn) v.hn = b.hn;
            if (!v.patient_name && b.patient_name) v.patient_name = b.patient_name;
            await calculateAndRecordCommission(v, '', true, b);
            const targetLog = (window.commissionLogs || []).find(l => l.id === logId || (bId && l.bill_id === bId));
            if (targetLog && targetLog.status !== 'paid') {
                newLogsToUpsert.push(targetLog);
            }
            existingLogIds.add(logId);
            existingBillLogIds.add(bId);
            addedCount++;
        }
    }

    // 2. Fallback: Process visits that have NO bills in the bills table
    const visitIdsWithBills = new Set(bills.map(b => b.visit_id).filter(Boolean));
    for (const v of visits) {
        const vId = v.visit_id || v.id;
        if (!vId) continue;
        if (visitIdsWithBills.has(vId)) continue;
        const existingLog = (window.commissionLogs || []).find(l => l.id === ('COM-' + vId) || (!l.bill_id && l.visit_id === vId));
        if (existingLog && existingLog.status === 'paid') continue;

        const vStatus = (v.status || '').trim();
        const isPaidStatus = (
            v.payment_status === 'paid' ||
            vStatus === 'รอผลแล็บ' ||
            vStatus === 'ทำรายการสำเร็จ' ||
            vStatus === 'สำเร็จ' ||
            vStatus === 'ชำระแล้ว' ||
            !!v.bill_id
        );
        if (!isPaidStatus && vStatus === 'รอชำระเงิน') continue;

        let p = null;
        if (v.hn && patientMap[v.hn]) {
            p = patientMap[v.hn];
        } else if (v.patient_name) {
            const cleanName = v.patient_name.trim().toLowerCase();
            p = patientMap[cleanName] || patients.find(pt => (pt.patient_name || pt.name || '').trim().toLowerCase() === cleanName);
        }

        const refBy = v.referred_by || v.referrer || v.ref_code || v.doctor_ref || p?.referred_by || p?.referrer || p?.ref_code;
        if (refBy && refBy !== '-' && refBy !== 'null' && refBy !== 'undefined') {
            v.referrer = refBy;
            if (!v.hn && p && p.hn) v.hn = p.hn;
            await calculateAndRecordCommission(v, v.lab_tests || '', true, null);
            const targetLog = (window.commissionLogs || []).find(l => l.id === ('COM-' + vId) || (!l.bill_id && l.visit_id === vId));
            if (targetLog && targetLog.status !== 'paid') {
                newLogsToUpsert.push(targetLog);
            }
            addedCount++;
        }
    }

    // 3. Clean up any old visit-level logs (COM-VIS-xxxx) that have been superseded by bill-level logs (COM-BILL-xxxx)
    const billVisits = new Set(bills.map(b => b.visit_id).concat(window.commissionLogs.filter(l => l.bill_id || (l.id && l.id.startsWith('COM-BILL-'))).map(l => l.visit_id)).filter(Boolean));
    if (billVisits.size > 0) {
        const supersededLogIds = [];
        window.commissionLogs = window.commissionLogs.filter(l => {
            if (l.id && l.id.startsWith('COM-VIS-') && billVisits.has(l.visit_id) && !l.bill_id) {
                supersededLogIds.push(l.id);
                return false;
            }
            return true;
        });
        if (supersededLogIds.length > 0 && typeof _supabase !== 'undefined') {
            try {
                _supabase.from('commission_logs').delete().in('id', supersededLogIds).then(() => {
                    console.log('✅ Cleaned up superseded visit-level commission logs:', supersededLogIds);
                }).catch(() => { });
            } catch (e) { }
        }
    }

    // 🌟 Reconcile and fix transaction dates of all existing commission logs
    const visitDateMap = new Map();
    visits.forEach(v => {
        const vId = v.visit_id || v.id;
        const vDate = v.created_at || v.date || v.visit_date;
        if (vId && vDate) visitDateMap.set(vId, vDate);
    });

    const billDateMap = new Map();
    bills.forEach(b => {
        if (b.bill_id && b.created_at) billDateMap.set(b.bill_id, b.created_at);
    });

    const logsToFix = [];
    (window.commissionLogs || []).forEach(l => {
        const bId = l.bill_id || (l.id && l.id.startsWith('COM-BILL-') ? l.id.replace(/^COM-/, '') : null);
        if (bId && billDateMap.has(bId)) {
            const trueDate = billDateMap.get(bId);
            if (trueDate && l.created_at !== trueDate) {
                l.created_at = trueDate;
                logsToFix.push({ id: l.id, created_at: trueDate });
            }
        } else if (l.visit_id && visitDateMap.has(l.visit_id)) {
            const trueDate = visitDateMap.get(l.visit_id);
            if (trueDate && l.created_at !== trueDate) {
                l.created_at = trueDate;
                logsToFix.push({ id: l.id, created_at: trueDate });
            }
        }
    });

    // 🌟 Direct Supabase cloud upsert for all batch-added logs
    if (newLogsToUpsert.length > 0 && typeof _supabase !== 'undefined') {
        try {
            const cleanUpsert = newLogsToUpsert.map(l => ({
                id: l.id,
                referrer_id: l.referrer_id || null,
                referrer_name: l.referrer_name || null,
                patient_name: l.patient_name || null,
                visit_id: l.visit_id || null,
                total_invoice: parseFloat(l.total_invoice || 0),
                base_amount: parseFloat(l.base_amount || 0),
                item_amount: parseFloat(l.item_amount || 0),
                item_details: l.item_details || '',
                amount: parseFloat(l.amount || 0),
                status: l.status || 'pending',
                is_bonus: !!l.is_bonus,
                created_at: l.created_at || new Date().toISOString()
            }));
            await _supabase.from('commission_logs').upsert(cleanUpsert, { onConflict: 'id' });
            console.log(`✅ Upserted ${cleanUpsert.length} bill commission logs to Supabase cloud DB`);
        } catch (e) {
            console.warn('Batch commission upsert error:', e);
        }
    }

    if (logsToFix.length > 0 && typeof _supabase !== 'undefined') {
        _supabase.from('commission_logs').upsert(logsToFix, { onConflict: 'id' }).then(() => {
            console.log(`✅ Synced transaction dates for ${logsToFix.length} commission logs`);
        }).catch(err => {
            console.warn('Sync commission log dates error:', err);
        });
    }

    if (addedCount > 0 || logsToFix.length > 0) {
        saveReferralLocalData();
        updateReferralSummaryCards();
        if (typeof renderReferrersTable === 'function') renderReferrersTable();
        if (typeof renderCommissionLogsTable === 'function') renderCommissionLogsTable();
    }
}
window.syncAllVisitsCommissionLogs = syncAllVisitsCommissionLogs;

// Real-time listener for MLM system updates from Team.html / other tabs
window.addEventListener('storage', (event) => {
    if (event.key === 'stk_app_cache_data' || event.key === 'stk_members' || event.key === 'clinic_referrers' || event.key === 'hr_employees') {
        console.log('MLM Member profiles updated, auto-syncing Clinic referral data...');
        if (typeof loadReferralData === 'function') {
            loadReferralData(false);
        }
    }
});

// ============================================================
// 15. รายงานสรุปค่าตรวจรักษาและค่าบริการประจำวัน (Daily Consultation & Service Fee Report)
// ============================================================
window.dailyReportPeriodMode = 'month';

function setDailyReportPeriod(mode) {
    window.dailyReportPeriodMode = mode;
    const btnDay = document.getElementById('btnDailyDay');
    const btnMonth = document.getElementById('btnDailyMonth');
    const btnYear = document.getElementById('btnDailyYear');

    const inputDate = document.getElementById('dailyReportDate');
    const inputMonth = document.getElementById('dailyReportMonth');

    if (btnDay && btnMonth && btnYear) {
        btnDay.className = "btn btn-sm rounded-pill fw-medium px-3 text-muted bg-transparent border-0";
        btnMonth.className = "btn btn-sm rounded-pill fw-medium px-3 text-muted bg-transparent border-0";
        btnYear.className = "btn btn-sm rounded-pill fw-medium px-3 text-muted bg-transparent border-0";

        if (mode === 'day') {
            btnDay.className = "btn btn-sm rounded-pill fw-medium px-3 text-primary bg-light shadow-xs border-0";
            if (inputDate) inputDate.classList.remove('d-none');
            if (inputMonth) inputMonth.classList.add('d-none');
        } else if (mode === 'month') {
            btnMonth.className = "btn btn-sm rounded-pill fw-medium px-3 text-primary bg-light shadow-xs border-0";
            if (inputMonth) inputMonth.classList.remove('d-none');
            if (inputDate) inputDate.classList.add('d-none');
        } else if (mode === 'year') {
            btnYear.className = "btn btn-sm rounded-pill fw-medium px-3 text-primary bg-light shadow-xs border-0";
            if (inputMonth) inputMonth.classList.add('d-none');
            if (inputDate) inputDate.classList.add('d-none');
        }
    }
    loadDailyReport();
}

async function loadDailyReport(isManualClick = false) {
    const tbodySummary = document.querySelector('#dailyReportSummaryTable tbody');
    const tbodyDetail = document.querySelector('#dailyReportDetailTable tbody');
    if (!tbodySummary) return;

    const periodMode = window.dailyReportPeriodMode || 'month';
    const dateInput = document.getElementById('dailyReportDate');
    const monthInput = document.getElementById('dailyReportMonth');
    const searchInput = document.getElementById('dailyReportSearch');
    const searchText = searchInput ? searchInput.value.toLowerCase().trim() : '';

    let visits = [];

    // Query Supabase visits table
    try {
        if (typeof _supabase !== 'undefined') {
            let vQuery = _supabase
                .from('visits')
                .select('visit_id, hn, patient_name, doctor_name, symptom, created_at, status');

            if (periodMode === 'day') {
                let targetDate = dateInput && dateInput.value ? dateInput.value : '';
                if (!targetDate) {
                    const todayRange = getVientianeDateRange('today');
                    targetDate = todayRange.startStr;
                    if (dateInput) dateInput.value = targetDate;
                }
                vQuery = vQuery.gte('created_at', targetDate + "T00:00:00").lte('created_at', targetDate + "T23:59:59");
            } else if (periodMode === 'month') {
                let targetMonth = monthInput && monthInput.value ? monthInput.value : '';
                if (!targetMonth) {
                    const vNow = getVientianeNow();
                    targetMonth = `${vNow.getFullYear()}-${String(vNow.getMonth() + 1).padStart(2, '0')}`;
                    if (monthInput) monthInput.value = targetMonth;
                }
                // Bug 5: คำนวณวันสุดท้ายของเดือนให้ถูกต้อง (ไม่ใช้ -31 คงที่)
                const [mYear, mMon] = targetMonth.split('-').map(Number);
                const lastDay = new Date(mYear, mMon, 0).getDate(); // วันสุดท้ายของเดือนนั้น
                vQuery = vQuery.gte('created_at', targetMonth + "-01T00:00:00").lte('created_at', `${targetMonth}-${String(lastDay).padStart(2, '0')}T23:59:59`);
            } else if (periodMode === 'year') {
                // Bug 4: เพิ่ม filter สำหรับ year mode
                const vNow = getVientianeNow();
                const yearStr = String(vNow.getFullYear());
                vQuery = vQuery.gte('created_at', yearStr + "-01-01T00:00:00").lte('created_at', yearStr + "-12-31T23:59:59");
            }

            const { data, error } = await vQuery.order('created_at', { ascending: false }).limit(200);
            if (data && data.length > 0) {
                visits = data;
                window.allVisitsCache = data;
            }
        }
    } catch (e) { }

    // Fallback: If DB query returned 0, use window.allBillsData or cached visits
    if (visits.length === 0 && window.allBillsData && window.allBillsData.length > 0) {
        visits = window.allBillsData.map(b => ({
            visit_id: b.visit_id,
            hn: b.hn,
            patient_name: b.patient_name,
            doctor_name: b.created_by || 'นพ. สมชาย ใจดี',
            symptom: 'ตรวจรักษาทั่วไป',
            payable_amount: b.payable_amount,
            total_price: b.subtotal,
            created_at: b.created_at,
            status: 'ชำระเงินแล้ว'
        }));
    } else if (visits.length === 0) {
        visits = window.allVisitsCache || [];
    }

    // Filter by period
    let filteredVisits = [...visits];
    if (periodMode === 'day') {
        let targetDate = dateInput && dateInput.value ? dateInput.value : '';
        if (!targetDate) {
            const now = new Date();
            targetDate = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
        }
        filteredVisits = filteredVisits.filter(v => {
            if (!v.created_at) return true;
            const d = new Date(v.created_at);
            const vDate = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
            return vDate === targetDate;
        });
    } else if (periodMode === 'month') {
        let targetMonth = monthInput && monthInput.value ? monthInput.value : '';
        if (!targetMonth) {
            const now = new Date();
            targetMonth = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
        }
        filteredVisits = filteredVisits.filter(v => {
            if (!v.created_at) return true;
            const d = new Date(v.created_at);
            const vMonth = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
            return vMonth === targetMonth;
        });
    }

    // Search query filter
    if (searchText) {
        filteredVisits = filteredVisits.filter(v =>
            (v.patient_name && v.patient_name.toLowerCase().includes(searchText)) ||
            (v.hn && v.hn.toLowerCase().includes(searchText)) ||
            (v.visit_id && v.visit_id.toLowerCase().includes(searchText)) ||
            (v.doctor_name && v.doctor_name.toLowerCase().includes(searchText))
        );
    }

    // Group visits by date (YYYY-MM-DD)
    const groupedByDate = new Map();
    filteredVisits.forEach(v => {
        const d = v.created_at ? new Date(v.created_at) : new Date();
        const dateKey = `${d.getDate()}/${d.getMonth() + 1}/${d.getFullYear() + 543}`;
        if (!groupedByDate.has(dateKey)) {
            groupedByDate.set(dateKey, []);
        }
        groupedByDate.get(dateKey).push(v);
    });

    let grandVisitsCount = filteredVisits.length;
    let grandDoctorFeeSum = 0;
    let grandServiceFeeSum = 0;
    let grandTotalCollected = 0;

    tbodySummary.innerHTML = '';

    if (groupedByDate.size === 0) {
        tbodySummary.innerHTML = '<tr><td colspan="7" class="text-center text-muted py-4">ไม่พบข้อมูลสรุปค่าตรวจรักษาในช่วงเวลานี้</td></tr>';
    } else {
        let rowIdx = 1;
        groupedByDate.forEach((dayVisits, dateKey) => {
            const visitsCount = dayVisits.length;
            let dayDoctorFee = 0;
            let dayServiceFee = 0;
            let dayTotalCollected = 0;

            dayVisits.forEach(v => {
                const totalVal = parseFloat(v.payable_amount || v.total_price || v.price || 0);
                const docFee = totalVal >= 200000 ? 200000 : totalVal;
                const srvFee = totalVal > 200000 ? (totalVal - 200000) : 0;

                dayDoctorFee += docFee;
                dayServiceFee += srvFee;
                dayTotalCollected += totalVal;
            });

            grandDoctorFeeSum += dayDoctorFee;
            grandServiceFeeSum += dayServiceFee;
            grandTotalCollected += dayTotalCollected;

            tbodySummary.innerHTML += `
                <tr>
                    <td class="ps-4 fw-bold text-muted" style="width: 50px;">${rowIdx++}</td>
                    <td class="fw-bold text-dark"><i class="ph ph-calendar me-1 text-primary"></i>${dateKey}</td>
                    <td class="text-center fw-semibold text-dark"><span class="badge bg-primary-subtle text-primary px-3 py-1 rounded-pill fs-6">${visitsCount} เคส</span></td>
                    <td class="text-end fw-semibold text-dark">${formatCommissionAmount(dayDoctorFee)}</td>
                    <td class="text-end fw-semibold text-dark">${formatCommissionAmount(dayServiceFee)}</td>
                    <td class="text-end fw-bold text-success fs-6">${formatCommissionAmount(dayTotalCollected)}</td>
                    <td class="text-center pe-4"><span class="badge bg-success-subtle text-success px-2.5 py-1 rounded-pill"><i class="bi bi-check-circle-fill me-1"></i>สมบูรณ์</span></td>
                </tr>
            `;
        });
    }

    // Update Top Summary Cards & Bottom Footer Bar
    if (document.getElementById('dailyReportTotalVisits')) document.getElementById('dailyReportTotalVisits').textContent = `${grandVisitsCount} เคส`;
    if (document.getElementById('dailyReportDoctorFee')) document.getElementById('dailyReportDoctorFee').textContent = formatCommissionAmount(grandDoctorFeeSum);
    if (document.getElementById('dailyReportServiceFee')) document.getElementById('dailyReportServiceFee').textContent = formatCommissionAmount(grandServiceFeeSum);
    if (document.getElementById('dailyReportGrandTotal')) document.getElementById('dailyReportGrandTotal').textContent = formatCommissionAmount(grandTotalCollected);

    if (document.getElementById('dailyFooterCount')) document.getElementById('dailyFooterCount').textContent = `${grandVisitsCount} เคส`;
    if (document.getElementById('dailyFooterDoctorFee')) document.getElementById('dailyFooterDoctorFee').textContent = formatCommissionAmount(grandDoctorFeeSum);
    if (document.getElementById('dailyFooterServiceFee')) document.getElementById('dailyFooterServiceFee').textContent = formatCommissionAmount(grandServiceFeeSum);
    if (document.getElementById('dailyFooterGrandTotal')) document.getElementById('dailyFooterGrandTotal').textContent = formatCommissionAmount(grandTotalCollected);

    // Render Detailed Table
    if (tbodyDetail) {
        tbodyDetail.innerHTML = '';
        if (filteredVisits.length === 0) {
            tbodyDetail.innerHTML = '<tr><td colspan="8" class="text-center text-muted py-4">ไม่พบประวัติการเข้าใช้บริการ</td></tr>';
        } else {
            filteredVisits.forEach((v, idx) => {
                const dateStr = v.created_at ? new Date(v.created_at).toLocaleString('th-TH', { dateStyle: 'short', timeStyle: 'short' }) : '-';
                const totalVal = parseFloat(v.payable_amount || v.total_price || v.price || 0);
                const statusBadge = (v.status === 'เสร็จสิ้น' || v.status === 'ชำระเงินแล้ว' || !v.status)
                    ? `<span class="badge bg-success-subtle text-success"><i class="bi bi-check-circle-fill me-1"></i>ชำระเงินแล้ว</span>`
                    : `<span class="badge bg-warning-subtle text-warning"><i class="bi bi-clock me-1"></i>${v.status}</span>`;

                tbodyDetail.innerHTML += `
                    <tr>
                        <td class="ps-4 text-muted fw-bold" style="width: 50px;">${idx + 1}</td>
                        <td class="small text-muted">${dateStr}</td>
                        <td class="fw-bold text-primary">${v.visit_id || '-'}</td>
                        <td class="fw-bold text-dark">${v.patient_name || '-'}<div class="text-muted extra-small">HN: ${v.hn || '-'}</div></td>
                        <td>${v.doctor_name || 'นพ. สมชาย ใจดี'}</td>
                        <td class="small text-muted">${v.symptom || v.diagnosis || 'ตรวจรักษาและบริการทั่วไป'}</td>
                        <td class="text-end fw-bold text-success fs-6">${formatCommissionAmount(totalVal)}</td>
                        <td class="text-center pe-4">${statusBadge}</td>
                    </tr>
                `;
            });
        }
    }

    if (isManualClick && typeof Swal !== 'undefined') {
        const Toast = Swal.mixin({
            toast: true,
            position: 'top-end',
            showConfirmButton: false,
            timer: 2000,
            timerProgressBar: true
        });
        Toast.fire({
            icon: 'success',
            title: 'รีเฟรชรายงานสรุปค่าตรวจสำเร็จ'
        });
    }
}

function exportDailyReportExcel() {
    if (!window.allVisitsCache || window.allVisitsCache.length === 0) {
        Swal.fire('ไม่มีข้อมูล', 'ไม่พบข้อมูลรายงานค่าตรวจสำหรับส่งออก Excel', 'warning');
        return;
    }

    let csvContent = "\uFEFF"; // UTF-8 BOM
    csvContent += "ลำดับ,วันที่/เวลา,รหัสเคส,HN,ชื่อผู้ป่วย,แพทย์ผู้ตรวจ,อาการ/รายการตรวจ,ยอดชำระเงิน,สถานะ\n";

    window.allVisitsCache.forEach((v, idx) => {
        const dateStr = v.created_at ? new Date(v.created_at).toLocaleString('th-TH') : '-';
        const totalVal = parseFloat(v.payable_amount || v.total_price || v.price || 0);

        csvContent += `${idx + 1},"${dateStr}","${v.visit_id || ''}","${v.hn || ''}","${(v.patient_name || '').replace(/"/g, '""')}","${(v.doctor_name || '').replace(/"/g, '""')}","${(v.symptom || '').replace(/"/g, '""')}",${totalVal},"${v.status || 'ชำระเงินแล้ว'}"\n`;
    });

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `รายงานสรุปค่าตรวจประจำวัน_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
}

function printDailyReport() {
    window.print();
}

window.loadDailyReport = loadDailyReport;
window.setDailyReportPeriod = setDailyReportPeriod;
window.exportDailyReportExcel = exportDailyReportExcel;
window.printDailyReport = printDailyReport;

// ============================================================
// รายงานสรุปค่าตรวจประจำวัน (Daily Examination Fee Summary Report) - ซิงค์ตรงกับ ระบบ Bill / ใบเสร็จรับเงิน 100%
// ============================================================
window.dailyExamCurrentPage = 1;
const DAILY_EXAM_PER_PAGE = 25;

function changeDailyExamPage(page) {
    if (typeof page === 'number' && !isNaN(page)) {
        window.dailyExamCurrentPage = page;
    }
    renderDailyExamReport();
}
window.changeDailyExamPage = changeDailyExamPage;

function onDailyExamDateChange() {
    window.dailyExamCurrentPage = 1;
    renderDailyExamReport();
}
window.onDailyExamDateChange = onDailyExamDateChange;

let dailyExamSearchTimer = null;
function debounceDailyExamSearch() {
    clearTimeout(dailyExamSearchTimer);
    dailyExamSearchTimer = setTimeout(() => {
        window.dailyExamCurrentPage = 1;
        renderDailyExamReport();
    }, 350);
}
window.debounceDailyExamSearch = debounceDailyExamSearch;

function getFilteredDailyExamBills() {
    const sInput = document.getElementById('dailyExamStartDate');
    const eInput = document.getElementById('dailyExamEndDate');

    // โหลดเฉพาะข้อมูลของ "วันปัจจุบัน" เป็นค่าเริ่มต้น
    const now = new Date();
    const todayStr = (typeof formatLocalDateYMD === 'function') ? formatLocalDateYMD(now) : now.toLocaleDateString('en-CA');
    if (sInput && !sInput.value) sInput.value = todayStr;
    if (eInput && !eInput.value) eInput.value = todayStr;

    const startDateVal = sInput?.value || '';
    const endDateVal = eInput?.value || '';
    const searchQuery = document.getElementById('searchDailyExamInput')?.value.toLowerCase().trim() || '';

    const startDate = startDateVal ? new Date(startDateVal + 'T00:00:00') : null;
    const endDate = endDateVal ? new Date(endDateVal + 'T23:59:59') : null;

    let bills = (window.allBillsData || []).slice();

    if (startDate || endDate) {
        bills = bills.filter(function (b) {
            const d = b.created_at ? new Date(b.created_at) : null;
            if (!d) return true;
            if (startDate && d < startDate) return false;
            if (endDate && d > endDate) return false;
            return true;
        });
    }

    if (searchQuery) {
        bills = bills.filter(function (b) {
            return (b.bill_id || '').toLowerCase().includes(searchQuery) ||
                (b.visit_id || '').toLowerCase().includes(searchQuery) ||
                (b.patient_name || '').toLowerCase().includes(searchQuery) ||
                (b.hn || '').toLowerCase().includes(searchQuery);
        });
    }

    return bills;
}

function calculateBillPayableAmount(b) {
    let labItems = (Array.isArray(b.items) ? b.items : []).filter(item => item.type !== 'med');
    let itemsTotal = 0;
    labItems.forEach(function (item) {
        let price = parseFloat(item.price || 0);
        if (price === 0 && typeof getTestItemDetails === 'function') {
            const details = getTestItemDetails(item.name);
            if (details && details.price > 0) price = details.price;
        }
        itemsTotal += price * (parseInt(item.qty || 1));
    });

    let subtotal = itemsTotal > 0 ? itemsTotal : parseFloat(b.subtotal || b.payable_amount || 0);
    let discount = parseFloat(b.discount || 0);
    let payable = b.payable_amount !== undefined && b.payable_amount > 0 ? parseFloat(b.payable_amount) : Math.max(0, subtotal - discount);
    return payable;
}

function renderDailyExamReport() {
    const tbody = document.querySelector('#dailyExamTable tbody');
    if (!tbody) return;

    if (!window.allBillsData || window.allBillsData.length === 0) {
        if (typeof loadBills === 'function') {
            loadBills().then(() => renderDailyExamReport());
            return;
        }
    }

    const bills = getFilteredDailyExamBills();

    tbody.innerHTML = '';

    const totalItems = bills.length;

    if (totalItems === 0) {
        tbody.innerHTML = '<tr><td colspan="6" class="text-center text-muted py-5"><i class="ph ph-receipt fs-2 text-primary opacity-25 d-block mb-2"></i>ไม่พบข้อมูลรายงานสรุปค่าตรวจประจำวัน</td></tr>';
        if (document.getElementById('dailyExamFooterCount')) document.getElementById('dailyExamFooterCount').textContent = '0 รายการ';
        if (document.getElementById('dailyExamFooterService')) document.getElementById('dailyExamFooterService').textContent = '₭0';
        const paginationContainer = document.getElementById('dailyExamPaginationContainer');
        if (paginationContainer) paginationContainer.innerHTML = '';
        return;
    }

    let totalServiceSum = 0;
    bills.forEach(b => {
        totalServiceSum += calculateBillPayableAmount(b);
    });

    if (document.getElementById('dailyExamFooterCount')) document.getElementById('dailyExamFooterCount').textContent = `${totalItems} รายการ`;
    if (document.getElementById('dailyExamFooterService')) document.getElementById('dailyExamFooterService').textContent = `₭${totalServiceSum.toLocaleString()}`;

    // คำนวณ Pagination (25 รายการต่อหน้า)
    const totalPages = Math.ceil(totalItems / DAILY_EXAM_PER_PAGE) || 1;
    if (!window.dailyExamCurrentPage || window.dailyExamCurrentPage < 1) window.dailyExamCurrentPage = 1;
    if (window.dailyExamCurrentPage > totalPages) window.dailyExamCurrentPage = totalPages;
    const currentPage = window.dailyExamCurrentPage;

    const startIndex = (currentPage - 1) * DAILY_EXAM_PER_PAGE;
    const endIndex = Math.min(startIndex + DAILY_EXAM_PER_PAGE, totalItems);
    const pageBills = bills.slice(startIndex, endIndex);

    let rowsHtml = '';
    pageBills.forEach((b, index) => {
        const d = b.created_at ? new Date(b.created_at) : new Date();
        const dateStr = `${d.getDate()}/${d.getMonth() + 1}/${d.getFullYear() + 543}`;

        const payable = calculateBillPayableAmount(b);
        const examName = b.patient_name && b.patient_name !== '-' ? `ตรวจรักษาทั่วไป (${b.patient_name})` : 'ตรวจรักษาทั่วไป';
        const qty = 1;

        rowsHtml += `
            <tr>
                <td class="ps-4 fw-bold text-muted" style="width: 60px;">${startIndex + index + 1}</td>
                <td class="fw-bold text-dark">${dateStr}</td>
                <td class="fw-bold text-dark">${examName}</td>
                <td class="text-end fw-semibold text-dark">₭${payable.toLocaleString()}</td>
                <td class="text-center fw-bold text-secondary">${qty}</td>
                <td class="text-end pe-4 fw-bold text-primary fs-6">₭${payable.toLocaleString()}</td>
            </tr>
        `;
    });
    tbody.innerHTML = rowsHtml;

    // Render Pagination Controls (แสดงครั้งละ 25 รายการ)
    const paginationContainer = document.getElementById('dailyExamPaginationContainer');
    if (paginationContainer) {
        const startDisplay = startIndex + 1;
        const endDisplay = endIndex;

        let pagHtml = `
            <div class="d-flex justify-content-between align-items-center w-100 px-2 flex-wrap gap-2">
                <div class="text-muted small fw-semibold">
                    แสดง <strong class="text-dark">${startDisplay} - ${endDisplay}</strong> จากทั้งหมด <strong class="text-dark">${totalItems}</strong> รายการ
                </div>
                <div class="d-flex justify-content-center align-items-center gap-1 flex-wrap">
        `;

        if (totalPages > 1) {
            // ปุ่มย้อนกลับ
            pagHtml += `
                <button type="button" class="btn btn-sm btn-light border text-muted px-2.5 py-1 rounded-2" onclick="changeDailyExamPage(${currentPage - 1})" ${currentPage === 1 ? 'disabled' : ''} style="font-size: 0.82rem;" title="หน้าก่อนหน้า">
                    <i class="bi bi-chevron-left"></i>
                </button>
            `;

            // ปุ่มเลขหน้า 1, 2, 3...
            for (let i = 1; i <= totalPages; i++) {
                if (i === 1 || i === totalPages || (i >= currentPage - 2 && i <= currentPage + 2)) {
                    const activeClass = (i === currentPage)
                        ? 'btn-primary text-white fw-bold shadow-xs'
                        : 'btn-light border text-dark';
                    pagHtml += `<button type="button" class="btn btn-sm ${activeClass} px-3 py-1 rounded-2" onclick="changeDailyExamPage(${i})" style="font-size: 0.82rem; min-width: 34px;">${i}</button>`;
                } else if (i === currentPage - 3 || i === currentPage + 3) {
                    pagHtml += `<span class="px-2 text-muted small">...</span>`;
                }
            }

            // ปุ่มหน้าถัดไป
            pagHtml += `
                <button type="button" class="btn btn-sm btn-light border text-muted px-2.5 py-1 rounded-2" onclick="changeDailyExamPage(${currentPage + 1})" ${currentPage === totalPages ? 'disabled' : ''} style="font-size: 0.82rem;" title="หน้าถัดไป">
                    <i class="bi bi-chevron-right"></i>
                </button>
            `;
        }

        pagHtml += `
                </div>
                <div class="text-muted small fw-semibold text-end d-none d-md-block" style="min-width: 140px;">
                    หน้า <strong class="text-primary">${currentPage}</strong> / <strong class="text-dark">${totalPages}</strong>
                </div>
            </div>
        `;
        paginationContainer.innerHTML = pagHtml;
    }
}

function exportDailyExamExcel() {
    let csvContent = "\uFEFF";
    csvContent += "ลำดับ,วันที่ทำรายการ,รายการตรวจ,ราคา,จำนวน,รวมราคา\n";

    const bills = getFilteredDailyExamBills();
    bills.forEach((b, index) => {
        const d = b.created_at ? new Date(b.created_at) : new Date();
        const dateStr = `${d.getDate()}/${d.getMonth() + 1}/${d.getFullYear() + 543}`;
        const payable = calculateBillPayableAmount(b);
        const examName = b.patient_name && b.patient_name !== '-' ? `ตรวจรักษาทั่วไป (${b.patient_name})` : 'ตรวจรักษาทั่วไป';

        csvContent += `${index + 1},"${dateStr}","${examName.replace(/"/g, '""')}",${payable},1,${payable}\n`;
    });

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `รายงานสรุปค่าตรวจประจำวัน_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
}

